    "q.l7#11.e" to "Крик нужен, чтобы нижние немедленно подняли голову и укрылись. Звук важнее объяснений, короткий повтор важнее длинной фразы.",
    "q.l7#12.p" to "Один в связке сорвался. Что делают остальные?",
    "q.l7#12.o0" to "Немедленно тормозят и держат верёвку натянутой, не двигаясь одновременно",
    "q.l7#12.o1" to "Все бегут к нему",
    "q.l7#12.o2" to "Отпускают верёвку",
    "q.l7#12.o3" to "Садятся на месте",
    "q.l7#12.e" to "Одновременное движение лишает верёвку натяжения, и упавший продолжает скользить. Первый шаг торможения — удержать себя.",
    "q.l7#13.p" to "Падение остановлено, но верёвка остаётся натянутой. Что правильно?",
    "q.l7#13.o0" to "Держать натяжение, сначала организовать страховку, потом подходить",
    "q.l7#13.o1" to "Сразу ослабить верёвку",
    "q.l7#13.o2" to "Пусть выбирается сам",
    "q.l7#13.o3" to "Перерезать верёвку",
    "q.l7#13.e" to "Ослабление может дать повторное скольжение. Сначала закрепиться самому, потом думать о спасении.",
    "q.l7#14.p" to "Почему кошки при срыве могут сами нанести травму?",
    "q.l7#14.o0" to "Зубья цепляются за снег или одежду, что приводит к выкручиванию или резкой остановке",
    "q.l7#14.o1" to "Потому что тяжёлые",
    "q.l7#14.o2" to "Потому что слетают",
    "q.l7#14.o3" to "Потому что стираются",
    "q.l7#14.e" to "При срыве нога внезапно зацепляется зубьями, и тело разворачивается вокруг сустава. Именно поэтому важна поза: ногами вниз, колени согнуты.",
    "q.l7#15.p" to "Почему большинство аварий случается на спуске?",
    "q.l7#15.o0" to "Усталость, снижение внимания и ощущение, что главное уже сделано",
    "q.l7#15.o1" to "Темнеет",
    "q.l7#15.o2" to "Снаряжение изношено",
    "q.l7#15.o3" to "Маршрут стал сложнее",
    "q.l7#15.e" to "Рельеф на спуске часто более открытый, а бдительность самая низкая. Планировать спуск как вторую половину маршрута — необходимость.",
    "q.l8#10.p" to "Какая поза рекомендуется при спуске по довольно крутому твёрдому снежному склону?",
    "q.l8#10.o0" to "Лицом к склону, в три точки опоры, постепенно смещаясь вниз",
    "q.l8#10.o1" to "Лицом наружу, быстрым шагом",
    "q.l8#10.o2" to "Скольжением",
    "q.l8#10.o3" to "Прыжками",
    "q.l8#10.e" to "Лицом к склону ледоруб всегда готов к торможению. Положение лицом наружу годится только для пологих участков и мягкого снега.",
    "q.l8#11.p" to "Как готовят торможение при контролируемом скольжении вниз?",
    "q.l8#11.o0" to "Ледоруб всё время в положении, из которого можно вдавить его и остановиться",
    "q.l8#11.o1" to "Убрать ледоруб в рюкзак",
    "q.l8#11.o2" to "Развести руки",
    "q.l8#11.o3" to "Закрыть глаза",
    "q.l8#11.e" to "Удовольствие от скольжения держится на возможности остановиться в любой момент. При неверной позе или слишком твёрдом снеге скольжение превращается в срыв.",
    "q.l8#12.p" to "Что обязательно проверяют перед спуском по верёвке?",
    "q.l8#12.o0" to "Точку, узлы, концы верёвки, направление заправки спускового устройства, резерв",
    "q.l8#12.o1" to "Только точку",
    "q.l8#12.o2" to "Только длину верёвки",
    "q.l8#12.o3" to "Только напарника",
    "q.l8#12.e" to "Почти все аварии на спуске приходятся на один из этих пяти пунктов. Проговорить их по порядку надёжнее, чем решить, что всё в порядке.",
    "q.l8#13.p" to "Где при спуске выше всего риск получить камнем сверху?",
    "q.l8#13.o0" to "Прямо под верёвкой",
    "q.l8#13.o1" to "В стороне, в трёх метрах",
    "q.l8#13.o2" to "Рядом с точкой",
    "q.l8#13.o3" to "За площадкой",
    "q.l8#13.e" to "Прямо под верёвкой идёт основной путь камней. При спуске старайтесь смещаться в сторону и быстро проходить край площадки.",
    "q.l8#14.p" to "Почему не удаётся вытянуть верёвку после спуска на двойной?",
    "q.l8#14.o0" to "На конце завязан узел, верёвка заклинилась в щели или ветви разной длины",
    "q.l8#14.o1" to "Верёвка слишком старая",
    "q.l8#14.o2" to "Спусковое слишком маленькое",
    "q.l8#14.o3" to "Точка слишком высоко",
    "q.l8#14.e" to "Перед вытягиванием проверяют: на конце нет узла, ничего не зацепилось, обе ветви одной длины. Если заклинило, сначала меняют угол, а не тянут силой.",
    "q.l8#15.p" to "Зачем на конце верёвки вяжут узел при спуске?",
    "q.l8#15.o0" to "Чтобы конец не выскользнул из спускового и не привёл к падению",
    "q.l8#15.o1" to "Чтобы удобнее собирать верёвку",
    "q.l8#15.o2" to "Чтобы отметить длину",
    "q.l8#15.o3" to "Чтобы меньше изнашивалась",
    "q.l8#15.e" to "Если верёвки не хватает, выскользнувший конец означает мгновенную потерю торможения. Этот узел почти ничего не стоит, но делит многие истории на до и после.",
    "q.l9#10.p" to "В чём преимущество восьмёрки перед простым узлом?",
    "q.l9#10.o0" to "После нагрузки её сравнительно легко развязать, а структура хорошо читается при проверке",
    "q.l9#10.o1" to "Она меньше",
    "q.l9#10.o2" to "Экономит верёвку",
    "q.l9#10.o3" to "Не требует контрольного узла",
    "q.l9#10.e" to "Простой узел после нагрузки затягивается намертво, и в поле его трудно развязать. Восьмёрка разбирается и под нагрузкой, поэтому стала стандартным узлом для привязывания.",
    "q.l9#11.p" to "Куда обычно вяжут контрольный узел?",
    "q.l9#11.o0" to "На конце верёвки, чтобы конец не выскользнул из снаряжения",
    "q.l9#11.o1" to "В середине",
    "q.l9#11.o2" to "На точке",
    "q.l9#11.o3" to "На кольце обвязки",
    "q.l9#11.e" to "Конец может выскользнуть при спуске, на страховке и при подъёме вторым. Контрольный узел это последняя механическая страховка.",
    "q.l9#12.p" to "Для чего в основном служит двойной рыбацкий узел?",
    "q.l9#12.o0" to "Для соединения двух верёвок близкого диаметра",
    "q.l9#12.o1" to "Для привязывания верёвки к обвязке",
    "q.l9#12.o2" to "Для схватывающего узла",
    "q.l9#12.o3" to "Для закрепления на точке",
    "q.l9#12.e" to "Он компактен и хорошо проходит через перегибы, поэтому годится для репшнура и стропы. Но после нагрузки развязывается трудно, поэтому концы оставляют длинными.",
    "q.l9#13.p" to "Что нужно делать после любого завязанного узла?",
    "q.l9#13.o0" to "Проверить схему и длину концов и проговорить проверку по пунктам",
    "q.l9#13.o1" to "Достаточно дёрнуть",
    "q.l9#13.o2" to "Сфотографировать",
    "q.l9#13.o3" to "Натереть воском",
    "q.l9#13.e" to "Завязал правильно и закончил вязать это разные вещи. Слишком короткий конец выскользнет под нагрузкой, поэтому проверка должна быть обязательным действием.",
    "q.l9#14.p" to "Почему место узла становится слабым звеном системы?",
    "q.l9#14.o0" to "Из-за изгиба верёвки её прочность заметно падает",
    "q.l9#14.o1" to "Потому что узел тяжёлый",
    "q.l9#14.o2" to "Из-за цвета",
    "q.l9#14.o3" to "Из-за трения и нагрева",
    "q.l9#14.e" to "В узле верёвка изгибается, и нагрузка распределяется неравномерно. Узел ставят туда, где нагрузка ниже, а не в ключевую несущую точку.",
    "q.l9#15.p" to "Какое свойство схватывающего узла самое важное?",
    "q.l9#15.o0" to "Под нагрузкой держит основную верёвку, без нагрузки сдвигается: работает как односторонний резерв",
    "q.l9#15.o1" to "Всегда намертво затянут",
    "q.l9#15.o2" to "Чем толще, тем лучше",
    "q.l9#15.o3" to "Только для спуска",
    "q.l9#15.e" to "Ценность схватывающего в односторонности: под нагрузкой стопорит, без нагрузки двигается. Поэтому он годится и для резерва, и для подъёма.",
    "q.l10#10.p" to "Что означает обратная продувка, которую проверяют после надевания обвязки?",
    "q.l10#10.o0" to "Продет ли конец ремня через оба кольца и остался ли достаточный хвост",
    "q.l10#10.o1" to "Закрыта ли муфта карабина",
    "q.l10#10.o2" to "Затянут ли узел",
    "q.l10#10.o3" to "Застёгнута ли каска",
    "q.l10#10.e" to "Недоправленная продувка самая частая ошибка новичков: снаружи выглядит надето, а под нагрузкой расходится.",
    "q.l10#11.p" to "Что делать с концом верёвки при движении в связке?",
    "q.l10#11.o0" to "Закрепить на верёвочной сумке или на себе, чтобы не волочился",
    "q.l10#11.o1" to "Пусть волочится по снегу",
    "q.l10#11.o2" to "Полностью размотать",
    "q.l10#11.o3" to "Намотать на руку",
    "q.l10#11.e" to "Волочащийся конец цепляется за кошки, камни и снежные мосты, а при срыве превращается в подсечку. Убрать его базовая дисциплина.",
    "q.l10#12.p" to "Почему интервал в связке не должен быть слишком коротким?",
    "q.l10#12.o0" to "При падении одного в трещину напарника затянет следом, и для спасения не останется места",
    "q.l10#12.o1" to "Не хватит верёвки",
    "q.l10#12.o2" to "Так медленнее идти",
    "q.l10#12.o3" to "Некрасиво",
    "q.l10#12.e" to "Интервал это дистанция реакции. Слишком короткий связывает двоих в один груз, слишком длинный усложняет торможение и связь.",
    "q.l10#13.p" to "Что нужно организовать в первую очередь при переходе от движения в связке к страховке лидера?",
    "q.l10#13.o0" to "Надёжную станцию и самостраховку",
    "q.l10#13.o1" to "Верёвку",
    "q.l10#13.o2" to "Связь",
    "q.l10#13.o3" to "Фотографии",
    "q.l10#13.e" to "Переход самая аварийная фаза: человек оказывается и не в связке, и ещё без страховки. Сначала станция, потом развязывание.",
    "q.l10#14.p" to "Когда связка, наоборот, повышает риск?",
    "q.l10#14.o0" to "На пологом склоне без риска падения узлы и интервалы добавляют спотыканий и сложностей в связи",
    "q.l10#14.o1" to "Всегда",
    "q.l10#14.o2" to "Когда есть трещины",
    "q.l10#14.o3" to "На спуске",
    "q.l10#14.e" to "Связка это инструмент против падения и трещин. В неподходящем месте хлопот от неё больше, чем пользы.",
    "q.l10#15.p" to "Что группе нужно согласовать до выхода в связке?",
    "q.l10#15.o0" to "Интервалы, команды, порядок прохождения трещин и сигналы остановки",
    "q.l10#15.o1" to "Марки снаряжения",
    "q.l10#15.o2" to "Скорость движения",
    "q.l10#15.o3" to "Кто фотографирует",
    "q.l10#15.e" to "Надёжность связки держится на согласованности реакции. Без единых команд первый же неожиданный случай превращается в хаос.",
    "q.m07#12.p" to "Куда должна смотреть муфта карабина на станции?",
    "q.m07#12.o0" to "От стены, в стороне от трения и направления нагрузки, чтобы её не выбило верёвкой или углом",
    "q.m07#12.o1" to "Вверх",
    "q.m07#12.o2" to "Вниз",
    "q.m07#12.o3" to "Куда получится",
    "q.m07#12.e" to "Выбитая муфта реальный способ отказа. Неверное направление означает, что надёжность отдана случаю.",
    "q.m07#13.p" to "Почему стропу нельзя перегибать через острый угол при соединении двух точек?",
    "q.m07#13.o0" to "Острая кромка надрезает стропу, и под нагрузкой прочность резко падает",
    "q.m07#13.o1" to "Некрасиво",
    "q.m07#13.o2" to "Будет скользить",
    "q.m07#13.o3" to "Слишком коротко",
    "q.m07#13.e" to "Один небольшой надрез может снять половину прочности. Если обойти угол нельзя, ставят протектор или удлиняют цепью.",
    "q.m07#14.p" to "Под каким углом обычно вкручивают ледобур?",
    "q.m07#14.o0" to "Слегка вверх, примерно на 10–15°, против направления нагрузки",
    "q.m07#14.o1" to "Строго горизонтально",
    "q.m07#14.o2" to "Наклоном вниз",
    "q.m07#14.o3" to "Как получится",
    "q.m07#14.e" to "Небольшой наклон вверх работает по направлению нагрузки: тело ледобура прижимается ко льду, а не вырывается. На плохом льду берут длиннее и с большим наклоном.",
    "q.m07#15.p" to "Что делать, если у станции только одна точка?",
    "q.m07#15.o0" to "Добавить независимый резерв или перейти на более надёжный рельеф",
    "q.m07#15.o1" to "Пользоваться как есть",
    "q.m07#15.o2" to "Навесить больше карабинов",
    "q.m07#15.o3" to "Укоротить верёвку",
    "q.m07#15.e" to "Количество карабинов не равно резервированию. Резерв начинается там, где причины отказа разные.",
    "q.m08#12.p" to "Что важнее всего планировать заранее на вершинах около 5 000 м, таких как Ганьшика и Хаба?",
    "q.m08#12.o0" to "Ритм акклиматизации и погодное окно, а не техническую сложность",
    "q.m08#12.o1" to "Закупку снаряжения",
    "q.m08#12.o2" to "Точки для съёмки",
    "q.m08#12.o3" to "Распределение ролей",
    "q.m08#12.e" to "Сложность пятитысячников обычно в высоте и погоде, а не в технике. Время, отданное акклиматизации, выгоднее, чем ещё один отработанный приём.",
    "q.m08#13.p" to "Как правильно поступать с разрешениями и требованием гида?",
    "q.m08#13.o0" to "Заранее уточнить местные правила и строго выполнять требования по гиду и регистрации",
    "q.m08#13.o1" to "Спросить уже на месте",
    "q.m08#13.o2" to "Обойти контрольно-пропускной пункт",
    "q.m08#13.o3" to "Договориться по знакомству",
    "q.m08#13.e" to "Многие вершины около 5 000 м требуют регистрации или гида. Восхождение без разрешения одновременно лишает и спасения, и страховки.",
    "q.m08#14.p" to "В чём логика пути от третьей вершины к главной?",
    "q.m08#14.o0" to "Сначала проверить акклиматизацию и силы на более простом маршруте, потом добавлять технику",
    "q.m08#14.o1" to "Потому что дешевле",
    "q.m08#14.o2" to "Потому что ближе",
    "q.m08#14.o3" to "Потому что там больше людей",
    "q.m08#14.e" to "Смысл постепенности в том, чтобы за раз менять только одну переменную. Когда высота и техника растут одновременно, при сбое непонятно, что именно виновато.",
    "q.m08#15.p" to "Какую информацию о путях отхода нужно уточнить до выхода?",
    "q.m08#15.o0" to "Путь спуска, места запасных лагерей, ближайший медицинский пункт и контакты",
    "q.m08#15.o1" to "Только путь спуска",
    "q.m08#15.o2" to "Только медицинский пункт",
    "q.m08#15.o3" to "Ничего не нужно",
    "q.m08#15.e" to "Отход это не просто пойти назад. При ухудшении погоды единственным выполнимым вариантом может оказаться ближайший запасной лагерь.",
    "q.l13#14.p" to "Через сколько обычно появляются симптомы AMS после подъёма на высоту?",
    "q.l13#14.o0" to "Через 6–12 часов",
    "q.l13#14.o1" to "Сразу",
    "q.l13#14.o2" to "Через 3 дня",
    "q.l13#14.o3" to "Через неделю",
    "q.l13#14.e" to "Это окно важно: день подъёма, с послеполуденных часов до ночи, является периодом наблюдения, и именно поэтому нельзя продолжать набор высоты.",
    "q.l13#15.p" to "Что главное отличает AMS от HACE?",
    "q.l13#15.o0" to "Появилась ли атаксия или изменение сознания",
    "q.l13#15.o1" to "Сила головной боли",
    "q.l13#15.o2" to "Есть ли тошнота",
    "q.l13#15.o3" to "Частота пульса",
    "q.l13#15.e" to "Головная боль и тошнота при AMS обычны; как только походка стала неустойчивой или сознание помутилось, действуют как при HACE и немедленно спускаются.",
    "q.l13#16.p" to "Можно ли продолжать подъём, если симптомы AMS прошли за 24 часа?",
    "q.l13#16.o0" to "Можно, но темп нужно замедлить и внимательно наблюдать",
    "q.l13#16.o1" to "Можно подниматься как угодно",
    "q.l13#16.o2" to "Подниматься нельзя больше никогда",
    "q.l13#16.o3" to "Нужно спуститься на 1 000 м",
    "q.l13#16.e" to "Полное исчезновение симптомов говорит о прогрессе акклиматизации. Но темп должен быть осторожнее, и при повторении симптомов подъём прекращают.",
    "q.l13#17.p" to "Что легко принять за AMS?",
    "q.l13#17.o0" to "Обезвоживание, простуду и недосып",
    "q.l13#17.o1" to "Перелом",
    "q.l13#17.o2" to "Обморожение",
    "q.l13#17.o3" to "Снежную слепоту",
    "q.l13#17.e" to "Симптомы этих трёх состояний перекрываются с AMS. Если после питья и отдыха заметно легчает, это скорее не AMS; если не легчает или хуже, ведут как AMS.",
    "q.l13#18.p" to "Что нужно учитывать, давая обезболивающее при AMS?",
    "q.l13#18.o0" to "Обезболивающее только скрывает симптомы и не может быть основанием для продолжения подъёма",
    "q.l13#18.o1" to "Выпил и можно подниматься",
    "q.l13#18.o2" to "Дозу можно увеличить",
    "q.l13#18.o3" to "Применять нельзя вообще",
    "q.l13#18.e" to "Обезболивающее убирает сигнал, но болезнь продолжается. Подъём после маскировки симптомов самый частый путь к ухудшению.",
    "q.l13#19.p" to "Почему у детей и пожилых горную болезнь чаще пропускают?",
    "q.l13#19.o0" to "Они хуже описывают симптомы, и изменение поведения появляется раньше жалоб",
    "q.l13#19.o1" to "Потому что они нечувствительны",
    "q.l13#19.o2" to "Потому что быстро акклиматизируются",
    "q.l13#19.o3" to "Потому что редко бывают в горах",
    "q.l13#19.e" to "Дети становятся вялыми, капризными, отказываются от еды; пожилые могут выглядеть просто без сил. Наблюдать за поведением надёжнее, чем ждать жалоб.",
    "q.l14#12.p" to "Каков простейший тест на атаксию при HACE на месте?",
    "q.l14#12.o0" to "Пройти по прямой линии, ставя пятку к носку",
    "q.l14#12.o1" to "Постоять на одной ноге",
    "q.l14#12.o2" to "Сделать приседание",
    "q.l14#12.o3" to "Попрыгать на месте",
    "q.l14#12.e" to "Неспособность идти по прямой, шаткая походка — тест положительный. Он не требует оборудования, его может провести любой, поэтому он годится для повседневного контроля.",
    "q.l14#13.p" to "Как обычно развивается кашель при HAPE?",
    "q.l14#13.o0" to "От сухого переходит в пенистую мокроту, переносимость нагрузки резко падает",
    "q.l14#13.o1" to "От мокроты переходит в сухой",
    "q.l14#13.o2" to "Не меняется",
    "q.l14#13.o3" to "Появляется только ночью",
    "q.l14#13.e" to "Пенистая мокрота вместе с одышкой в покое — типичное сочетание для HAPE. К моменту, когда появляется розовая пенистая мокрота, состояние обычно уже тяжёлое.",
    "q.l14#14.p" to "На каком этапе похода HAPE встречается чаще?",
    "q.l14#14.o0" to "В первую-вторую ночь после подъёма",
    "q.l14#14.o1" to "До выхода на маршрут",
    "q.l14#14.o2" to "На спуске",
    "q.l14#14.o3" to "После возвращения на равнину",
    "q.l14#14.e" to "Ночью гипоксия наиболее выражена, поэтому HAPE часто проявляется во вторую ночь. Именно поэтому «первой ночи» уделяют особое внимание.",
    "q.l14#15.p" to "При подозрении на HACE или HAPE каков порядок действий?",
    "q.l14#15.o0" to "Немедленный спуск и кислород, лекарства — вспомогательное средство",
    "q.l14#15.o1" to "Сначала принять лекарство и наблюдать",
    "q.l14#15.o2" to "Сначала переночевать",
    "q.l14#15.o3" to "Сначала ждать спасателей",
    "q.l14#15.e" to "Спуск — единственная мера, которая надёжно разворачивает течение болезни. Лекарства и кислород нужны, чтобы выиграть время на спуск.",
    "q.l14#16.p" to "Каково назначение и ограничение барокамеры (мешка Гамова)?",
    "q.l14#16.o0" to "Имитирует спуск и выигрывает время, но не заменяет настоящий спуск",
    "q.l14#16.o1" to "Полностью излечивает",
    "q.l14#16.o2" to "Можно применять длительно",
    "q.l14#16.o3" to "Только для тех, кто в сознании",
    "q.l14#16.e" to "Мешок — это переносная малая высота: нужен оператор, расходует силы, объём ограничен. Это переходная мера, а не конечная точка.",
    "q.l14#17.p" to "Если во время похода случился HAPE, после восстановления следует?",
    "q.l14#17.o0" to "В этом походе больше не подниматься, организовать спуск",
    "q.l14#17.o1" to "Отдохнуть два дня и продолжить подъём",
    "q.l14#17.o2" to "Сменить маршрут и идти дальше",
    "q.l14#17.o3" to "Продолжать на половинной дозе",
    "q.l14#17.e" to "Риск повторного HAPE высок, а второй эпизод может развиться быстрее и тяжелее. Это восхождение должно быть закончено.",
    "q.l14#18.p" to "Что конкретно включает «изменение сознания» при HACE?",
    "q.l14#18.o0" to "Сонливость, невпопадные ответы, странное поведение, галлюцинации",
    "q.l14#18.o1" to "Только кома",
    "q.l14#18.o2" to "Только головная боль",
    "q.l14#18.o3" to "Только тошнота",
    "q.l14#18.e" to "На ранней стадии это может быть просто «тише обычного» или «повторяет одно и то же». Партнёры замечают это раньше самого человека, поэтому нужно наблюдать друг за другом.",
    "q.l14#19.p" to "Почему HAPE и HACE могут возникать одновременно?",
    "q.l14#19.o0" to "Оба — проявления тяжёлой высотной болезни, патологически могут сосуществовать",
    "q.l14#19.o1" to "Потому что лечение одинаковое",
    "q.l14#19.o2" to "Потому что симптомы похожи",
    "q.l14#19.o3" to "Они не возникают одновременно",
    "q.l14#19.e" to "В клинике часто встречаются случаи HACE вместе с HAPE. Принцип действий один: спуск, кислород, при необходимости лекарства.",
    "q.l15#12.p" to "Что в процессе акклиматизации меняется первым?",
    "q.l15#12.o0" to "Увеличивается вентиляция: дыхание становится глубже и чаще",
    "q.l15#12.o1" to "Растёт число эритроцитов",
    "q.l15#12.o2" to "Укрепляются мышцы",
    "q.l15#12.o3" to "Снижается пульс",
    "q.l15#12.e" to "Вентиляция увеличивается уже в первые часы, а эритроцитов становится больше за дни и недели. Поэтому первая ночь — самая тяжёлая.",
    "q.l15#13.p" to "Почему алкоголь и седативные препараты усугубляют высотную болезнь?",
    "q.l15#13.o0" to "Они подавляют дыхательный драйв и усиливают ночную гипоксию",
    "q.l15#13.o1" to "Потому что вызывают обезвоживание",
    "q.l15#13.o2" to "Потому что раздражают желудок",
    "q.l15#13.o3" to "Потому что мешают сну",
    "q.l15#13.e" to "На высоте дыхательный драйв и без того ослаблен, а эти вещества подавляют его ещё сильнее. Кроме того, состояние опьянения легко спутать с ранней стадией HACE.",
    "q.l15#14.p" to "Периодическое дыхание часто встречается ночью на высоте. Каков его механизм?",
    "q.l15#14.o0" to "Гипоксия вызывает гипервентиляцию, затем слишком низкий CO2 приводит к апноэ, и цикл повторяется",
    "q.l15#14.o1" to "Обструкция дыхательных путей",
    "q.l15#14.o2" to "Проблема с сердцем",
    "q.l15#14.o3" to "Психологический эффект",
    "q.l15#14.e" to "Это физиологично, паниковать не нужно. Но оно прерывает сон, и это одна из причин спать пониже.",
    "q.l15#15.p" to "Что НЕ относится к ранним признакам плохой акклиматизации?",
    "q.l15#15.o0" to "Аппетит улучшился, сон стал лучше",
    "q.l15#15.o1" to "Постоянная головная боль",
    "q.l15#15.o2" to "Частые ночные пробуждения с нехваткой воздуха",
    "q.l15#15.o3" to "Снижение переносимости нагрузки",
    "q.l15#15.e" to "Ест с аппетитом, спит хорошо, идёт нормально — три признака хорошей акклиматизации. Если всё наоборот, темп нужно снизить.",
    "q.l15#16.p" to "Насколько убедительны данные об интервальной гипоксической тренировке как преакклиматизации?",
    "q.l15#16.o0" to "Определённый физиологический эффект есть, но она не заменяет акклиматизацию на месте",
    "q.l15#16.o1" to "Полностью заменяет акклиматизацию",
    "q.l15#16.o2" to "Совершенно бесполезна",
    "q.l15#16.o3" to "Работает только у спортсменов",
    "q.l15#16.e" to "Преакклиматизация может немного сократить время адаптации, но скорость подъёма и высота сна остаются определяющими. Не считайте её коротким путём.",
    "q.l15#17.p" to "Главный риск подъёма на высоту с недолеченной простудой?",
    "q.l15#17.o0" to "Воспаление дыхательных путей повышает риск HAPE",
    "q.l15#17.o1" to "Можно заразить партнёров",
    "q.l15#17.o2" to "Простуда усилится",
    "q.l15#17.o3" to "Никакого влияния",
    "q.l15#17.e" to "Это самый недооценённый пункт. Подъём через силу с простудой, которую считают мелочью, — частая причина HAPE.",
    "q.l15#18.p" to "Как следует использовать день отдыха в период акклиматизации?",
    "q.l15#18.o0" to "Оставаться на той же высоте, больше спать и есть, а не лежать полностью без движения",
    "q.l15#18.o1" to "Полностью лежать в постели",
    "q.l15#18.o2" to "Продолжать подъём",
    "q.l15#18.o3" to "Спуститься отдыхать",
    "q.l15#18.e" to "Лёгкая активность помогает вентиляции и кровообращению. Полный покой, наоборот, замедляет акклиматизацию и снижает аппетит.",
    "q.l15#19.p" to "Почему говорят, что сам план похода и есть профилактика?",
    "q.l15#19.o0" to "Скорость подъёма и высота сна определяют большую часть риска, поэтому изменить план важнее, чем принимать таблетки",
    "q.l15#19.o1" to "Потому что план легко написать",
    "q.l15#19.o2" to "Потому что лекарства дорогие",
    "q.l15#19.o3" to "Потому что так требует гид",
    "q.l15#19.e" to "Кто закладывает дни акклиматизации в план, редко нуждается в лекарствах; кто расписывает график плотно, обычно держится на таблетках.",
    "q.l16#12.p" to "Какой примерно температуре ядра соответствует лёгкая степень переохлаждения?",
    "q.l16#12.o0" to "35–32 ℃, сознание ясное, дрожь выражена",
    "q.l16#12.o1" to "38 ℃",
    "q.l16#12.o2" to "Ниже 30 ℃",
    "q.l16#12.o3" to "Ниже 28 ℃",
    "q.l16#12.e" to "Лёгкая степень характеризуется дрожью и ясным сознанием. Дрожь — признак того, что организм ещё вырабатывает тепло, то есть ещё есть запас.",
    "q.l16#13.p" to "Почему прекращение дрожи считают тревожным признаком?",
    "q.l16#13.o0" to "Организм больше не может поддерживать температуру за счёт теплопродукции: это средняя степень и тяжелее",
    "q.l16#13.o1" to "Значит, стало лучше",
    "q.l16#13.o2" to "Значит, человек уснул",
    "q.l16#13.o3" to "Значит, он слишком устал",
    "q.l16#13.e" to "Переход от трясёт без остановки к не трясёт — не улучшение, а срыв компенсации. Нужны немедленное согревание и госпитализация.",
    "q.l16#14.p" to "Что правильно делать с переохлаждённым без сознания?",
    "q.l16#14.o0" to "Не давать горячее питьё, а укрыть, изолировать от земли и переносить осторожно",
    "q.l16#14.o1" to "Дать горячий сладкий чай",
    "q.l16#14.o2" to "Растирать руки и ноги",
    "q.l16#14.o3" to "Заставить идти",
    "q.l16#14.e" to "При нарушенном сознании глотательный рефлекс ненадёжен, питьё может попасть в дыхательные пути. Грубое перемещение может спровоцировать нарушение ритма сердца.",
    "q.l16#15.p" to "Какой должна быть температура воды при согревании отмороженной конечности на месте?",
    "q.l16#15.o0" to "37–40 ℃",
    "q.l16#15.o1" to "50–60 ℃",
    "q.l16#15.o2" to "Ледяная вода",
    "q.l16#15.o3" to "Чем горячее, тем лучше",
    "q.l16#15.e" to "Эта температура близка к температуре тела: согревает, но не обжигает. Слишком горячая вода даёт вторичное повреждение, слишком холодная бесполезна.",
    "q.l16#16.p" to "Почему после согревания отморожения нужно избегать повторного замерзания?",
    "q.l16#16.o0" to "Повторное замерзание и оттаивание повреждает ткани гораздо сильнее, чем одно отморожение",
    "q.l16#16.o1" to "Потому что будет больно",
    "q.l16#16.o2" to "Потому что появится отёк",
    "q.l16#16.o3" to "Потому что останется рубец",
    "q.l16#16.e" to "Согреть и снова заморозить хуже, чем держать в холоде. Поэтому согревать нужно только тогда, когда дальнейшее замерзание исключено.",
    "q.l16#17.p" to "Чего НЕ следует делать с отмороженной частью тела на месте?",
    "q.l16#17.o0" to "Растирать снегом, греть над огнём, протирать спиртом",
    "q.l16#17.o1" to "Согревать в тёплой воде",
    "q.l16#17.o2" to "Закрывать стерильной повязкой",
    "q.l16#17.o3" to "Приподнимать конечность",
    "q.l16#17.e" to "Трение и сухое тепло усиливают повреждение тканей. На месте делают только тёплое согревание, защиту и обезболивание.",
    "q.l16#18.p" to "Можно ли идти дальше после отморожения стоп?",
    "q.l16#18.o0" to "По возможности нет: ходьба усиливает повреждение; если можно дождаться спасателей, ждите",
    "q.l16#18.o1" to "Можно идти",
    "q.l16#18.o2" to "Бегом будет быстрее",
    "q.l16#18.o3" to "Можно, если не болит",
    "q.l16#18.e" to "Нагрузка на согретые отмороженные стопы значительно усиливает повреждение. Именно поэтому вопрос когда согревать — это компромисс.",
    "q.l16#19.p" to "Три главных условия профилактики переохлаждения?",
    "q.l16#19.o0" to "Оставаться сухим, защищаться от ветра, вовремя восполнять энергию",
    "q.l16#19.o1" to "Надеть больше одежды",
    "q.l16#19.o2" to "Пить больше горячей воды",
    "q.l16#19.o3" to "Больше ходить",
    "q.l16#19.e" to "Влага, ветер и нехватка энергии — три входа в переохлаждение. Противоядие: слой отвода влаги, ветрозащитный слой и регулярный приём пищи.",
    "q.m11#12.p" to "Почему южный склон Юйчжу подходит как первая вершина 6000-метрового уровня?",
    "q.m11#12.o0" to "Снежный склон относительно пологий, есть подъезд, маршрут отработан",
    "q.m11#12.o1" to "Потому что она самая высокая",
    "q.m11#12.o2" to "Потому что она технически самая сложная",
    "q.m11#12.o3" to "Потому что там мало людей",
    "q.m11#12.e" to "Цель первой 6000-метровой вершины — проверить акклиматизацию и выносливость, а не технику. Отработанный маршрут снижает неизвестность.",
    "q.m11#13.p" to "В каком горном хребте находится Цицзы?",
    "q.m11#13.o0" to "Ньенчен-Тангла",
    "q.m11#13.o1" to "Куньлунь",
    "q.m11#13.o2" to "Гималаи",
    "q.m11#13.o3" to "Каракорум",
    "q.m11#13.e" to "Цицзы находится в уезде Дамсюн в Тибете и относится к Ньенчен-Тангла. Хребет определяет климат и сезонное окно — важный фон при выборе вершины.",
    "q.m11#14.p" to "Каково самое типичное назначение Лобуче-Восточной?",
    "q.m11#14.o0" to "Переходная вершина и техническая тренировка между 6000 и 8000 м",
    "q.m11#14.o1" to "Туристический маршрут",
    "q.m11#14.o2" to "Горнолыжный склон",
    "q.m11#14.o3" to "Смотровая площадка",
    "q.m11#14.e" to "Она стоит прямо у треккингового маршрута к Эвересту: склон круче, подъезд удобный — обычная переходная вершина.",
    "q.m11#15.p" to "Какова техническая особенность Айленд-Пик (Имджа-Цзе)?",
    "q.m11#15.o0" to "Нужны движение в связке и прохождение ледника с трещинами: классическая техническая 6000-метровая вершина",
    "q.m11#15.o1" to "Чистый треккинг",
    "q.m11#15.o2" to "Достаточно ходьбы по снежному склону",
    "q.m11#15.o3" to "Снега не бывает круглый год",
    "q.m11#15.e" to "Техника Айленд-Пик — это прежде всего ледник и трещины, а не скальная стена. Движение в связке и спасение из трещины обязательны.",
    "q.m11#16.p" to "Что при выборе вершины 6000-метрового уровня важнее самой высоты?",
    "q.m11#16.o0" to "Характер маршрута (снежный склон, ледник, скалы) и сложность отступления",
    "q.m11#16.o1" to "Красиво ли звучит название",
    "q.m11#16.o2" to "Далеко ли ехать",
    "q.m11#16.o3" to "Сколько это стоит",
    "q.m11#16.e" to "При одинаковых 6100 м снежный склон и ледник требуют разного на порядок. Сначала смотрите на характер маршрута, потом на высоту.",
    "q.m11#17.p" to "Требования по разрешениям и гидам на 6000-метровом уровне обычно по сравнению с 5000-метровым?",
    "q.m11#17.o0" to "Строже: чаще нужна регистрация или обязательный гид",
    "q.m11#17.o1" to "Мягче",
    "q.m11#17.o2" to "Полностью такие же",
    "q.m11#17.o3" to "Требований нет",
    "q.m11#17.e" to "Чем выше и чем глуше маршрут, тем строже контроль. Уточнить правила заранее гораздо проще, чем выяснять у подножия.",
    "q.m11#18.p" to "Почему на 6000-метровом уровне нужно исходить из того, что трещины есть?",
    "q.m11#18.o0" to "Под снежными мостами их не видно, поэтому нужно идти в связке, как будто они есть",
    "q.m11#18.o1" to "Потому что трещины есть всегда",
    "q.m11#18.o2" to "Потому что так требует гид",
    "q.m11#18.o3" to "Потому что так написано в страховке",
    "q.m11#18.e" to "Не видно не значит нет. Движение в связке стоит дёшево, падение в трещину — очень дорого.",
    "q.m11#19.p" to "План акклиматизации на 6000-метровом уровне обычно по сравнению с 5000-метровым?",
    "q.m11#19.o0" to "Длиннее: выше высота сна, медленнее восстановление",
    "q.m11#19.o1" to "Короче",
    "q.m11#19.o2" to "Такой же",
    "q.m11#19.o3" to "Не нужен",
    "q.m11#19.e" to "С каждой ступенью высоты время акклиматизации увеличивается. Переносить ритм 5000 м сразу на 6000 м — типичная недооценка.",
    "q.l43#0.p" to "Три основных источника проблем кожи на высоте?",
    "q.l43#0.o0" to "Сухость, ультрафиолет, ветер",
    "q.l43#0.o1" to "Холод, влага, трение",
    "q.l43#0.o2" to "Гипоксия, низкое давление, холод",
    "q.l43#0.o3" to "Питание, сон, стресс",
    "q.l43#0.e" to "Эти три фактора действуют одновременно, и кожный барьер быстро разрушается. Увлажнение и защита от солнца — не роскошь, а способ сохранить работоспособность.",
    "q.l43#1.p" to "Как правильно пользоваться химической грелкой?",
    "q.l43#1.o0" to "Крепить на поясницу, живот или внешнюю сторону ботинка, не на голую кожу",
    "q.l43#1.o1" to "Крепить прямо на кожу",
    "q.l43#1.o2" to "Крепить на лоб",
    "q.l43#1.o3" to "На ночь обклеиться с ног до головы",
    "q.l43#1.e" to "На голой коже возможен низкотемпературный ожог, а такие ожоги на высоте заживают очень медленно. Грелка защищает от падения температуры ядра.",
    "q.l43#2.p" to "Как правильно поступать с водой после мытья посуды?",
    "q.l43#2.o0" to "Процедить остатки, воду разбрызгать, остатки унести с собой",
    "q.l43#2.o1" to "Вылить в ручей",
    "q.l43#2.o2" to "Вылить у палатки",
    "q.l43#2.o3" to "Вылить в уборную яму",
    "q.l43#2.e" to "Остатки еды — источник загрязнения и приманка для животных. Процедить, унести, воду разбрызгать — так воздействие минимально.",
    "q.l43#3.p" to "Почему нижний слой стирают в первую очередь?",
    "q.l43#3.o0" to "Соль от пота натирает кожу, а повреждения кожи на высоте заживают плохо",
    "q.l43#3.o1" to "Потому что так красивее",
    "q.l43#3.o2" to "Потому что он лёгкий",
    "q.l43#3.o3" to "Потому что он дешёвый",
    "q.l43#3.e" to "Соль и бактерии в нижнем слое постоянно раздражают кожу. Одна потёртость в сухости и холоде может не заживать неделями.",
    "q.l43#4.p" to "Что делать, если пуховая куртка загрязнилась или намокла?",
    "q.l43#4.o0" to "Не стирать: стряхнуть снег и высушить",
    "q.l43#4.o1" to "Постирать со стиральным порошком",
    "q.l43#4.o2" to "Отжать",
    "q.l43#4.o3" to "Высушить над огнём",
    "q.l43#4.e" to "После стирки пух в поле почти невозможно вернуть в объём. Намокшую вещь только сушат, но не над огнём: огонь повреждает ткань и пух.",
    "q.l43#5.p" to "Что НЕ входит в три правила порядка в лагере?",
    "q.l43#5.o0" to "Оставлять еду в палатке на ночь",
    "q.l43#5.o1" to "Обувь в тамбуре",
    "q.l43#5.o2" to "Еда не в палатке",
    "q.l43#5.o3" to "Мусор собрать и подвесить",
    "q.l43#5.e" to "Еда в палатке ведёт животных прямо в спальную зону и надолго оставляет запах в спальнике. Три правила одновременно защищают от влаги, животных и загрязнения.",
    "q.l43#6.p" to "Почему на высоте важна гигиеническая помада для губ?",
    "q.l43#6.o0" to "В губах нет меланина, и после трещин больно есть и говорить",
    "q.l43#6.o1" to "Потому что так красивее",
    "q.l43#6.o2" to "Потому что они загорят",
    "q.l43#6.o3" to "Потому что они опухают",
    "q.l43#6.e" to "Губы — самая забываемая зона для защиты от солнца и та, которая при трещинах мешает есть. Помаду держать при себе.",
    "q.l43#7.p" to "Как планировать время на личную гигиену?",
    "q.l43#7.o0" to "Сделать коротким ежедневным ритуалом (утром и вечером по несколько минут), а не делом на досуге",
    "q.l43#7.o1" to "Делать, когда появится солнце",
    "q.l43#7.o2" to "Раз в неделю",
    "q.l43#7.o3" to "По настроению",
    "q.l43#7.e" to "Ценность гигиены — в регулярности. Ритуал выполняется и при усталости, а решение по настроению обычно пропускается.",
    "q.l43#8.p" to "Какие вещи в лагере должны быть у каждого свои, с подписанным именем?",
    "q.l43#8.o0" to "Посуда",
    "q.l43#8.o1" to "Средства гигиены",
    "q.l43#8.o2" to "Кружка",
    "q.l43#8.o3" to "Палатка",
    "q.l43#8.e" to "Первые три — то, что контактирует со ртом и кожей; общее пользование передаёт кишечные и кожные проблемы. Палатку распределяют по людям, подписывать её не нужно.",
    "q.l43#9.p" to "Какие гигиенические действия нужно делать на высоте каждый день?",
    "q.l43#9.o0" to "Наносить солнцезащитный крем, в том числе на губы",
    "q.l43#9.o1" to "Увлажнять кожу",
    "q.l43#9.o2" to "Менять носки на сухие и сушить обувь",
    "q.l43#9.o3" to "Мыться полностью каждый день",
    "q.l43#9.e" to "Первые три напрямую влияют на состояние кожи и стоп. Полное мытьё на высоте нереально и не нужно: достаточно местной гигиены.",
    "q.l43#10.p" to "Каких ситуаций при использовании химической грелки нужно избегать?",
    "q.l43#10.o0" to "Крепить прямо на кожу",
    "q.l43#10.o1" to "Долго держать на одном месте во сне",
    "q.l43#10.o2" to "Крепить на уже отмороженный участок",
    "q.l43#10.o3" to "Крепить на поясницу",
    "q.l43#10.e" to "Первые три могут дать низкотемпературный ожог или усилить повреждение при сниженной чувствительности. Поясница — обычное место для грелки.",
    "q.l43#11.p" to "Расставьте порядок действий после прихода в лагерь.",
    "q.l43#11.o0" to "Сначала снять мокрый нижний слой и надеть тёплый",
