    "q.l43#11.o2" to "Вскипятить воду, поесть, попить",
    "q.l43#11.o3" to "Выполнить ритуал ухода: защита от солнца, увлажнение, губы, обработка потёртостей",
    "q.l43#11.e" to "Смысл порядка — сначала остановить потерю тепла. Сначала готовить, потом переодеваться — самая частая ошибка.",
    "q.l43#12.p" to "Грелку крепят на поясницу, живот или внешнюю сторону ботинка, но не прямо на ______.",
