    "q.l43#12.a1" to "тело",
    "q.l43#12.e" to "На голой коже возможен низкотемпературный ожог, а ожоги на высоте заживают крайне плохо.",
    "q.l43#13.p" to "Порядок в лагере требует, чтобы еда не попадала в ______.",
    "q.l43#13.a0" to "палатку",
