    "q.l43#14.l2" to "Смена носков на сухие",
    "q.l43#14.l3" to "Химическая грелка",
    "q.l43#14.r0" to "Ультрафиолетовый ожог, включая риск снежной слепоты",
    "q.l43#14.r1" to "Сухость и трещины кожи, разрушение барьера",
