    "q.l43#14.r3" to "Падение температуры ядра",
    "q.l43#14.e" to "Четыре действия закрывают четыре класса проблем. Все они несложные, трудно другое — делать их каждый день.",
    "q.l43#15.p" to "Какой вариант стирки на высоте самый реалистичный?",
    "q.l43#15.o0" to "Стирать только нижний слой, небольшим количеством средства с хорошим полосканием, сушить в палатке",
