    "q.l43#15.o3" to "Тереть снегом",
    "q.l43#15.e" to "Вода и топливо в дефиците. Нижний слой — единственное, что обязательно стирать; остальное достаточно проветрить и выбить.",
    "q.l43#16.p" to "Как часто на высоте нужно обновлять солнцезащитный крем?",
    "q.l43#16.o0" to "Каждые 2–3 часа, а также после потоотделения или таяния снега",
