    "q.l43#16.o3" to "Не обновлять",
    "q.l43#16.e" to "Сильный ультрафиолет, ветер и отражение от снега быстро разрушают защитный слой. Обновлять важнее, чем выбирать высокий фактор.",
    "q.l43#17.p" to "Что чаще всего забывают, выходя из палатки ночью?",
    "q.l43#17.o0" to "Надеть обувь или лагерные тапочки, а не идти по снегу в одних носках",
