    "q.l43#17.o2" to "Взять воду",
    "q.l43#17.o3" to "Надеть шапку",
    "q.l43#17.e" to "Мокрые носки будут холодными всю ночь и повысят риск отморожения и переохлаждения. Лагерная обувь — самое простое и эффективное решение.",
    "q.l43#18.p" to "Как планировать расходники вроде влажных салфеток и бумаги?",
    "q.l43#18.o0" to "Разложить по дням и оставить один запас, чтобы не намокли",
