    "q.l43#18.o2" to "Взять побольше",
    "q.l43#18.o3" to "Не брать",
    "q.l43#18.e" to "Целая упаковка легко намокает и занимает место. Разложение по дням контролирует расход и оставляет резерв, если часть намокнет.",
    "q.l43#19.p" to "Что из средств гигиены стоит брать в двух экземплярах?",
