    "q.l43#19.o1" to "Шампунь",
    "q.l43#19.o2" to "Парфюм",
    "q.l43#19.o3" to "Бритву",
    "q.l43#19.e" to "Эти две вещи малы, незаменимы при утере и напрямую влияют на приём пищи и кожный барьер.",
    "q.m12#16.p" to "Каково теоретическое механическое преимущество системы 3:1?",
    "q.m12#16.o0" to "Вытянув 1 м верёвки, груз поднимается примерно на 1/3 м",
    "q.m12#16.o1" to "Нагрузка уменьшается вдвое",
    "q.m12#16.o2" to "Скорость не меняется",
    "q.m12#16.o3" to "Схватывающий узел не нужен",
    "q.m12#16.e" to "Механическое преимущество равно числу несущих ветвей верёвки. 3:1 означает, что усилие составляет около трети нагрузки, без учёта трения.",
    "q.m12#17.p" to "Какова обычно эффективность системы 5:1 в реальной работе?",
    "q.m12#17.o0" to "Ниже теоретической из-за потерь на трение в блоках и верёвке",
