    "q.m12#17.o2" to "Точно равна теоретической",
    "q.m12#17.o3" to "Не зависит от трения",
    "q.m12#17.e" to "Каждый блок даёт потери на трение, и реальная эффективность часто составляет лишь 60–70 % от теории. При расчёте нужно оставлять запас.",
    "q.m12#18.p" to "Какова главная плата за использование карабина вместо блока в качестве точки изменения направления?",
    "q.m12#18.o0" to "Заметно растёт трение, эффективность падает",
    "q.m12#18.o1" to "Не хватает прочности",
