    "q.m12#19.o0" to "Держит после вытягивания и не даёт грузу сползти обратно",
    "q.m12#19.o1" to "Повышает прочность",
    "q.m12#19.o2" to "Снижает трение",
    "q.m12#19.o3" to "Соединяет две верёвки",
    "q.m12#19.e" to "Без схватывающего узла груз каждый раз сползает, стоит отпустить. Узел превращает прерывистое вытягивание в перемещение.",
