    "q.m12#20.o3" to "Чтобы сэкономить верёвку",
    "q.m12#20.e" to "Надёжность схватывающего узла зависит от соответствия диаметра верёвки и её состояния. В ответственных системах два узла — обычная практика.",
    "q.m12#21.p" to "Как должна идти система при транспортировке пострадавшего?",
    "q.m12#21.o0" to "Как можно ближе к рельефу, чтобы не ударять его о стену или карниз",
    "q.m12#21.o1" to "Как можно выше",
    "q.m12#21.o2" to "Как можно быстрее",
    "q.m12#21.o3" to "Строго вертикально вверх",
    "q.m12#21.e" to "Повреждения при транспортировке чаще возникают от ударов, а не от тяги. Планировка трассы и расположение точек не менее важны.",
    "q.m12#22.p" to "В чём плата за систему 6:1 (сложную систему) по сравнению с 3:1?",
    "q.m12#22.o0" to "Нужно больше снаряжения, собирается дольше, расходует больше верёвки",
    "q.m12#22.o1" to "Легче, но быстрее",
    "q.m12#22.o2" to "Платы нет",
    "q.m12#22.o3" to "Нельзя разобрать",
    "q.m12#22.e" to "Чем выше механическое преимущество, тем сложнее сборка и длиннее нужная верёвка. В спасательной работе скорость обычно важнее экономии сил.",
    "q.m12#23.p" to "Каково базовое требование при переходе внутри системы?",
    "q.m12#23.o0" to "В любой момент хотя бы одно устройство несёт нагрузку, без момента полного отсоединения",
    "q.m12#23.o1" to "Действовать быстро",
    "q.m12#23.o2" to "Работать вдвоём",
    "q.m12#23.o3" to "Использовать ту же верёвку",
    "q.m12#23.e" to "Переход — частая точка аварий в спасательных работах. Везде, где снимают старое, сначала создают новое соединение.",
    "q.m12#24.p" to "Что делать, если верёвка в системе проходит через острую кромку?",
    "q.m12#24.o0" to "Поставить протектор или изменить направление, чтобы не порезать оплётку",
    "q.m12#24.o1" to "Просто перекинуть",
    "q.m12#24.o2" to "Натянуть сильнее",
    "q.m12#24.o3" to "Заменить на стропу",
    "q.m12#24.e" to "Порезанная нагруженная верёвка резко теряет прочность. Протектор стоит дёшево, а цена ошибки — верёвка или падение.",
    "q.m12#25.p" to "Почему к точкам спасательной системы предъявляют более высокие требования, чем к обычной станции?",
    "q.m12#25.o0" to "Держат статическую нагрузку с динамическими колебаниями, и система обычно одна",
    "q.m12#25.o1" to "Потому что это важнее",
    "q.m12#25.o2" to "Потому что людей больше",
    "q.m12#25.o3" to "Из-за длины верёвки",
    "q.m12#25.e" to "При спасении нет второй станции в запасе. Отказ точки означает, что упадут оба.",
    "q.m12#26.p" to "Что нужно учитывать при оценке усилия на вытягивание помимо механического преимущества?",
    "q.m12#26.o0" to "Вес пострадавшего и снаряжения, трение верёвки о блоки, сопротивление рельефа",
    "q.m12#26.o1" to "Погоду",
    "q.m12#26.o2" to "Время",
    "q.m12#26.o3" to "Вес партнёров",
    "q.m12#26.e" to "Теоретическое усилие часто недооценивают. С поправкой на трение и рельеф реальное усилие может оказаться вдвое больше.",
    "q.m12#27.p" to "Что нужно сделать сразу после сборки системы?",
    "q.m12#27.o0" to "Сделать пробное вытягивание без нагрузки и проверить ход, узлы и точки",
    "q.m12#27.o1" to "Сразу тянуть человека",
    "q.m12#27.o2" to "Сфотографировать",
    "q.m12#27.o3" to "Собрать верёвку",
    "q.m12#27.e" to "Пробное вытягивание без нагрузки выявляет до 80 % ошибок сборки. Десять секунд могут сэкономить отказ системы.",
    "q.l32#0.p" to "Перила делят по назначению на три типа. Какая группа верна?",
    "q.l32#0.o0" to "Перильная верёвка, короткий участок фиксированной верёвки, экспедиционное провешивание",
    "q.l32#0.o1" to "Одинарная, двойная, сдвоенная верёвка",
    "q.l32#0.o2" to "Динамическая, статическая, вспомогательная верёвка",
    "q.l32#0.o3" to "Верхний, средний, нижний участок",
    "q.l32#0.e" to "Три типа соответствуют трём сценариям и трём наборам правил. Перепутав сценарий, перила делают по схеме для маршрута, который стоит весь сезон.",
    "q.l32#1.p" to "Какую верёвку используют для длинных перил?",
    "q.l32#1.o0" to "Статическую, с малым удлинением",
    "q.l32#1.o1" to "Динамическую",
    "q.l32#1.o2" to "Вспомогательную (репшнур)",
    "q.l32#1.o3" to "Стропу",
    "q.l32#1.e" to "Удлинение динамической верёвки рассчитано на срыв: на перилах человек будет пружинить вверх-вниз, а верёвка износится быстрее.",
    "q.l32#2.p" to "Каков обычный диаметр статической верёвки для перил?",
    "q.l32#2.o0" to "9–11 мм",
    "q.l32#2.o1" to "5–6 мм",
    "q.l32#2.o2" to "7–8 мм",
    "q.l32#2.o3" to "12–14 мм",
    "q.l32#2.e" to "Слишком тонкая хуже сопротивляется истиранию и скользит в руках, слишком толстая прибавляет вес и объём. 9–11 мм — обычный диапазон для экспедиционного провешивания.",
    "q.l32#3.p" to "В чём проблема схемы, где две точки соединены одной стропой?",
    "q.l32#3.o0" to "Это последовательный отказ, а не резервирование",
    "q.l32#3.o1" to "Зря тратится стропа",
    "q.l32#3.o2" to "Некрасиво",
    "q.l32#3.o3" to "Снижает скорость работы с верёвкой",
    "q.l32#3.e" to "В последовательной схеме отказ одной точки ослабляет всю систему и резко меняет нагрузку. Условие резервирования — каждая точка независимо подключена к карабину.",
    "q.l32#4.p" to "Что означает независимость в пяти проверках точки?",
    "q.l32#4.o0" to "Точки должны быть на разных скальных блоках, разных деревьях, разных шлямбурах",
    "q.l32#4.o1" to "Точки расположены близко",
    "q.l32#4.o2" to "Используется одна стропа",
    "q.l32#4.o3" to "Две закладки в одной трещине",
    "q.l32#4.e" to "Две закладки в одной трещине вырвутся вместе при отказе одного скального блока. Независимость оценивают по вопросу: совпадает ли причина отказа.",
    "q.l32#5.p" to "Что проверяют по направлению нагрузки?",
    "q.l32#5.o0" to "Точка должна держать фактическое направление нагрузки, а не только вниз",
    "q.l32#5.o1" to "Точка обращена к видам",
    "q.l32#5.o2" to "Верёвка идёт прямо",
    "q.l32#5.o3" to "Точка должна быть сверху",
    "q.l32#5.e" to "Поперечный маятник на провешенном участке и раскачивание при подъёме дают боковую нагрузку. Точка, рассчитанная только на вертикаль, при боковой нагрузке откажет.",
    "q.l32#6.p" to "Что требует особого внимания у снежных точек?",
    "q.l32#6.o0" to "Прочность снега и риск таяния: при оттепели весь участок может отказать",
    "q.l32#6.o1" to "Снег слишком мягкий, неудобно закапывать",
    "q.l32#6.o2" to "Снег намочит верёвку",
    "q.l32#6.o3" to "Снежный якорь слишком тяжёлый",
    "q.l32#6.e" to "Надёжность снежной точки сильно зависит от температуры и времени. Точка, сделанная на дневной оттепели, может быть совсем не той, что была утром.",
    "q.l32#7.p" to "Зачем на конце верёвки вяжут контрольный узел?",
    "q.l32#7.o0" to "Чтобы конец не выскользнул из устройства",
    "q.l32#7.o1" to "Чтобы удобнее сматывать",
    "q.l32#7.o2" to "Чтобы отметить длину",
    "q.l32#7.o3" to "Чтобы добавить трение",
    "q.l32#7.e" to "При спуске или втором на конце, вышедшем из устройства, человек теряет связь с верёвкой. Контрольный узел — самая дешёвая и самая полезная страховка.",
    "q.l32#8.p" to "Какова основная роль промежуточной точки (re-belay)?",
    "q.l32#8.o0" to "Дать верёвке идти плавно и ограничить срыв и износ одним участком",
    "q.l32#8.o1" to "Добавить вес",
    "q.l32#8.o2" to "Удобнее фотографировать",
    "q.l32#8.o3" to "Заменить станцию",
    "q.l32#8.e" to "Без промежуточных точек на длинном маршруте верёвка образует огромный угол на скальной полке: её трудно выдёргивать, износ концентрируется, а глубина срыва растёт.",
    "q.l32#9.p" to "Можно ли находиться под работающим на провешивании?",
    "q.l32#9.o0" to "Нет: пока работают сверху, зона снизу должна быть свободна",
    "q.l32#9.o1" to "Да, удобно передавать инструмент",
    "q.l32#9.o2" to "Да, если в каске",
    "q.l32#9.o3" to "Да, если не баловаться",
    "q.l32#9.e" to "Камнепад — главный источник травм при провешивании. Человек снизу означает, что самое опасное место отдано партнёру.",
    "q.l32#10.p" to "Что нужно определить ещё на этапе планирования провешивания?",
    "q.l32#10.o0" to "Начало и конец каждого участка, промежуточные точки и точки отхода, длину верёвки, способ закрепления",
    "q.l32#10.o1" to "Цвет, бренд, цену, вес",
    "q.l32#10.o2" to "Кто идёт первым, кто фотографирует, кто кипятит воду, кто считает деньги",
    "q.l32#10.o3" to "Погоду, настроение, бюджет, отпуск",
    "q.l32#10.e" to "Эти четыре пункта определяют, можно ли безопасно уйти с маршрута. Пропустить планирование и сразу выйти на верёвку — значит отдать план отхода на волю случая.",
    "q.l32#11.p" to "Почему перила требуют регулярной проверки с записью результатов?",
    "q.l32#11.o0" to "Провешенный маршрут обычно стоит весь сезон, а состояние верёвки меняется от солнца, износа и циклов замерзания-оттаивания",
    "q.l32#11.o1" to "Для аудита",
    "q.l32#11.o2" to "Чтобы разделить ответственность",
    "q.l32#11.o3" to "Это не нужно",
    "q.l32#11.e" to "Ворс на оплётке, жёсткость, локальное сплющивание — признаки вывода из эксплуатации. Без записей никто не скажет, сколько дней эта верёвка висит.",
    "q.l32#12.p" to "Что входит в пять проверок точки?",
    "q.l32#12.o0" to "Независимость",
    "q.l32#12.o1" to "Уравнивание",
    "q.l32#12.o2" to "Направление",
    "q.l32#12.o3" to "Защита от острых кромок",
    "q.l32#12.e" to "Пятый пункт — дублирование. Чаще всего забывают именно острые кромки: порезанная стропа теряет почти всю прочность.",
    "q.l32#13.p" to "Какие признаки означают, что перила пора вывести из эксплуатации?",
    "q.l32#13.o0" to "Ворс на оплётке, прощупывается сердцевина",
    "q.l32#13.o1" to "Верёвка затвердела, на ощупь хрупкая",
    "q.l32#13.o2" to "Локальное сплющивание",
    "q.l32#13.o3" to "Цвет выгорел",
    "q.l32#13.e" to "Первые три — структурные повреждения. Выгорание само по себе только внешнее, но связан с ультрафиолетовым старением.",
    "q.l32#14.p" to "Что входит в самообеспечение безопасности при провешивании?",
    "q.l32#14.o0" to "Всегда минимум две точки подключения",
    "q.l32#14.o1" to "Каска",
    "q.l32#14.o2" to "Наблюдение сверху и защита от камнепада",
    "q.l32#14.o3" to "Мешок для верёвки и укладка остатка",
    "q.l32#14.e" to "Вместе это даёт безопасность рабочей зоны. Жёсткое правило одно — два подключения; исключение только прямое ввязывание при лидировании.",
    "q.l32#15.p" to "На каких уровнях может быть резервирование в системе перил?",
    "q.l32#15.o0" to "Резервирование точек: две независимые точки",
    "q.l32#15.o1" to "Резервирование подключения: PAS или дублирующая стропа",
    "q.l32#15.o2" to "Резервирование снаряжения: дублирующий схватывающий узел",
    "q.l32#15.o3" to "Резервирование цвета: купить несколько цветов",
    "q.l32#15.e" to "Три уровня отвечают за то, что система не откажет, переход не останется без точки и снаряжение не будет нести нагрузку в одиночку. Цвет к безопасности отношения не имеет.",
    "q.l32#16.p" to "Расставьте правильный порядок установки участка перил.",
    "q.l32#16.o0" to "Определить начало, конец и промежуточные точки, оценить длину верёвки",
    "q.l32#16.o1" to "Сделать точки: независимые, уравновешенные, с дублированием",
    "q.l32#16.o2" to "Проложить верёвку, поставить промежуточные точки",
    "q.l32#16.o3" to "Завязать контрольный узел и записать состояние верёвки",
    "q.l32#16.e" to "В длину закладывают запас на узлы и подключения: лучше длиннее, чем короче. Контрольный узел делают последним, но пропускать его нельзя.",
    "q.l32#17.p" to "Одна из точек вызывает сомнение. Каков правильный порядок действий?",
    "q.l32#17.o0" to "Прекратить использование участка и вывести людей в безопасное место",
    "q.l32#17.o1" to "Добавить независимую дублирующую точку",
    "q.l32#17.o2" to "Заново уравновесить нагрузку",
    "q.l32#17.o3" to "Проверить, записать и решить, продолжать ли",
    "q.l32#17.e" to "Сначала людей в безопасное место, потом технические меры. Обратный порядок превращает сам процесс устранения в место аварии.",
    "q.l32#18.p" to "Каков правильный ежедневный порядок работы с долговременными перилами?",
    "q.l32#18.o0" to "Перед выходом проверить точки и состояние верёвки",
    "q.l32#18.o1" to "При прохождении убедиться в двух подключениях",
    "q.l32#18.o2" to "При снятии проверить износ и контрольный узел",
    "q.l32#18.o3" to "Записать дату проверки и найденные проблемы",
    "q.l32#18.e" to "Ценность этой схемы в том, что проверка становится привычкой. Управлять перилами на весь сезон по памяти рано или поздно значит что-то пропустить.",
    "q.l32#19.p" to "Стандарт динамической верёвки — EN ______.",
    "q.l32#19.a0" to "892",
    "q.l32#19.e" to "Динамическая верёвка EN 892 / UIAA 101, статическая EN 1891 / UIAA 110. При закупке и проверке сверяются по номеру стандарта.",
    "q.l32#20.p" to "Для перил выбирают ______ верёвку (впишите: динамическую или статическую).",
    "q.l32#20.a0" to "статическую",
    "q.l32#20.a1" to "статическую верёвку",
    "q.l32#20.e" to "Статическая верёвка имеет малое удлинение и стойка к истиранию, поэтому подходит для долгого закрепления. Из-за удлинения динамической перила будут постоянно пружинить.",
    "q.l32#21.p" to "При провешивании конец верёвки обязательно ______, чтобы он не выскользнул из устройства.",
    "q.l32#21.a0" to "завязывают",
    "q.l32#21.a1" to "закрепляют контрольным узлом",
    "q.l32#21.e" to "Это самый пропускаемый шаг и тот, у которого самые прямые последствия.",
    "q.l32#22.p" to "Обычный диапазон диаметра статической верёвки для экспедиционного провешивания — ______–11 мм.",
    "q.l32#22.a0" to "9",
    "q.l32#22.e" to "9–11 мм сочетают стойкость к истиранию и вес. Тоньше 9 мм — быстрый износ, толще 11 мм — заметный лишний вес.",
    "q.l32#23.p" to "Соотнесите тип перил с типичным сценарием.",
    "q.l32#23.l0" to "Перильная верёвка",
    "q.l32#23.l1" to "Короткий участок фиксированной верёвки",
    "q.l32#23.l2" to "Экспедиционное провешивание",
    "q.l32#23.l3" to "Промежуточная точка",
    "q.l32#23.r0" to "Короткий участок с выходом на открытое место, проходят с опорой на верёвку",
    "q.l32#23.r1" to "Один крутой участок или один верёвочный участок, проходят вверх-вниз многократно",
    "q.l32#23.r2" to "Длинный маршрут, много участков, груз, стоит весь сезон",
    "q.l32#23.r3" to "Делит длинную верёвку на части, снижая углы и износ",
    "q.l32#23.e" to "Сценарий задаёт требования: чем дольше, тяжелее и опаснее, тем выше требования к резервированию точек и учёту состояния верёвки.",
    "q.l32#24.p" to "Соотнесите снаряжение с номером стандарта.",
    "q.l32#24.l0" to "Статическая верёвка",
    "q.l32#24.l1" to "Динамическая верёвка",
    "q.l32#24.l2" to "Зажим (жумар)",
    "q.l32#24.l3" to "Обвязка",
    "q.l32#24.r0" to "EN 1891 / UIAA 110",
    "q.l32#24.r1" to "EN 892 / UIAA 101",
    "q.l32#24.r2" to "EN 567",
    "q.l32#24.r3" to "EN 12277",
    "q.l32#24.e" to "Номер стандарта — основание для закупки и проверки, а также ответ на вопрос, под какую нагрузку это снаряжение изначально рассчитано.",
    "q.l32#25.p" to "Соотнесите проблему точки с её последствием.",
    "q.l32#25.l0" to "Последовательное соединение",
    "q.l32#25.l1" to "Нагрузка только в одном направлении",
    "q.l32#25.l2" to "Острая кромка без защиты",
    "q.l32#25.l3" to "Одна точка без дублирования",
    "q.l32#25.r0" to "Отказ одной точки ослабляет систему и резко меняет нагрузку",
    "q.l32#25.r1" to "При боковой нагрузке точка вырывается или ломается",
    "q.l32#25.r2" to "Стропа порезана, прочность резко падает",
    "q.l32#25.r3" to "Отказ единственного подключения означает полную потерю страховки",
    "q.l32#25.e" to "Четыре проблемы дают четыре способа отказа. Они часто есть одновременно, поэтому проверять нужно по пунктам, а не на глаз.",
    "q.l32#26.p" to "Партнёр говорит: «Эта верёвка висит всего сезон, проверять не надо». Что разумнее ответить?",
    "q.l32#26.o0" to "Износ перил определяется условиями и трением, а не длиной сезона",
    "q.l32#26.o1" to "Действительно, проверять не нужно",
    "q.l32#26.o2" to "Достаточно сменить цвет",
    "q.l32#26.o3" to "Если не порвалась, значит годится",
    "q.l32#26.e" to "Солнце, циклы замерзания-оттаивания и трение о скалы накапливают повреждения. Периодичность проверки задаёт интенсивность использования, а не календарь.",
    "q.l32#27.p" to "Каково правило оценки длины верёвки при провешивании?",
    "q.l32#27.o0" to "Закладывать запас на узлы и подключения: лучше длиннее, чем короче",
    "q.l32#27.o1" to "Ровно равна длине участка",
    "q.l32#27.o2" to "Чем короче и легче, тем лучше",
    "q.l32#27.o3" to "Считать по прямой линии на карте",
    "q.l32#27.e" to "Короткая верёвка делает весь участок непригодным, длинная просто тяжелее. Узлы, подключения и промежуточные точки забирают длину, и это нужно учитывать.",
    "q.l32#28.p" to "Участник проходит участок перил с поперечным маятником. Что нужно проверить в первую очередь?",
    "q.l32#28.o0" to "Держат ли точки боковую нагрузку и есть ли второе подключение",
    "q.l32#28.o1" to "Цвет верёвки",
    "q.l32#28.o2" to "Длину верёвки",
    "q.l32#28.o3" to "Его вес",
    "q.l32#28.e" to "Поперечный маятник превращает вертикальную нагрузку в боковую, и именно так вырывает многие точки.",
    "q.l32#29.p" to "Зачем на провешенном маршруте нужны точки отхода?",
    "q.l32#29.o0" to "Чтобы при изменении погоды или состояния людей можно было безопасно выйти в пределах одного участка",
    "q.l32#29.o1" to "Чтобы отдохнуть",
    "q.l32#29.o2" to "Чтобы складировать снаряжение",
    "q.l32#29.o3" to "Чтобы фотографировать",
    "q.l32#29.e" to "Длинный маршрут не всегда проходят до конца. Точки отхода определяют, останется ли выбор, когда условия ухудшатся.",
    "q.m13#14.p" to "Каков правильный порядок подъёма по схватывающим узлам (подъём на прусиках)?",
    "q.m13#14.o0" to "Встать (подтянуть верхний узел) → сесть (перенести вес) → подтянуть нижний узел → повторить",
    "q.m13#14.o1" to "Толкать оба узла одновременно",
    "q.m13#14.o2" to "Толкать только верхний узел",
    "q.m13#14.o3" to "Тянуться руками",
    "q.m13#14.e" to "Цикл встать — сесть — подтянуть переносит вес между верхним и нижним узлами. Толкать оба одновременно значит просто соскользнуть.",
    "q.m13#15.p" to "Какова роль петли для ноги при самостоятельном подъёме?",
    "q.m13#15.o0" to "Перенести вес на ноги и снизить нагрузку на руки",
    "q.m13#15.o1" to "Увеличить трение",
    "q.m13#15.o2" to "Соединить с обвязкой",
    "q.m13#15.o3" to "Отметить высоту",
    "q.m13#15.e" to "Тянуться только руками — значит выбиться из сил через десяток метров. Петля для ноги включает ноги и определяет, выберетесь вы или нет.",
    "q.m13#16.p" to "Что нужно сделать в первую очередь при спасении из связки?",
    "q.m13#16.o0" to "Затормозить и закрепиться, чтобы упавший не продолжал скользить",
    "q.m13#16.o1" to "Сразу спуститься в трещину",
    "q.m13#16.o2" to "Вызвать спасателей",
    "q.m13#16.o3" to "Сфотографировать",
    "q.m13#16.e" to "Торможение — единственное, что нельзя отложить. Связь, система и вытягивание обсуждаются после закрепления.",
    "q.m13#17.p" to "Что опаснее всего для висящего в трещине?",
    "q.m13#17.o0" to "Переохлаждение, сдавливание верёвкой и травмы от ударов",
    "q.m13#17.o1" to "Солнечный ожог",
    "q.m13#17.o2" to "Высотная болезнь",
    "q.m13#17.o3" to "Обезвоживание",
    "q.m13#17.e" to "В трещине очень холодно, а подвешивание нарушает кровообращение. Спасение должно быть быстрым, а не просто вытягиванием наверх.",
    "q.m13#18.p" to "Зачем пострадавшему дают возможность самостраховки?",
    "q.m13#18.o0" to "Он перестаёт зависеть от основной верёвки, и спасатель освобождает руки для системы",
    "q.m13#18.o1" to "Потому что верёвке не доверяют",
    "q.m13#18.o2" to "Потому что так положено",
    "q.m13#18.o3" to "Потому что нет снаряжения",
    "q.m13#18.e" to "Самостраховка схватывающим узлом или ледорубом стабилизирует положение и даёт человеку дело, снижая панику.",
    "q.m13#19.p" to "Как правильно вытащить из трещины пострадавшего, который не может двигаться сам?",
    "q.m13#19.o0" to "Собрать систему 3:1 или 5:1 и вытягивать сверху",
    "q.m13#19.o1" to "Тянуть верёвку руками",
    "q.m13#19.o2" to "Пусть выбирается сам",
    "q.m13#19.o3" to "Обмотать верёвку вокруг пояса",
    "q.m13#19.e" to "Тянуть руками практически невозможно и легко потерять контроль. Системное вытягивание — единственный надёжный способ.",
    "q.m13#20.p" to "Откуда возникает цейтнот при спасении?",
    "q.m13#20.o0" to "Скорость переохлаждения, изменение погоды, истощение группы",
    "q.m13#20.o1" to "Только от усталости",
    "q.m13#20.o2" to "Только от погоды",
    "q.m13#20.o3" to "Только от переохлаждения",
    "q.m13#20.e" to "Все три действуют одновременно. В плане спасения важен вопрос «за сколько мы успеем», а не только «сможем ли».",
    "q.m13#21.p" to "Какой способ связи при спасении наименее надёжен?",
    "q.m13#21.o0" to "Крик через небольшой снежный бугор",
    "q.m13#21.o1" to "Рация",
    "q.m13#21.o2" to "Сигналы верёвкой",
    "q.m13#21.o3" to "Свисток",
    "q.m13#21.e" to "Ветер, длина верёвки и рельеф съедают звук. Заранее оговорённые сигналы верёвкой или свистком надёжнее, чем крик на месте.",
    "q.m13#22.p" to "Почему навыки самоспасения отрабатывают до автоматизма на безопасном рельефе?",
    "q.m13#22.o0" to "При реальном срыве внимание занято страхом, и выполняются только автоматические действия",
    "q.m13#22.o1" to "Для экзамена",
    "q.m13#22.o2" to "Для скорости",
    "q.m13#22.o3" to "Для красоты",
    "q.m13#22.e" to "Это общая логика любой спасательной подготовки: довести действие до состояния, когда думать не нужно, и тогда останется запас на наблюдение и оценку.",
    "q.m13#23.p" to "Какова главная задача второго участника при спасении из связки?",
    "q.m13#23.o0" to "Помочь с торможением, готовить систему, следить за опасностью сверху",
    "q.m13#23.o1" to "Фотографировать",
    "q.m13#23.o2" to "Продолжать движение",
    "q.m13#23.o3" to "Собирать верёвку",
    "q.m13#23.e" to "В этом и смысл связки из трёх: один тормозит, один собирает систему, один наблюдает. В связке из двух всё приходится совмещать.",
    "q.m13#24.p" to "Если упавший не реагирует, каков приоритет?",
    "q.m13#24.o0" to "Как можно быстрее достать и начать реанимацию, одновременно вызывая внешнюю помощь",
    "q.m13#24.o1" to "Сначала собрать систему 5:1",
    "q.m13#24.o2" to "Ждать спасателей",
    "q.m13#24.o3" to "Сначала всё записать",
    "q.m13#24.e" to "Отсутствие реакции означает крайне короткое временное окно. Здесь скорость важнее экономии сил: при необходимости берут самую простую систему.",
    "q.m13#25.p" to "Что чаще всего забывают после завершения спасения?",
    "q.m13#25.o0" to "Разобрать систему и ход работы, записать проблемы",
    "q.m13#25.o1" to "Собрать верёвку",
    "q.m13#25.o2" to "Спуститься",
    "q.m13#25.o3" to "Поесть",
    "q.m13#25.e" to "Разница между тренировкой и реальностью проявляется именно в разборе: какой этап был медленным, какой узел завязали неверно, какую команду никто не расслышал.",
    "q.m13#26.p" to "Почему спасательная система должна быть независима от основной верёвки?",
    "q.m13#26.o0" to "Основная верёвка может быть повреждена ледовой крошкой и острыми кромками, и она всё ещё несёт нагрузку",
    "q.m13#26.o1" to "Потому что так положено",
    "q.m13#26.o2" to "Потому что она длиннее",
    "q.m13#26.o3" to "Потому что она легче",
    "q.m13#26.e" to "Подвесить спасательную систему на повреждённую и нагруженную верёвку — значит сложить два риска в один.",
    "q.m13#27.p" to "Что группа должна решить заранее, ещё в зоне трещин?",
    "q.m13#27.o0" to "Кто тормозит, кто собирает систему, как поддерживается связь",
    "q.m13#27.o1" to "Кто идёт первым",
    "q.m13#27.o2" to "Кто несёт самое тяжёлое",
    "q.m13#27.o3" to "Кто фотографирует",
    "q.m13#27.e" to "Роли определяют до выхода. В первые тридцать секунд после срыва обсуждать, кто что делает, уже некогда.",
    "q.l33#0.p" to "Чего НЕТ в стандартном наборе для подъёма по перилам?",
    "q.l33#0.o0" to "Спускового устройства (восьмёрки или корзинки)",
    "q.l33#0.o1" to "Жумара",
    "q.l33#0.o2" to "Петли для ноги",
    "q.l33#0.o3" to "Дублирующего схватывающего узла",
    "q.l33#0.e" to "На подъёме спусковое устройство не нужно: оно относится к смене верёвки и спуску. Набор определяется текущим действием, а не принципом «повесить всё».",
    "q.l33#1.p" to "Как звучит формула движения при подъёме?",
    "q.l33#1.o0" to "Встать, сесть, подтянуть",
    "q.l33#1.o1" to "Тянуть, упираться, прыгать",
    "q.l33#1.o2" to "Присесть, прыгнуть, схватить",
    "q.l33#1.o3" to "Толкать, тянуть, садиться",
    "q.l33#1.e" to "Встать на петлю, перенести вес вверх, подтянуть грудной зажим, сесть, подтянуть жумар. При верном ритме экономится половина сил.",
    "q.l33#2.p" to "Где должен быть центр тяжести при подъёме?",
    "q.l33#2.o0" to "Близко к верёвке",
    "q.l33#2.o1" to "Как можно дальше наружу",
    "q.l33#2.o2" to "Раскачиваться влево-вправо",
    "q.l33#2.o3" to "Как можно сильнее откинуться назад",
    "q.l33#2.e" to "Откинутый центр тяжести даёт боковую нагрузку на зажим, он легче соскакивает, а сил тратится заметно больше. Держаться у верёвки — это и безопасность, и экономия.",
    "q.l33#3.p" to "Каково исключение из правила двух подключений?",
    "q.l33#3.o0" to "Прямое ввязывание при лидировании",
    "q.l33#3.o1" to "Хорошая погода",
    "q.l33#3.o2" to "Светлое время суток",
    "q.l33#3.o3" to "Короткое расстояние",
    "q.l33#3.e" to "При лидировании человек сам является частью системы и не может подключить вторую точку. Во всех остальных случаях два независимых подключения обязательны.",
    "q.l33#4.p" to "Каково первое правило прохождения узла?",
    "q.l33#4.o0" to "Сначала создать новое подключение, потом снять старое",
    "q.l33#4.o1" to "Сначала снять старое, потом создать новое",
    "q.l33#4.o2" to "Работать двумя зажимами одновременно",
    "q.l33#4.o3" to "Просто перешагнуть узел",
    "q.l33#4.e" to "При обратном порядке на мгновение возникает состояние «только одна точка» или даже «ни одной». Прохождение узла — это управляемый перенос системы.",
    "q.l33#5.p" to "Можно ли при прохождении узла снять с верёвки оба зажима одновременно?",
    "q.l33#5.o0" to "Нет: в любой момент хотя бы один должен быть на верёвке и под нагрузкой",
    "q.l33#5.o1" to "Да, если действовать быстро",
    "q.l33#5.o2" to "Да, если кто-то смотрит",
    "q.l33#5.o3" to "Да, если узел короткий",
    "q.l33#5.e" to "Одновременное снятие обоих означает полную потерю связи с верёвкой. Лучше потратить лишнюю минуту на перестановку, чем один раз рискнуть.",
    "q.l33#6.p" to "Каков первый шаг перехода с подъёма на спуск?",
    "q.l33#6.o0" to "Подключиться к станции через PAS или стропу",
    "q.l33#6.o1" to "Сначала снять жумар",
    "q.l33#6.o2" to "Сначала поставить спусковое устройство",
    "q.l33#6.o3" to "Сначала отстегнуть грудной зажим",
    "q.l33#6.e" to "Сначала получают подключение, независимое от системы подъёма, и только потом речь идёт о снятии старой системы. Это общая отправная точка всех смен верёвки.",
    "q.l33#7.p" to "Что обязательно сделать после установки спускового устройства, но до снятия зажимов?",
    "q.l33#7.o0" to "Нагрузить устройство и проверить его",
    "q.l33#7.o1" to "Сначала расстегнуть обвязку",
    "q.l33#7.o2" to "Сначала собрать верёвку",
    "q.l33#7.o3" to "Сначала снять каску",
    "q.l33#7.e" to "Проверка под нагрузкой — единственный способ убедиться, что новая система действительно держит вес. Пропустив этот шаг, можно снять старую систему и сразу упасть.",
    "q.l33#8.p" to "Какова роль схватывающего узла над спусковым устройством?",
    "q.l33#8.o0" to "Автоматически зажимать верёвку при срыве руки, работая независимым дублёром",
    "q.l33#8.o1" to "Увеличивать скорость спуска",
    "q.l33#8.o2" to "Защищать верёвку",
    "q.l33#8.o3" to "Отмечать положение",
    "q.l33#8.e" to "Схватывающий узел закусывает верёвку, когда отпускают тормозящую руку. Это единственная защита в самый опасный момент — момент отпускания.",
    "q.l33#9.p" to "Зачем перед спуском вяжут контрольный узел на конце верёвки?",
    "q.l33#9.o0" to "Чтобы конец не выскользнул из спускового устройства",
    "q.l33#9.o1" to "Чтобы удобнее сматывать",
    "q.l33#9.o2" to "Чтобы отметить длину",
    "q.l33#9.o3" to "Чтобы уменьшить износ",
    "q.l33#9.e" to "Если верёвки не хватает, вышедший конец означает мгновенную потерю торможения. Контрольный узел — обязательный пункт проверки перед спуском.",
    "q.l33#10.p" to "Каков правильный порядок прохождения промежуточной точки?",
    "q.l33#10.o0" to "Сначала подключиться к точке, затем переставить зажимы, в конце снять подключение к точке",
    "q.l33#10.o1" to "Сначала переставить зажимы, потом подключиться к точке",
    "q.l33#10.o2" to "Проходить без подключения к точке",
    "q.l33#10.o3" to "Сначала снять подключение, потом переставить",
    "q.l33#10.e" to "На промежуточной точке верёвка зажата карабином: места мало и движение легко искажается. Сначала создают независимое подключение, и только потом появляется запас на ошибку.",
    "q.l33#11.p" to "Что делать, если верёвка заклинила?",
    "q.l33#11.o0" to "Изменить угол вытягивания или тянуть сбоку, но не рвать стоя прямо под верёвкой",
    "q.l33#11.o1" to "Встать прямо под ней и тянуть изо всех сил",
    "q.l33#11.o2" to "Дёргать весом тела",
    "q.l33#11.o3" to "Сразу перерезать",
    "q.l33#11.e" to "Рывок стоя под верёвкой грозит ударом отскочившей верёвкой или камнем, а узел можно затянуть ещё сильнее. Изменение угла — самый действенный первый шаг.",
    "q.l33#12.p" to "Какую сторону тянуть, снимая сдвоенную верёвку после спуска?",
    "q.l33#12.o0" to "Ту, где трение меньше",
    "q.l33#12.o1" to "Ту, где трение больше",
    "q.l33#12.o2" to "Любую",
    "q.l33#12.o3" to "Обе одновременно",
    "q.l33#12.e" to "С меньшей стороны верёвка выдёргивается легче и оплётка изнашивается меньше. Условие — контрольные узлы на концах и отсутствие зацепов.",
    "q.l33#13.p" to "Что из снаряжения обязательно должно быть на себе при подъёме по перилам?",
    "q.l33#13.o0" to "Жумар и грудной зажим (или второй схватывающий узел)",
    "q.l33#13.o1" to "Петля для ноги",
    "q.l33#13.o2" to "Дублирующий схватывающий узел и PAS",
    "q.l33#13.o3" to "Каска",
    "q.l33#13.e" to "Все четыре составляют полную систему подъёма и дублирования. Без любого из них прохождение узла и смена верёвки вынуждают работать на одной точке.",
    "q.l33#14.p" to "Какие ошибки при смене верёвки встречаются чаще всего?",
    "q.l33#14.o0" to "Сначала снять старую систему, потом собрать новую",
    "q.l33#14.o1" to "Снять зажимы, не нагрузив и не проверив спусковое устройство",
    "q.l33#14.o2" to "Одновременно снять оба зажима",
    "q.l33#14.o3" to "Подключиться к станции перед сменой верёвки",
    "q.l33#14.e" to "Первые три — ошибки порядка. Последний пункт как раз правильное действие: подключение к станции и делают, чтобы первых трёх ошибок не возникло.",
    "q.l33#15.p" to "Какие проверки обязательны перед спуском?",
    "q.l33#15.o0" to "Спусковое устройство заправлено в правильном направлении",
    "q.l33#15.o1" to "Дублирующий схватывающий узел стоит и работает",
    "q.l33#15.o2" to "На конце верёвки завязан контрольный узел",
    "q.l33#15.o3" to "Длины верёвки хватает до следующей станции",
    "q.l33#15.e" to "Пропуск любого пункта грозит потерей контроля. Весь набор проверяют до того, как снимают страховку.",
    "q.l33#16.p" to "Что можно использовать как новое подключение при прохождении узла?",
    "q.l33#16.o0" to "PAS или стропу, подключённые выше узла",
    "q.l33#16.o1" to "Подключение к близлежащей точке",
    "q.l33#16.o2" to "Второй зажим, поставленный выше",
    "q.l33#16.o3" to "Захват верёвки рукой",
    "q.l33#16.e" to "Рука не является подключением: стоит разжать пальцы, и связи нет. Первые три варианта создают точку нагрузки, независимую от старой системы.",
    "q.l33#17.p" to "Расставьте пять шагов подъёма через узел.",
    "q.l33#17.o0" to "Перед узлом замедлиться, оценить положение узла и участок верёвки выше",
    "q.l33#17.o1" to "Подключиться через PAS или стропу выше узла либо к близлежащей точке",
    "q.l33#17.o2" to "Поставить выше второй зажим или схватывающий узел, встать и перенести вес",
    "q.l33#17.o3" to "Снять нижний зажим и поставить его выше узла",
    "q.l33#17.o4" to "Убедиться, что новое подключение нагружено, и снять дубль PAS",
    "q.l33#17.e" to "Смысл пяти шагов — всегда иметь лишнюю точку. Пропустив любой шаг, получаешь участок, где нагрузку держит единственная точка или не держит никто.",
    "q.l33#18.p" to "Расставьте порядок перехода с подъёма на спуск.",
    "q.l33#18.o0" to "Подключиться к станции через PAS или стропу",
    "q.l33#18.o1" to "Поставить спусковое устройство и правильно заправить верёвку",
    "q.l33#18.o2" to "Нагрузить устройство и проверить его",
    "q.l33#18.o3" to "Снять жумар, оставив грудной зажим или дублирующий узел",
    "q.l33#18.o4" to "Снять второй зажим и убедиться, что устройство и дубль работают",
    "q.l33#18.o5" to "Отстегнуть PAS и начать спуск",
    "q.l33#18.e" to "Порядок фиксирован и не подлежит импровизации. Каждый шаг сохраняет хотя бы одно надёжное подключение.",
    "q.l33#19.p" to "Расставьте порядок перехода со спуска на подъём.",
    "q.l33#19.o0" to "Поставить над спусковым устройством схватывающий узел или зажим и подключить к обвязке",
    "q.l33#19.o1" to "Встать и перенести вес на схватывающий узел",
    "q.l33#19.o2" to "Поставить второй зажим или петлю для ноги и проверить, что они держат",
    "q.l33#19.o3" to "Снять спусковое устройство",
    "q.l33#19.o4" to "Начать подъём",
    "q.l33#19.e" to "Ключ в третьем шаге: снимать спусковое устройство можно только тогда, когда новая система уже несёт нагрузку.",
    "q.l33#20.p" to "Расставьте три шага спуска через узел.",
    "q.l33#20.o0" to "Выше узла подключиться через PAS к узлу или к точке, создав дубль",
    "q.l33#20.o1" to "Перенести спусковое устройство ниже узла, подтянуть и проверить под нагрузкой",
    "q.l33#20.o2" to "Отстегнуть PAS и продолжить спуск",
    "q.l33#20.e" to "Если толстый узел сразу не проходится, сначала переносят дублирующий узел ниже, потом спусковое устройство: между двумя переносами связь сохраняется.",
    "q.l33#21.p" to "При подъёме по перилам в любой момент нужно сохранять ______ независимых подключения.",
    "q.l33#21.a0" to "2",
    "q.l33#21.a1" to "два",
    "q.l33#21.e" to "Два подключения — жёсткое правило работы с перилами. Единственное исключение — прямое ввязывание при лидировании.",
    "q.l33#22.p" to "При переходе с подъёма на спуск нужно сначала подключиться к ______, а потом снимать зажимы.",
    "q.l33#22.a0" to "станции",
    "q.l33#22.a1" to "точке",
    "q.l33#22.a2" to "промежуточной точке",
    "q.l33#22.e" to "Получить подключение, независимое от старой системы, — отправная точка любой смены верёвки.",
    "q.l33#23.p" to "Распространённые формы дублирующего схватывающего узла над спусковым устройством — прусик или ______.",
    "q.l33#23.a0" to "автоблок",
    "q.l33#23.a1" to "французский прусик",
    "q.l33#23.a2" to "схватывающий узел",
    "q.l33#23.e" to "Оба варианта — дубль, который зажимает при отпускании руки. Неверно поставленный или неверной длины узел не работает, поэтому проверку доводят до автоматизма.",
    "q.l33#24.p" to "Соотнесите операцию с её ключевым правилом.",
    "q.l33#24.l0" to "Прохождение узла",
    "q.l33#24.l1" to "Прохождение промежуточной точки",
    "q.l33#24.l2" to "Переход с подъёма на спуск",
    "q.l33#24.l3" to "Переход со спуска на подъём",
    "q.l33#24.r0" to "Сначала создать новое подключение, потом снять старое",
    "q.l33#24.r1" to "Сначала подключиться к точке, потом переставлять снаряжение",
    "q.l33#24.r2" to "Подключение к станции, установка устройства, проверка, снятие зажимов",
    "q.l33#24.r3" to "Снимать спусковое устройство только после того, как новая система нагружена",
    "q.l33#24.e" to "У всех четырёх операций одна структура: создать, перенести, снять. Запоминать структуру надёжнее, чем запоминать шаги.",
    "q.l33#25.p" to "Соотнесите пункты проверки ABCDE с их содержанием.",
    "q.l33#25.l0" to "A — точки",
    "q.l33#25.l1" to "B — дублирование",
    "q.l33#25.l2" to "C — подключения",
    "q.l33#25.l3" to "E — выход",
    "q.l33#25.r0" to "Две независимые точки, уравнивание, верное направление нагрузки, защита острых кромок",
    "q.l33#25.r1" to "PAS или схватывающий узел на месте, у каждого элемента свой дубль",
    "q.l33#25.r2" to "Муфта карабина закрыта, узлы затянуты, на конце верёвки контрольный узел",
    "q.l33#25.r3" to "Известна ближайшая точка отхода, длины верёвки хватает, связь оговорена",
    "q.l33#25.e" to "Ценность этой проверки в том, что её проходят каждый раз перед выходом на верёвку. Она не заменяет оценку, но отсекает большинство грубых ошибок.",
    "q.l33#26.p" to "Партнёр собирается снять один зажим и «сразу же» поставить второй. Что вы скажете?",
    "q.l33#26.o0" to "Сначала нужно создать подключение через PAS или к точке, без момента без связи",
    "q.l33#26.o1" to "Главное — быстро",
    "q.l33#26.o2" to "Днём можно",
    "q.l33#26.o3" to "На коротком узле можно",
    "q.l33#26.e" to "«Сразу же» при срыве руки означает нулевой запас. Запас на прохождении узла создаётся только третьим подключением.",
    "q.l33#27.p" to "На промежуточной точке верёвку нужно вынуть из карабина и вставить обратно. Как правильно?",
    "q.l33#27.o0" to "Сначала подключиться к точке, потом работать с верёвкой, в конце снять дубль",
    "q.l33#27.o1" to "Сначала вынуть верёвку, потом подключиться к точке",
    "q.l33#27.o2" to "Попросить партнёра подержать верёвку",
    "q.l33#27.o3" to "Просто открыть карабин",
    "q.l33#27.e" to "В момент вынимания человек может зависеть только от старого подключения. Только создав независимое, есть смысл начинать операцию.",
    "q.l33#28.p" to "Почему смену верёвки называют самым аварийным этапом работы с перилами?",
    "q.l33#28.o0" to "Потому что нагрузку переносят между снятием старой системы и сборкой новой, и запас на ошибку минимален",
    "q.l33#28.o1" to "Потому что много снаряжения",
    "q.l33#28.o2" to "Потому что тяжело физически",
    "q.l33#28.o3" to "Потому что нужны двое",
    "q.l33#28.e" to "Прохождение узла — это «добавить точку», смена верёвки — «заменить систему целиком». Любая ошибка порядка напрямую ведёт к потере связи.",
    "q.l34#0.p" to "Какой рельеф на леднике самый опасный и самый недооценённый?",
    "q.l34#0.o0" to "Трещины и снежные мосты, закрытые снегом",
    "q.l34#0.o1" to "Моренные гряды",
    "q.l34#0.o2" to "Ровное снежное поле",
    "q.l34#0.o3" to "Щебнистые склоны по краям ледника",
    "q.l34#0.e" to "Засыпанная свежим снегом трещина выглядит как обычный снег. В ледниковых авариях падение в трещину занимает первое место.",
    "q.l34#1.p" to "Где чаще всего появляются поперечные трещины?",
    "q.l34#1.o0" to "В местах изменения крутизны: на перегибах, у подножия склона, при выходе на ледовую ступень",
    "q.l34#1.o1" to "Посередине ледника",
    "q.l34#1.o2" to "В конце ледника",
    "q.l34#1.o3" to "На морене",
    "q.l34#1.e" to "Резкое изменение крутизны означает растяжение или сжатие, и трещины раскрываются именно там. Перед подъёмом осматривать зону перегиба — самая практичная привычка.",
    "q.l34#2.p" to "Какова причина продольных трещин по краям ледника?",
    "q.l34#2.o0" to "Растяжение от трения краёв ледника о рельеф при течении",
    "q.l34#2.o1" to "Их выбивают камнепады",
    "q.l34#2.o2" to "Их вытаптывают восходители",
    "q.l34#2.o3" to "Их размывает талая вода",
    "q.l34#2.e" to "Середина течёт быстрее краёв, разница скоростей даёт сдвиг и растяжение. Поэтому идти по осевой линии обычно безопаснее, чем вдоль края.",
    "q.l34#3.p" to "Каков обычный интервал между участниками в связке?",
    "q.l34#3.o0" to "8–10 м",
    "q.l34#3.o1" to "2–3 м",
    "q.l34#3.o2" to "20–30 м",
    "q.l34#3.o3" to "Чем ближе, тем лучше",
    "q.l34#3.e" to "При слишком коротком интервале провалившийся сразу утянет партнёра, при слишком длинном растут тормозной путь и сложность спасения. В зоне трещин интервал сокращают, но не меньше 6–8 м.",
    "q.l34#4.p" to "Зачем в связке вяжут узлы на верёвке?",
    "q.l34#4.o0" to "Ограничить глубину падения, добавить трение при торможении и дать за что взяться при спасении",
    "q.l34#4.o1" to "Чтобы верёвка не скручивалась",
    "q.l34#4.o2" to "Чтобы отметить длину",
    "q.l34#4.o3" to "Для красоты",
    "q.l34#4.e" to "Узел создаёт дополнительное сопротивление и упор на краю трещины, заметно уменьшая глубину падения. Плата — верёвку чуть труднее выдёргивать, но это оправдано.",
    "q.l34#5.p" to "В чём главное преимущество связки из трёх перед связкой из двух?",
    "q.l34#5.o0" to "Когда один провалился, двое тормозят, а один может готовить систему спасения — запас больше",
    "q.l34#5.o1" to "Идут быстрее",
    "q.l34#5.o2" to "Верёвка легче",
    "q.l34#5.o3" to "Узлы не нужны",
    "q.l34#5.e" to "В связке из двух тормозящий почти не может работать с системой; только в связке из трёх появляется разделение на торможение и сборку системы.",
    "q.l34#6.p" to "По чему в первую очередь судят о надёжности снежного моста?",
    "q.l34#6.o0" to "По цвету и провалу: тёмный, синеватый цвет или радиальные трещины говорят о тонком слое",
    "q.l34#6.o1" to "По количеству следов",
    "q.l34#6.o2" to "По ровности поверхности",
    "q.l34#6.o3" to "По наличию ветра",
    "q.l34#6.e" to "Прочность моста зависит от пролёта и толщины снега. Цвет и провал — самые наглядные признаки, а следы говорят лишь о том, что здесь уже кто-то шёл, но не о безопасности.",
    "q.l34#7.p" to "Когда лучше всего проходить зону с частыми трещинами?",
    "q.l34#7.o0" to "Утром или в холодное ночное время",
    "q.l34#7.o1" to "В полдень",
    "q.l34#7.o2" to "После обеда",
    "q.l34#7.o3" to "В любое время, разницы нет",
    "q.l34#7.e" to "На холоде снежные мосты крепче всего, после дневного таяния прочность заметно падает. План похода строят вокруг этого, а не наоборот.",
    "q.l34#8.p" to "Как правильно проходить ледопад (зону сераков)?",
    "q.l34#8.o0" to "Быстро, с интервалом, в каске, не останавливаясь внутри зоны",
    "q.l34#8.o1" to "Медленно, в связке",
    "q.l34#8.o2" to "Отдохнуть внутри зоны",
    "q.l34#8.o3" to "Сфотографироваться на память",
    "q.l34#8.e" to "Опасность ледопада — обрушение сераков, и это не трещина: вниз идёт целый блок. Чем меньше времени внутри, тем лучше, и ждать там в связке тоже не стоит.",
    "q.l34#9.p" to "В каком состоянии должна быть верёвка при движении по леднику?",
    "q.l34#9.o0" to "Умеренно натянута: не волочится и не провисает слишком сильно",
    "q.l34#9.o1" to "Полностью свободна и волочится по снегу",
    "q.l34#9.o2" to "Натянута очень туго",
    "q.l34#9.o3" to "Смотана и несётся в руке",
    "q.l34#9.e" to "Провисшая верёвка в момент падения даёт рывковую нагрузку, а перетянутая стягивает партнёров. Умеренное натяжение плюс узлы — самое устойчивое сочетание.",
    "q.l34#10.p" to "Что делать в первую очередь при явной трещине на пути?",
    "q.l34#10.o0" to "Обойти, найти более узкое место или уже наведённый мост",
    "q.l34#10.o1" to "Перепрыгнуть",
    "q.l34#10.o2" to "Встать на край и посмотреть глубину",
    "q.l34#10.o3" to "Расширить ледорубом",
    "q.l34#10.e" to "Первый принцип выбора маршрута на леднике — обойти. Прыжок и осмотр с края — два самых частых способа навредить себе.",
    "q.l34#11.p" to "Почему движение по осевой линии ледника обычно безопаснее?",
    "q.l34#11.o0" to "В зонах растяжения по краям трещин больше, а по центру нагрузка распределена ровнее",
    "q.l34#11.o1" to "По центру снег толще",
    "q.l34#11.o2" to "По центру короче",
    "q.l34#11.o3" to "По центру больше людей",
    "q.l34#11.e" to "По центру трещин обычно меньше, а пролёты мостов короче. Но у ледопадов и ледовых ступеней решение принимают отдельно, механически переносить правило нельзя.",
    "q.l34#12.p" to "Что учитывают при оценке риска ледникового маршрута?",
    "q.l34#12.o0" to "Плотность трещин и состояние снежных мостов",
    "q.l34#12.o1" to "Риск сераков и падения льда",
    "q.l34#12.o2" to "Температуру и солнце в этот день, влияющие на прочность мостов",
    "q.l34#12.o3" to "Численность группы и способ движения в связке",
    "q.l34#12.e" to "Все четыре связаны: температура определяет мосты, численность определяет связку, связка определяет последствия падения. Оценка риска — это взгляд на них вместе.",
    "q.l34#13.p" to "Какие признаки говорят о ненадёжности снежного моста?",
    "q.l34#13.o0" to "Заметный провал поверхности",
    "q.l34#13.o1" to "Тёмный, синеватый цвет",
    "q.l34#13.o2" to "Радиальные трещины у краёв моста",
    "q.l34#13.o3" to "Свежий снег сверху и гулкий отзвук пустоты под ним",
    "q.l34#13.e" to "Все четыре — разные проявления недостаточной прочности. Услышав гулкий отзвук, нужно отходить назад, а не делать ещё шаг вперёд.",
    "q.l34#14.p" to "Какие действия на леднике повышают риск?",
    "q.l34#14.o0" to "Слишком короткий интервал в связке",
    "q.l34#14.o1" to "Отсутствие узлов на верёвке",
    "q.l34#14.o2" to "Остановка на отдых в ледопаде",
    "q.l34#14.o3" to "Движение вдоль края ледника",
    "q.l34#14.e" to "Четыре пункта повышают соответственно риск совместного падения, глубокого погружения, падения льда и боковых трещин. Все они — следствие выбора, которого можно избежать.",
    "q.l34#15.p" to "Что группа должна согласовать до входа в зону частых трещин?",
    "q.l34#15.o0" to "Интервал и способ вязки узлов",
    "q.l34#15.o1" to "Порядок прохождения и дистанции",
    "q.l34#15.o2" to "Правила действий у снежного моста: прощупать, обойти, отойти",
    "q.l34#15.o3" to "У кого самый тяжёлый рюкзак",
    "q.l34#15.e" to "Первые три определяют, как все будут реагировать в момент опасности. Договориться заранее гораздо безопаснее, чем обсуждать это на краю трещины.",
    "q.l34#16.p" to "Расставьте порядок прохождения подозрительного снежного моста.",
    "q.l34#16.o0" to "Остановиться, осмотреть цвет, провал и трещины вокруг",
    "q.l34#16.o1" to "Прощупать толщину моста ледорубом или щупом",
    "q.l34#16.o2" to "Убедившись, что обхода нет, сократить интервал и проходить по одному",
    "q.l34#16.o3" to "После прохождения всех последний снимает страховку и идёт следом",
    "q.l34#16.e" to "Прощупывать нужно до того, как человек встанет на мост. Проход по одному означает, что вес одного человека принимается за раз, — это ключевая мера.",
    "q.l34#17.p" to "Каков правильный порядок планирования ледникового перехода?",
    "q.l34#17.o0" to "Сначала изучить схему маршрута и распределение трещин",
    "q.l34#17.o1" to "Определить время прохождения зоны трещин: утро или ночь",
    "q.l34#17.o2" to "Определить способ движения в связке и интервал",
    "q.l34#17.o3" to "Перед выходом ещё раз уточнить погоду и температуру",
    "q.l34#17.e" to "Сначала рельеф, затем время, затем порядок в связке и в конце проверка погоды. При обратном порядке получается «пошли по плану, но выбрали не то время».",
    "q.l34#18.p" to "Партнёр провалился в трещину. Каков порядок первых трёх действий?",
    "q.l34#18.o0" to "Немедленно затормозить и держать верёвку под нагрузкой",
    "q.l34#18.o1" to "Убедиться, что своё положение безопасно, и закрепиться",
    "q.l34#18.o2" to "Крикнуть партнёрам, чтобы готовили систему спасения",
    "q.l34#18.o3" to "Действовать по порядку спасения из связки",
    "q.l34#18.e" to "Торможение — единственное, что нельзя отложить; закрепление и система идут после. Подробный порядок — в уроке о самоспасении и спасении из связки.",
    "q.l34#19.p" to "Обычный интервал в связке на леднике — ______–10 м.",
    "q.l34#19.a0" to "8",
    "q.l34#19.e" to "8–10 м — общепринятый диапазон. В зоне трещин его сокращают, но не настолько, чтобы падение одного утянуло всю группу.",
    "q.l34#20.p" to "Прочность снежного моста оценивают не только по цвету и провалу, но и прощупывая его ледорубом: ______.",
    "q.l34#20.a0" to "прощупать",
    "q.l34#20.a1" to "проверить",
    "q.l34#20.a2" to "потыкать",
    "q.l34#20.e" to "Прощупывание делают до того, как человек встанет на мост. Кончиком ледоруба легко вводить и оценивать толщину слоя и наличие пустоты под ним.",
    "q.l34#21.p" to "Зону частых трещин лучше проходить ______, когда снежные мосты крепче всего.",
    "q.l34#21.a0" to "утром",
    "q.l34#21.a1" to "рано утром",
    "q.l34#21.a2" to "ночью",
    "q.l34#21.e" to "На холоде мост становится жёстче и прочнее, а после дневного таяния прочность заметно падает.",
    "q.l34#22.p" to "Соотнесите тип трещины с её типичным положением.",
    "q.l34#22.l0" to "Поперечная трещина",
    "q.l34#22.l1" to "Продольная трещина",
    "q.l34#22.l2" to "Косая трещина",
    "q.l34#22.l3" to "Серак и ледопад",
    "q.l34#22.r0" to "Места изменения крутизны: перегибы, подножие, ледовые ступени",
    "q.l34#22.r1" to "Зона растяжения у краёв ледника, где он трётся о рельеф",
    "q.l34#22.r2" to "Места поворота ледника или изменения его ширины",
    "q.l34#22.r3" to "Под крутым ледопадом, где высок риск падения льда",
    "q.l34#22.e" to "Причина трещин — растяжение. Запомнив это, можно заранее предсказать, где следующий участок даст разрыв.",
    "q.l34#23.p" to "Соотнесите признак снежного моста с действием.",
    "q.l34#23.l0" to "Провал поверхности",
    "q.l34#23.l1" to "Тёмный, синеватый цвет",
    "q.l34#23.l2" to "Радиальные трещины",
    "q.l34#23.l3" to "Гулкий отзвук пустоты",
    "q.l34#23.r0" to "Снизить приоритет прохождения, искать обход",
    "q.l34#23.r1" to "Слой тонкий: не проверять, стоя на нём",
    "q.l34#23.r2" to "Структура повреждена, проход запрещён",
    "q.l34#23.r3" to "Немедленно отойти и сменить маршрут",
    "q.l34#23.e" to "Четыре признака идут по возрастанию серьёзности. При любом из них сначала думают об обходе, а не о том, как быстрее проскочить.",
    "q.l34#24.p" to "Соотнесите роль с обязанностями в связке из трёх.",
    "q.l34#24.l0" to "Первый, ведущий",
    "q.l34#24.l1" to "Средний",
    "q.l34#24.l2" to "Замыкающий",
    "q.l34#24.r0" to "Выбирает маршрут и оценивает мосты, задаёт темп",
    "q.l34#24.r1" to "Связывает переднего и заднего, передаёт команды",
    "q.l34#24.r2" to "Собирает верёвку, следит за тылом и состоянием конца верёвки",
    "q.l34#24.e" to "Роли в связке из трёх оговаривают до выхода. Средний — не «самое безопасное место», а узел передачи информации.",
    "q.l34#25.p" to "Кто-то предлагает «топнуть разок и проверить, крепкий ли мост». Что делать?",
    "q.l34#25.o0" to "Остановить и перейти на ледоруб или щуп, либо сразу обойти",
    "q.l34#25.o1" to "Пусть попробует, всё равно в связке",
    "q.l34#25.o2" to "Пусть пройдёт первым один",
    "q.l34#25.o3" to "Пробежать, чтобы меньше нагружать",
    "q.l34#25.e" to "Человек — это десятки килограммов сосредоточенной нагрузки, один шаг может проломить мост. Проверяют инструментом, а не весом тела.",
    "q.l34#26.p" to "К полудню потеплело, а до зоны трещин ещё два часа. Что делать?",
    "q.l34#26.o0" to "Пересмотреть план: дождаться вечернего похолодания или пойти по запасному маршруту",
    "q.l34#26.o1" to "Идти по плану",
    "q.l34#26.o2" to "Ускориться и проскочить",
    "q.l34#26.o3" to "Стоять на месте до завтра",
    "q.l34#26.e" to "Прочность моста зависит от времени. План строят вокруг самого крепкого периода, а не подстраивают людей под план.",
    "q.l34#27.p" to "Почему ледопад не годится как место ожидания в связке?",
    "q.l34#27.o0" to "Серак обрушивается целым блоком, а ожидание растягивает время под опасностью",
    "q.l34#27.o1" to "Потому что там ветер",
    "q.l34#27.o2" to "Потому что неровно",
    "q.l34#27.o3" to "Потому что нет связи",
    "q.l34#27.e" to "Риск трещин распределяют связкой, а риск падения льда снижают только сокращением времени под ним. Направления борьбы с этими двумя рисками совершенно разные.",
    "q.l34#28.p" to "Что верно про темп и скорость движения по леднику?",
    "q.l34#28.o0" to "Ровный темп с сохранением интервала безопаснее рывков",
    "q.l34#28.o1" to "Чем быстрее, тем безопаснее",
    "q.l34#28.o2" to "Чем медленнее, тем безопаснее",
    "q.l34#28.o3" to "Каждый идёт как может",
    "q.l34#28.e" to "Из-за рывков верёвка то провисает, то натягивается, давая рывковые нагрузки. На леднике единый темп — это и безопасность, и эффективность.",
    "q.l34#29.p" to "Что важнее всего отработать тому, кто впервые выходит на ледник?",
    "q.l34#29.o0" to "На безопасном участке: движение в связке, контроль интервала и положение для торможения",
    "q.l34#29.o1" to "Бегать быстрее",
    "q.l34#29.o2" to "Проходить трещины в одиночку",
    "q.l34#29.o3" to "Работать на высоте",
    "q.l34#29.e" to "Положение для торможения и чувство интервала нужно довести до мышечной памяти на безопасном рельефе, иначе при реальном падении будет уже поздно.",
    "q.m14#17.p" to "Как обычно проявляются невозвратные издержки в решениях на горе?",
    "q.m14#17.o0" to "«Столько денег и времени уже потрачено, нельзя уехать ни с чем»",
    "q.m14#17.o1" to "Прогноз был неточным",
    "q.m14#17.o2" to "Не хватило снаряжения",
    "q.m14#17.o3" to "Партнёры шли слишком медленно",
    "q.m14#17.e" to "Чем больше вложено, тем труднее отказаться. Но понесённые затраты не вернутся от продолжения — добавятся только новые риски.",
    "q.m14#18.p" to "Когда групповое мышление возникает легче всего?",
    "q.m14#18.o0" to "Когда группа сплочённая, возражений нет, а лидер высказался слишком рано",
    "q.m14#18.o1" to "Когда в группе большие разногласия",
    "q.m14#18.o2" to "Когда людей мало",
    "q.m14#18.o3" to "Когда плохая погода",
    "q.m14#18.e" to "Сплочённость сама по себе хороша, но она подавляет инакомыслие. Обычные меры — дать высказаться младшему первым и назначить «адвоката дьявола».",
    "q.m14#19.p" to "Что такое предвзятость подтверждения?",
    "q.m14#19.o0" to "Поиск только той информации, что подтверждает своё решение, с игнорированием обратных доводов",
    "q.m14#19.o1" to "Неспособность запомнить информацию",
    "q.m14#19.o2" to "Чрезмерная осторожность",
    "q.m14#19.o3" to "Зависимость от других",
    "q.m14#19.e" to "Если очень хочется «сегодня пройти», замечаются только хорошие признаки погоды. Единственное противоядие — самому искать опровержение.",
    "q.m14#20.p" to "Зачем для важных решений нужен чек-лист?",
    "q.m14#20.o0" to "В усталости и под давлением пункты пропускаются, а список превращает «помнить» в «проверить по пунктам»",
    "q.m14#20.o1" to "Для архива",
    "q.m14#20.o2" to "Чтобы выглядеть профессионально",
    "q.m14#20.o3" to "Потому что так положено",
    "q.m14#20.e" to "Чек-лист не заменяет оценку, он гарантирует, что вся нужная для оценки информация собрана.",
    "q.m14#21.p" to "Как выглядит эффект якоря в походе?",
    "q.m14#21.o0" to "«По плану до лагеря 6 часов» становится эталоном, и реальное состояние пути игнорируется",
    "q.m14#21.o1" to "Доверие гиду",
    "q.m14#21.o2" to "Работа с картой",
    "q.m14#21.o3" to "Измерение температуры",
    "q.m14#21.e" to "Как только якорь появился, все дальнейшие суждения подстраиваются под него. Опираться нужно на фактический темп, а не на плановое значение.",
    "q.m14#22.p" to "В чём ценность записи решений: времени, основания, вывода?",
    "q.m14#22.o0" to "Разбор получает опору, и у группы появляется общее понимание одних и тех же фактов",
    "q.m14#22.o1" to "Для отчёта",
    "q.m14#22.o2" to "Для страховки",
    "q.m14#22.o3" to "Для книги",
    "q.m14#22.e" to "Без записей разбор превращается в «каждый о своём». Выписанная хронология показывает, на каком узле можно было решить раньше.",
    "q.m14#23.p" to "Какой конкретный риск создаёт ореол эксперта?",
    "q.m14#23.o0" to "Никто не решается оспорить явную ошибку, и ошибка спокойно исполняется",
    "q.m14#23.o1" to "Эксперт устаёт",
    "q.m14#23.o2" to "Эксперт дорого берёт",
    "q.m14#23.o3" to "Эксперт плохо знает маршрут",
    "q.m14#23.e" to "Ореол подавляет подъём информации наверх. Самое опасное состояние в группе — не когда никто не понимает, а когда никто не решается сказать.",
    "q.l35#0.p" to "Какова основная причина смерти при засыпании лавиной?",
    "q.l35#0.o0" to "Асфиксия, 65–100 %",
    "q.l35#0.o1" to "Травма",
    "q.l35#0.o2" to "Гипотермия",
    "q.l35#0.o3" to "Кровопотеря",
    "q.l35#0.e" to "Этот пункт напрямую задаёт порядок действий: сначала дыхательные пути и вентиляция, потом кровообращение и согревание.",
    "q.l35#1.p" to "Каковы примерно показатели выживаемости при полном и частичном засыпании по сводке 2023 года?",
    "q.l35#1.o0" to "Около 48 % и 96 %",
    "q.l35#1.o1" to "Около 80 % и 90 %",
    "q.l35#1.o2" to "Около 20 % и 60 %",
    "q.l35#1.o3" to "Оба около 50 %",
    "q.l35#1.e" to "Разница более чем вдвое говорит о том, что «голова снаружи» и «человек под снегом целиком» — совершенно разные ситуации.",
    "q.l35#2.p" to "Какой промежуток времени примерно охватывает фаза выживания на кривой?",
    "q.l35#2.o0" to "Первые 18 минут",
    "q.l35#2.o1" to "Первые 5 минут",
    "q.l35#2.o2" to "18–35 минут",
    "q.l35#2.o3" to "После 90 минут",
    "q.l35#2.e" to "В фазе выживания гибель связана в основном с травмой, а дыхательные пути обычно ещё проходимы. Именно поэтому «18 минут» повторяют так настойчиво.",
    "q.l35#3.p" to "Чем характеризуется фаза асфиксии на кривой?",
    "q.l35#3.o0" to "Выживаемость круто падает: это самый напряжённый участок окна спасения",
    "q.l35#3.o1" to "Кривая пологая",
    "q.l35#3.o2" to "Выживаемость растёт",
    "q.l35#3.o3" to "Фаза не связана с охлаждением",
    "q.l35#3.e" to "Падение на 18–35-й минуте объясняется тем, что дыхательные пути забиты снегом, а кислород в воздушном кармане кончается. Именно в эти минуты и заключена ценность спасения силами партнёров.",
    "q.l35#4.p" to "Почему в латентной фазе (примерно 35–90 минут) кривая относительно пологая?",
    "q.l35#4.o0" to "У людей с воздушным карманом и проходимыми путями включается защитное охлаждение и обмен веществ замедляется",
    "q.l35#4.o1" to "Снег тает",
    "q.l35#4.o2" to "Пришла помощь",
    "q.l35#4.o3" to "Травма заживает",
    "q.l35#4.e" to "Здесь гипотермия выступает защитой, а не угрозой. Поэтому «лежал долго» нельзя механически приравнивать к «шансов нет».",
    "q.l35#5.p" to "Какую долю смертей при лавинах составляет гипотермия?",
    "q.l35#5.o0" to "0–4 %",
    "q.l35#5.o1" to "20–30 %",
    "q.l35#5.o2" to "50 %",
    "q.l35#5.o3" to "Почти все",
    "q.l35#5.e" to "Доля мала, но отдельные случаи реальны. Она напоминает: сначала дыхание, потом согревание, и порядок обратный недопустим.",
    "q.l35#6.p" to "Что важнее всего сделать в первые 0–2 минуты после схода лавины?",
    "q.l35#6.o0" to "Оценить риск повторной лавины, назначить наблюдателя, записать время и последнюю точку, где видели человека",
    "q.l35#6.o1" to "Сразу начать копать",
    "q.l35#6.o2" to "Сфотографировать",
    "q.l35#6.o3" to "Позвонить родственникам",
    "q.l35#6.e" to "Без наблюдателя спасатели могут стать второй группой под лавиной; без записи времени правило 60 минут потом просто не применить.",
    "q.l35#7.p" to "Какова цель этапа с 2-й по 10-ю минуту?",
    "q.l35#7.o0" to "Как можно быстрее добраться до человека, а не выкопать весь снег",
    "q.l35#7.o1" to "Прокопать нормативный проход",
    "q.l35#7.o2" to "Собрать снаряжение",
    "q.l35#7.o3" to "Дождаться профессиональной группы",
    "q.l35#7.e" to "Добравшись до лица, можно начать вентиляцию — это на несколько минут раньше, чем при полной откопке, а в фазе асфиксии несколько минут решают исход.",
    "q.l35#8.p" to "Каков правильный порядок первых 60 секунд после того, как добрались до лица?",
    "q.l35#8.o0" to "Очистить рот и нос от снега и крошки, проверить признаки жизни, при отсутствии дыхания сразу начать спасательное дыхание",
    "q.l35#8.o1" to "Сначала вытащить тело, потом очистить лицо",
    "q.l35#8.o2" to "Сначала сфотографировать, потом помогать",
    "q.l35#8.o3" to "Сначала дать горячее питьё",
    "q.l35#8.e" to "Сначала дыхательные пути, потом всё остальное. Выдёргивать человека сразу — значит и усугубить возможную травму позвоночника, и затолкать снег в рот и нос.",
    "q.l35#9.p" to "«Выживаемость 25 % на 45-й минуте выше 18 % на 40-й». Как это понимать правильно?",
    "q.l35#9.o0" to "Это разброс из-за малой выборки и разной доли людей с воздушным карманом, а не подъём кривой",
    "q.l35#9.o1" to "Значит, на 45-й минуте безопаснее",
    "q.l35#9.o2" to "Значит, надо ждать до 45-й минуты",
    "q.l35#9.o3" to "Данные ошибочны",
    "q.l35#9.e" to "Учить нужно тенденции, а не делать абсолютных обещаний из одной точки. Приняв разброс за закономерность, легко прийти к абсурдным выводам.",
    "q.l35#10.p" to "Всех полностью откопанных осмотрели — выглядят нормально. Что делать?",
    "q.l35#10.o0" to "Всё равно отправить в больницу под наблюдение",
    "q.l35#10.o1" to "Отпустить в лагерь",
    "q.l35#10.o2" to "Продолжить программу дня",
    "q.l35#10.o3" to "Пусть идут вниз сами",
    "q.l35#10.e" to "Последствия гипоксии и охлаждения могут проявиться с задержкой. Для наблюдения и оценки нужны оборудование и время, в лагере этого нет.",
    "q.l35#11.p" to "Какие сведения обязательно фиксируют на месте лавины?",
    "q.l35#11.o0" to "Время схода или время последнего подтверждённого контакта",
    "q.l35#11.o1" to "Последнюю точку, где человека видели",
    "q.l35#11.o2" to "Число засыпанных",
    "q.l35#11.o3" to "Имена спасателей",
    "q.l35#11.e" to "Первые три напрямую определяют зону поиска и медицинские решения. Имена спасателей — запись для отчёта, на решение на месте она не влияет.",
    "q.l35#12.p" to "Что нужно делать одновременно после откопки?",
    "q.l35#12.o0" to "Защищать позвоночник, избегая грубых перемещений",
    "q.l35#12.o1" to "Согревать всё тело, снять мокрую одежду, изолировать от земли",
    "q.l35#12.o2" to "Постоянно следить за ритмом сердца и температурой ядра",
    "q.l35#12.o3" to "Предложить пострадавшему встать и подвигаться",
    "q.l35#12.e" to "Первые три — стандартные действия. Самостоятельная активность усилит и охлаждение, и возможную травму позвоночника.",
    "q.l35#13.p" to "Что НЕ должно влиять на решение, спасать ли человека?",
    "q.l35#13.o0" to "Глубина засыпания",
    "q.l35#13.o1" to "Наличие воздушного кармана",
    "q.l35#13.o2" to "Плотность снега",
    "q.l35#13.o3" to "Полностью ли заполнены дыхательные пути",
    "q.l35#13.e" to "Первые три влияют на время раскопок, но не на медицинское решение. В сортировке участвуют только состояние дыхательных путей, время и температура.",
    "q.l35#14.p" to "Расставьте порядок действий первых десяти минут на месте лавины.",
    "q.l35#14.o0" to "Оценить риск повторной лавины и камнепада, назначить наблюдателя",
    "q.l35#14.o1" to "Записать время и последнюю точку, где видели человека, вызвать помощь",
    "q.l35#14.o2" to "Найти по биперу и уточнить место зондированием",
    "q.l35#14.o3" to "Начать копать с целью как можно быстрее добраться до лица",
    "q.l35#14.e" to "Логика порядка проста: сначала не дать спасению превратиться во вторую аварию, затем обеспечить основание для последующих решений.",
    "q.l35#15.p" to "Расставьте порядок действий после того, как добрались до лица.",
    "q.l35#15.o0" to "Очистить рот и нос от снега и крошки, оценить дыхательные пути",
    "q.l35#15.o1" to "В течение минуты проверить признаки жизни",
    "q.l35#15.o2" to "При отсутствии дыхания сразу начать спасательное дыхание",
    "q.l35#15.o3" to "Распределить по правилу 60 минут и организовать транспортировку",
    "q.l35#15.e" to "Вентиляция должна идти раньше полной откопки и раньше переноски. На практике именно этот порядок чаще всего делают наоборот.",
    "q.l35#16.p" to "Основная причина смерти при засыпании лавиной — асфиксия, на неё приходится ______–100 % смертей.",
    "q.l35#16.a0" to "65",
    "q.l35#16.e" to "Диапазон 65–100 % получен по девяти исследованиям. Он и объясняет, почему «сначала дыхание» — жёсткое правило.",
    "q.l35#17.p" to "В кривой выживаемости постоянно подчёркивают «золотые ______ минут» — окно до начала фазы асфиксии.",
    "q.l35#17.a0" to "18",
    "q.l35#17.a1" to "восемнадцать",
    "q.l35#17.e" to "18 минут — статистическая точка перелома. Это не магическое число, но как ориентир для тренировок оно годится.",
    "q.l35#18.p" to "Гипотермия составляет лишь ______–4 % смертей при лавинах.",
    "q.l35#18.a0" to "0",
    "q.l35#18.e" to "0–4 %. Доля мала, но именно она объясняет отдельные случаи спасения после очень долгого пребывания под снегом.",
    "q.l35#19.p" to "Соотнесите четыре фазы кривой выживаемости с их особенностями.",
    "q.l35#19.l0" to "Фаза выживания (0–18 минут)",
    "q.l35#19.l1" to "Фаза асфиксии (18–35 минут)",
    "q.l35#19.l2" to "Латентная фаза (35–90 минут)",
    "q.l35#19.l3" to "Фаза длительного погребения (свыше 90 минут)",
    "q.l35#19.r0" to "Гибель в основном от травмы, дыхательные пути обычно проходимы",
    "q.l35#19.r1" to "Выживаемость круто падает, окно спасения самое узкое",
    "q.l35#19.r2" to "У людей с воздушным карманом включается защитное охлаждение, кривая пологая",
    "q.l35#19.r3" to "На первом месте гипотермия, изредка выживают даже после очень долгого погребения",
    "q.l35#19.e" to "Четыре фазы соответствуют четырём структурам причин смерти. Разбирать кривую по фазам полезнее, чем запоминать отдельные проценты.",
    "q.l35#20.p" to "Соотнесите причину смерти с её долей.",
    "q.l35#20.l0" to "Асфиксия",
    "q.l35#20.l1" to "Травма",
    "q.l35#20.l2" to "Гипотермия",
    "q.l35#20.r0" to "65–100 %",
    "q.l35#20.r1" to "5–29 %",
    "q.l35#20.r2" to "0–4 %",
    "q.l35#20.e" to "Из этих долей и вытекает приоритет действий: дыхание, затем остановка кровотечения и иммобилизация, затем согревание.",
    "q.l35#21.p" to "Группа начала копать, не назначив наблюдателя. В чём главный риск?",
    "q.l35#21.o0" to "Повторная лавина накроет и спасателей",
    "q.l35#21.o1" to "Будут копать медленно",
    "q.l35#21.o2" to "Не хватит верёвки",
    "q.l35#21.o3" to "Не останется записи",
    "q.l35#21.e" to "Лавина редко сходит один раз. Наблюдатель — единственный, кто может крикнуть «стоп», когда идёт вторая.",
    "q.l35#22.p" to "Почему нельзя «выдернуть человека, как только до него докопались»?",
    "q.l35#22.o0" to "Можно усугубить травму позвоночника и затолкать снег в рот и нос",
    "q.l35#22.o1" to "Испортится одежда",
    "q.l35#22.o2" to "Не останется времени на фото",
    "q.l35#22.o3" to "Человек испугается",
    "q.l35#22.e" to "Сначала очистить лицо и дыхательные пути, проверить положение головы и шеи, потом освобождать грудь и тело. При обратном порядке спасённый может остаться парализованным.",
    "q.l35#23.p" to "Вы на месте один. Копать или сначала звать помощь?",
    "q.l35#23.o0" to "Копать: окно спасения короче любого времени реакции, сигнал подать при первой возможности",
    "q.l35#23.o1" to "Сначала позвонить",
    "q.l35#23.o2" to "Сначала сбегать в лагерь за людьми",
    "q.l35#23.o3" to "Сначала снять видео",
    "q.l35#23.e" to "В одиночку ожидание помощи почти равно отказу от спасения. Момент для сигнала можно найти позже, раскопки ждать не могут.",
    "q.l35#24.p" to "Почему время засыпания нужно фиксировать с точностью до минуты?",
    "q.l35#24.o0" to "От него зависит, по какой ветви правил пойдёт дальнейшая реанимация",
    "q.l35#24.o1" to "Для отчёта",
    "q.l35#24.o2" to "Для страховой выплаты",
    "q.l35#24.o3" to "Для статистики",
    "q.l35#24.e" to "60 минут — граница сортировки, а на месте время обычно восстанавливают по моменту, когда человека видели. Ошибка в десять минут уводит решение на другую ветвь.",
    "q.l35#25.p" to "Почему «глубоко засыпан» не значит «безнадёжно»?",
    "q.l35#25.o0" to "Глубина влияет на время раскопок, а медицинское решение опирается на время, дыхательные пути и температуру",
    "q.l35#25.o1" to "Потому что снег растает",
    "q.l35#25.o2" to "Потому что людей много",
    "q.l35#25.o3" to "Потому что глубоко засыпанный холоднее",
    "q.l35#25.e" to "Если считать глубину медицинским критерием, люди сдаются раньше времени. Глубина меняет только то, сколько вы копаете, но не то, что вы делаете.",
    "q.l36#0.p" to "Какова линия решения по времени засыпания в редакции ICAR MedCom 2023 года?",
    "q.l36#0.o0" to "60 минут",
    "q.l36#0.o1" to "35 минут",
    "q.l36#0.o2" to "90 минут",
    "q.l36#0.o3" to "120 минут",
    "q.l36#0.e" to "В редакции 2013 года было 35 минут, в 2023-м обновили до 60. В учебных материалах обязательно указывать год и методику.",
    "q.l36#1.p" to "Засыпан 25 минут, признаков жизни нет, дыхательные пути частично забиты рыхлым снегом (не полностью). Что делать?",
    "q.l36#1.o0" to "Действовать как при асфиксии: очистить рот и нос, как можно скорее дать спасательное дыхание и начать компрессии",
    "q.l36#1.o1" to "Считать это обструкцией и отказаться от реанимации",
    "q.l36#1.o2" to "Сначала согревать",
    "q.l36#1.o3" to "Ждать профессиональную группу",
    "q.l36#1.e" to "До 60 минут действуют как при асфиксии, независимо от проходимости путей. Рыхлый снег не равен обструкции: обструкция требует полного заполнения.",
    "q.l36#2.p" to "Засыпан 70 минут, признаков жизни нет, дыхательные пути проходимы, температуру ядра измерить нельзя. Что делать?",
    "q.l36#2.o0" to "Действовать как при гипотермической остановке сердца: начать реанимацию и транспортировку",
    "q.l36#2.o1" to "Действовать как при асфиксии и реанимацию не начинать",
    "q.l36#2.o2" to "Ждать измерения температуры",
    "q.l36#2.o3" to "Только согревать",
    "q.l36#2.e" to "Проходимые пути плюс больше 60 минут дают достаточно высокую вероятность гипотермической остановки, поэтому реанимацию начинают. Охлаждённое сердце «не считается мёртвым, пока не согрето».",
    "q.l36#3.p" to "Засыпан 70 минут, признаков жизни нет, рот и нос полностью забиты плотным снегом, температуру измерить невозможно. Что делать?",
    "q.l36#3.o0" to "Действовать как при асфиксической остановке сердца и реанимацию не начинать",
    "q.l36#3.o1" to "Немедленно начать компрессии",
    "q.l36#3.o2" to "Сначала откопать, потом решать",
    "q.l36#3.o3" to "Сделать два вдоха и прекратить",
    "q.l36#3.e" to "Это прямо перечисленный в редакции 2023 года случай, когда реанимацию можно не начинать. Если температуру измерить можно и она ниже 30 ℃, решение меняется на попытку реанимации.",
    "q.l36#4.p" to "Температура ядра 28 ℃, дыхательные пути проходимы, признаков жизни нет, засыпан 80 минут. Что делать?",
    "q.l36#4.o0" to "Попытаться реанимировать и везти в клинику, где возможно экстракорпоральное согревание",
    "q.l36#4.o1" to "Прекратить реанимацию",
    "q.l36#4.o2" to "Только согревать",
    "q.l36#4.o3" to "Ждать, пока температура поднимется, и потом решать",
    "q.l36#4.e" to "Ниже 30 ℃ при проходимых путях — попытку реанимации делают независимо от времени засыпания. Таким пострадавшим нужны условия согревания уровня ECLS.",
    "q.l36#5.p" to "Что в лавинном спасении считается обструкцией дыхательных путей?",
    "q.l36#5.o0" to "Рот и нос полностью забиты плотным снегом или крошкой",
    "q.l36#5.o1" to "Немного снега во рту",
    "q.l36#5.o2" to "Мокрота",
    "q.l36#5.o3" to "Кровь из носа",
    "q.l36#5.e" to "Определение должно быть строгим, потому что от него зависит, начинать ли реанимацию. При неопределённости считают пути проходимыми — это умолчание в пользу спасения.",
    "q.l36#6.p" to "Что верно про воздушный карман?",
    "q.l36#6.o0" to "С карманом выживаемость выше, но сам карман не является основанием решать, спасать ли",
    "q.l36#6.o1" to "Без кармана спасать не нужно",
    "q.l36#6.o2" to "С карманом человек точно выживет",
    "q.l36#6.o3" to "Карман определяет наличие обструкции",
    "q.l36#6.e" to "Редакция 2023 года прямо указывает: наличие кармана, плотность снега и глубина не должны менять действий. Они влияют на время, но не на решение.",
    "q.l36#7.p" to "Когда можно начинать непрямой массаж сердца?",
    "q.l36#7.o0" to "Не дожидаясь полной откопки: достаточно освободить грудную клетку",
    "q.l36#7.o1" to "Только после полной откопки",
    "q.l36#7.o2" to "Только в больнице",
    "q.l36#7.o3" to "Только после измерения температуры",
    "q.l36#7.e" to "«Подождём, пока откопают» — это потерянные минуты. Редакция 2023 года прямо говорит: эффективные компрессии возможны и при необычном положении тела, и пока человек ещё в снегу.",
    "q.l36#8.p" to "Почему спасательное дыхание нужно давать как можно раньше?",
    "q.l36#8.o0" to "Такие пострадавшие погибают почти всегда от асфиксии, и гипоксия здесь первая проблема",
    "q.l36#8.o1" to "Так удобнее",
    "q.l36#8.o2" to "Чтобы успокоить родственников",
    "q.l36#8.o3" to "Чтобы сэкономить кислород",
    "q.l36#8.e" to "Сначала вентиляция, потом кровообращение. В этом и физиологическая основа правила «до 60 минут независимо от путей».",
    "q.l36#9.p" to "Что обычно относят к показаниям к прекращению реанимации?",
    "q.l36#9.o0" to "Смертельная травма, полное замерзание, обструкция путей при засыпании более 60 минут, выраженная гиперкалиемия",
    "q.l36#9.o1" to "Требование родственников",
    "q.l36#9.o2" to "Наступление темноты",
    "q.l36#9.o3" to "Нехватка снаряжения",
    "q.l36#9.e" to "Эти показания взяты из редакции 2023 года и рекомендаций ICAR по прекращению реанимации. Решение принимает обученный человек, а не тот, кто копает.",
    "q.l36#10.p" to "В чём ошибка фразы «сначала посмотрим, как глубоко засыпало, и решим, спасать ли»?",
    "q.l36#10.o0" to "Глубина влияет на время раскопок, но не участвует в медицинском решении",
    "q.l36#10.o1" to "Глубину невозможно измерить",
    "q.l36#10.o2" to "Глубина всегда небольшая",
    "q.l36#10.o3" to "Глубина определяет выживаемость",
    "q.l36#10.e" to "Если принять инженерную задачу за медицинский критерий, люди сдаются раньше времени. Решение опирается только на время, дыхательные пути и температуру.",
    "q.l36#11.p" to "Какие факторы по редакции 2023 года участвуют в сортировке?",
    "q.l36#11.o0" to "Время засыпания",
    "q.l36#11.o1" to "Проходимость дыхательных путей",
    "q.l36#11.o2" to "Возможность измерить температуру ядра и её значение",
    "q.l36#11.o3" to "Глубина засыпания",
    "q.l36#11.e" to "Первые три образуют дерево решений. Четвёртый влияет лишь на то, сколько копать, и сортировку не меняет.",
    "q.l36#12.p" to "Что входит в действия при гипотермической остановке сердца?",
    "q.l36#12.o0" to "Перемещать бережно, избегая резких толчков",
    "q.l36#12.o1" to "Изолировать и утеплить всё тело",
    "q.l36#12.o2" to "Постоянно следить за ритмом сердца и температурой ядра",
    "q.l36#12.o3" to "Как можно скорее согреть на месте до 35 ℃ и только потом везти",
    "q.l36#12.e" to "Эффективно согреть на месте невозможно, а попытка «сначала согреть, потом ехать» только теряет время. Цель — как можно быстрее доставить в центр с ECLS.",
    "q.l36#13.p" to "Что верно в отношении дыхательных путей и вентиляции?",
    "q.l36#13.o0" to "Очистить рот и нос от снега и ледяной крошки",
    "q.l36#13.o1" to "При неопределённости считать пути проходимыми",
    "q.l36#13.o2" to "Сначала вентиляция, потом компрессии",
    "q.l36#13.o3" to "Оценивать дыхательные пути после полной откопки",
    "q.l36#13.e" to "Первые три пункта все ведут к ранней вентиляции. Последний откладывает самые важные минуты.",
    "q.l36#14.p" to "Расставьте порядок действий при засыпании не более 60 минут без признаков жизни.",
    "q.l36#14.o0" to "Очистить рот и нос, оценить дыхательные пути",
    "q.l36#14.o1" to "Немедленно начать спасательное дыхание",
    "q.l36#14.o2" to "Начать непрямой массаж сердца",
    "q.l36#14.o3" to "Утеплить, защитить позвоночник и организовать транспортировку",
    "q.l36#14.e" to "Вентиляция важнее компрессий — в этом главное отличие асфиксической остановки при лавине от обычной кардиогенной.",
    "q.l36#15.p" to "Расставьте порядок сортировки при засыпании более 60 минут.",
    "q.l36#15.o0" to "Убедиться, что время засыпания действительно больше 60 минут",
    "q.l36#15.o1" to "Оценить, полностью ли забиты дыхательные пути",
    "q.l36#15.o2" to "Попытаться измерить температуру ядра",
    "q.l36#15.o3" to "По соответствующей ветви решить, начинать ли реанимацию",
    "q.l36#15.e" to "Порядок отражает логику: сначала время, затем дыхательные пути, потом температура. Если на любом шаге данных нет, выбирают ветвь, более склонную к спасению.",
    "q.l36#16.p" to "Линия решения о реанимации по ICAR MedCom 2023 года — засыпание ______ минут.",
    "q.l36#16.a0" to "60",
    "q.l36#16.e" to "Прежние 35 минут отменены. Учебные материалы и банк вопросов должны быть приведены к 60 минутам.",
    "q.l36#17.p" to "При температуре ядра ниже ______ ℃ и проходимых дыхательных путях реанимацию пробуют независимо от времени засыпания.",
    "q.l36#17.a0" to "30",
    "q.l36#17.e" to "30 ℃ — параллельный критерий. Он вводит в решение окно защитного охлаждения.",
    "q.l36#18.p" to "Гипотермия даёт лишь 0–4 % смертей при лавинах, поэтому порядок действий — сначала ______, потом согревание.",
    "q.l36#18.a0" to "дыхание",
    "q.l36#18.a1" to "вентиляция",
    "q.l36#18.a2" to "проходимость дыхательных путей",
    "q.l36#18.e" to "Сначала вентиляция, потом согревание: в лавинном спасении этот порядок строже, чем при обычной гипотермии.",
    "q.l36#19.p" to "Соотнесите ситуацию засыпания с действием (редакция 2023 года).",
    "q.l36#19.l0" to "Не более 60 минут, признаков жизни нет",
    "q.l36#19.l1" to "Более 60 минут, пути проходимы, температуру измерить нельзя",
    "q.l36#19.l2" to "Более 60 минут, пути обтурированы, температуру измерить нельзя",
    "q.l36#19.l3" to "Температура измерима и ниже 30 ℃, пути проходимы",
    "q.l36#19.r0" to "Действовать как при асфиксии, как можно скорее дать спасательное дыхание",
    "q.l36#19.r1" to "Действовать как при гипотермической остановке, начать реанимацию",
    "q.l36#19.r2" to "Действовать как при асфиксической остановке, реанимацию не начинать",
    "q.l36#19.r3" to "Пробовать реанимацию независимо от времени и везти на ECLS",
    "q.l36#19.e" to "Четыре ветви покрывают почти все ситуации на месте. Запоминать условия ветвления надёжнее, чем заучивать выводы.",
    "q.l36#20.p" to "Соотнесите показание к прекращению реанимации с его смыслом.",
    "q.l36#20.l0" to "Смертельная травма",
    "q.l36#20.l1" to "Полное замерзание",
    "q.l36#20.l2" to "Обструкция путей при засыпании более 60 минут",
    "q.l36#20.l3" to "Выраженная гиперкалиемия",
    "q.l36#20.r0" to "Повреждения сами по себе несовместимы с жизнью",
    "q.l36#20.r1" to "Тело заморожено, согревание лишено смысла",
    "q.l36#20.r2" to "Действовать как при асфиксической остановке, реанимацию не начинать",
    "q.l36#20.r3" to "Указывает на длительную гипоксию и крайне плохой прогноз",
    "q.l36#20.e" to "Все четыре — свидетельства того, что ситуация уже медицински необратима. Решение должен принимать обученный человек и фиксировать его основание.",
    "q.l36#21.p" to "Кто-то на месте говорит: «Больше 35 минут — уже не спасаем». Как ответить?",
    "q.l36#21.o0" to "Это формулировка 2013 года; в редакции 2023-го линия смещена на 60 минут и добавлен температурный критерий",
    "q.l36#21.o1" to "Он прав",
    "q.l36#21.o2" to "Зависит от обстоятельств",
    "q.l36#21.o3" to "Пусть он и решает",
    "q.l36#21.e" to "В русскоязычных материалах 35 минут всё ещё встречаются очень часто. Обновление этой формулировки — одна из самых практичных ценностей такого курса.",
    "q.l36#22.p" to "Ситуация: засыпан 20 минут, при откопке дыхания нет, во рту и носу рыхлый снег, но заполнение не полное. Что делать в первую очередь?",
    "q.l36#22.o0" to "Очистить рот и нос, дать спасательное дыхание, начать компрессии, как можно скорее транспортировать",
    "q.l36#22.o1" to "Признать обструкцию и не реанимировать",
    "q.l36#22.o2" to "Сначала согревать",
    "q.l36#22.o3" to "Ждать решения профессиональной группы",
    "q.l36#22.e" to "До 60 минут и при отсутствии полной обструкции — действуют как при асфиксии и реанимируют в полную силу. Рыхлый снег обструкции не создаёт.",
    "q.l36#23.p" to "Ситуация: засыпан 70 минут, пути проходимы, температура ядра 28 ℃, признаков жизни нет. Что делать в первую очередь?",
    "q.l36#23.o0" to "Продолжать реанимацию, перемещать бережно, утеплить всё тело и везти в клинику с возможностью ECLS",
    "q.l36#23.o1" to "Прекратить реанимацию",
    "q.l36#23.o2" to "Только наблюдать, сохраняя тепло",
    "q.l36#23.o3" to "Сначала согреть до 35 ℃, потом везти",
    "q.l36#23.e" to "Суть гипотермической остановки в том, чтобы довезти до места, где возможно согревание; реанимацию в пути не прерывают.",
    "q.l36#24.p" to "Почему говорят, что охлаждённое сердце очень чувствительно?",
    "q.l36#24.o0" to "Резкое перемещение может спровоцировать фибрилляцию, поэтому переносят бережно и в горизонтальном положении",
    "q.l36#24.o1" to "Потому что человеку холодно",
    "q.l36#24.o2" to "Потому что пульс редкий",
    "q.l36#24.o3" to "Потому что давление низкое",
    "q.l36#24.e" to "Отсюда требование переносить «ровно, устойчиво, мягко», и это вторая причина, помимо защиты позвоночника, которую в лавинном спасении повторяют постоянно.",
    "q.l36#25.p" to "Участник сорвался эмоционально и требует прекратить реанимацию. Что делать руководителю?",
    "q.l36#25.o0" to "Вывести его из процесса, но реанимацию продолжать: решение по показаниям принимает обученный человек",
    "q.l36#25.o1" to "Немедленно прекратить",
    "q.l36#25.o2" to "Отчитать его",
    "q.l36#25.o3" to "Заставить продолжать компрессии",
    "q.l36#25.e" to "Эмоции нужно принять, но медицинское решение не может определяться эмоциями. Заменить человека, а не остановить руки — более ответственный шаг.",
    "q.l38#0.p" to "Каково первое правило раскопок?",
    "q.l38#0.o0" to "Всегда работать с низовой стороны",
    "q.l38#0.o1" to "Копать сверху вниз",
    "q.l38#0.o2" to "Копать с наветренной стороны вниз",
    "q.l38#0.o3" to "Копать сбоку горизонтально",
    "q.l38#0.e" to "Работа с низовой стороны даёт три преимущества: снег летит вниз, у канала есть уклон, и копающий не находится над пострадавшим.",
    "q.l38#1.p" to "Что описывает традиционная формула «1,5 глубины засыпания»?",
    "q.l38#1.o0" to "Расстояние, на которое отступают от щупа вниз по склону",
    "q.l38#1.o1" to "Ширину канала",
    "q.l38#1.o2" to "Длину щупа",
    "q.l38#1.o3" to "Время раскопок",
    "q.l38#1.e" to "Отступ нужен, чтобы было куда выносить снег. Это эмпирическое правило, и новые исследования предлагают альтернативу.",
    "q.l38#2.p" to "Что предлагает исследование снежного конвейера 2023 года насчёт точки начала раскопок?",
    "q.l38#2.o0" to "Если людей трое и больше и места хватает, копать сразу от щупа вниз по линии падения",
    "q.l38#2.o1" to "Всегда отступать на 1,5 глубины",
    "q.l38#2.o2" to "Копать сверху",
    "q.l38#2.o3" to "Копать сбоку горизонтально",
    "q.l38#2.e" to "Смещение точки начала удлиняет путь до головы. Вывод исследования опирается на условие «людей достаточно» и не переносится безоговорочно.",
    "q.l38#3.p" to "В каких случаях смещение точки начала действительно оправдано?",
    "q.l38#3.o0" to "Засыпание очень неглубокое и ноги ушли почти на ту же глубину, либо людей не хватает и нужен вариант для одного",
    "q.l38#3.o1" to "В любом случае",
    "q.l38#3.o2" to "Когда снег жёсткий",
    "q.l38#3.o3" to "Когда стемнело",
    "q.l38#3.e" to "В этих двух случаях смещение сокращает бесполезный перенос. В остальных быстрее копать от щупа.",
    "q.l38#4.p" to "Какова обычная ширина канала конвейера?",
    "q.l38#4.o0" to "1–2 м",
    "q.l38#4.o1" to "0,3 м",
    "q.l38#4.o2" to "3–4 м",
    "q.l38#4.o3" to "Чем уже, тем лучше",
    "q.l38#4.e" to "Слишком узкий канал снижает эффективность выноса, слишком широкий резко увеличивает объём работы. 1–2 м — точка равновесия.",
    "q.l38#5.p" to "При каком примерно уклоне канала снег скатывается обратно к щупу?",
    "q.l38#5.o0" to "Меньше 26 градусов",
    "q.l38#5.o1" to "Меньше 10 градусов",
    "q.l38#5.o2" to "Меньше 45 градусов",
    "q.l38#5.o3" to "Меньше 60 градусов",
    "q.l38#5.e" to "26 градусов — критическое значение из исследования. Если уклона не хватает, выброшенный снег сползает обратно, и работа идёт впустую.",
    "q.l38#6.p" to "Какой из трёх приёмов переноса снега самый эффективный?",
    "q.l38#6.o0" to "Сгребание (paddling)",
    "q.l38#6.o1" to "Зачерпывание (scooping)",
    "q.l38#6.o2" to "Нарезание блоков (cutting blocks)",
    "q.l38#6.o3" to "Все одинаково",
    "q.l38#6.e" to "Сгребание — это выметание снега: движение непрерывное и частое. Нарезание блоков подходит только для жёсткого снега, потому что сначала нужно нарубить блоки.",
    "q.l38#7.p" to "Зачем при раскопках назначают одного руководителя?",
    "q.l38#7.o0" to "Смотреть за направлением, за состоянием снега сверху и за положением пострадавшего, чтобы никто не копал уткнувшись вниз",
    "q.l38#7.o1" to "Контролировать работу",
    "q.l38#7.o2" to "Фотографировать",
    "q.l38#7.o3" to "Экономить силы",
    "q.l38#7.e" to "Как только все копающие опускают голову, канал уводит в сторону и никто не замечает повторную лавину. Руководитель — единственный, кто смотрит вверх.",
    "q.l38#8.p" to "Как меняется порядок действий после того, как добрались до лица?",
    "q.l38#8.o0" to "Сначала очистить рот и нос и проверить дыхательные пути, затем грудь и руки, в конце ноги и тело",
    "q.l38#8.o1" to "Сначала ноги",
    "q.l38#8.o2" to "Сначала тянуть за плечи",
    "q.l38#8.o3" to "Сначала освободить рюкзак",
    "q.l38#8.e" to "Грудная клетка должна иметь возможность расширяться, иначе вентиляции нет. Освобождать ноги первыми — значит отложить дыхание, а тянуть за плечи — рисковать позвоночником.",
    "q.l38#9.p" to "На чём основано утверждение «спасти может и один человек»?",
    "q.l38#9.o0" to "В условиях исследования один человек по схеме конвейера с ограниченными силами добирается до глубины 1,5 м за 18 минут",
    "q.l38#9.o1" to "Потому что у человека есть скрытые силы",
    "q.l38#9.o2" to "Потому что снег лёгкий",
    "q.l38#9.o3" to "Потому что пострадавший поможет себе сам",
    "q.l38#9.e" to "Скорость около 13,2 см/мин на жёстком снегу и 25,3 см/мин на мягком — это данные исследования, и они объясняют, почему вариант для одного стоит отрабатывать.",
    "q.l38#10.p" to "Какова примерно скорость копания на жёстком и мягком снегу?",
    "q.l38#10.o0" to "Около 13 см/мин на жёстком и 25 см/мин на мягком",
    "q.l38#10.o1" to "Около 5 см/мин в обоих случаях",
    "q.l38#10.o2" to "Около 50 см/мин в обоих случаях",
    "q.l38#10.o3" to "На жёстком быстрее",
    "q.l38#10.e" to "Эта разница объясняет, почему состояние снега меняет ожидаемое время спасения, и почему нарезание блоков применяют только на жёстком снегу.",
    "q.l38#11.p" to "Какая ошибка при коллективных раскопках встречается чаще всего?",
    "q.l38#11.o0" to "Все сбиваются в одну точку, без эстафеты и смены",
    "q.l38#11.o1" to "Копают слишком широко",
    "q.l38#11.o2" to "Копают слишком быстро",
    "q.l38#11.o3" to "Используют лопату",
    "q.l38#11.e" to "Сбившись в кучу, люди мешают друг другу и не могут работать долго. Смена и эстафета дают скорость гораздо быстрее, чем один герой.",
    "q.l38#12.p" to "Какие роли нужно распределить при организации раскопок?",
    "q.l38#12.o0" to "Руководитель раскопок",
    "q.l38#12.o1" to "Копающие и выносящие снег",
    "q.l38#12.o2" to "Наблюдатель за безопасностью",
    "q.l38#12.o3" to "Тот, кто фиксирует время и место",
    "q.l38#12.e" to "Четыре роли закрывают направление, силы, безопасность и время. Стоит пропустить одну — и соответствующее звено выходит из-под контроля.",
    "q.l38#13.p" to "Какие действия возвращают выброшенный снег обратно?",
    "q.l38#13.o0" to "Копать сверху или с наветренной стороны",
    "q.l38#13.o1" to "Слишком малый уклон канала, меньше примерно 26 градусов",
    "q.l38#13.o2" to "Складывать снег выше щупа",
    "q.l38#13.o3" to "Располагать канал вдоль линии падения",
    "q.l38#13.e" to "Первые три приводят к возврату снега. Четвёртый пункт как раз правильное решение.",
    "q.l38#14.p" to "Какие утверждения о точке начала раскопок верны?",
    "q.l38#14.o0" to "Традиционная формула: 1,5 глубины и выход с низовой стороны",
    "q.l38#14.o1" to "Упрощение Avalanche.org: при глубине меньше 1 м отступить на шаг, при большей — на два",
    "q.l38#14.o2" to "ISSW 2023: при достаточном числе людей копать от щупа вдоль линии падения",
    "q.l38#14.o3" to "Формула и выводы исследования полностью противоречат друг другу, нужно выбрать одно",
    "q.l38#14.e" to "Три формулировки — это принцип плюс опыт двух поколений. Излагать так: принцип, формула, обновление — тогда формула не превращается в суеверие.",
    "q.l38#15.p" to "Расставьте порядок стандартных раскопок.",
    "q.l38#15.o0" to "Определить рабочую площадку с низовой стороны и оценить риск повторной лавины",
    "q.l38#15.o1" to "Пробить от точки начала V-образный канал в сторону щупа",
    "q.l38#15.o2" to "Организовать эстафету выноса снега и смену",
    "q.l38#15.o3" to "Добравшись до лица, в первую очередь очистить рот и нос",
    "q.l38#15.e" to "Логика порядка: сначала безопасность, затем эффективность, и в конце приоритет дыхательных путей.",
    "q.l38#16.p" to "Расставьте порядок действий после того, как добрались до лица.",
    "q.l38#16.o0" to "Очистить рот и нос от снега и ледяной крошки, проверить дыхательные пути",
    "q.l38#16.o1" to "Освободить грудь и руки, чтобы грудная клетка могла расширяться",
    "q.l38#16.o2" to "Освободить ноги и остальное тело",
    "q.l38#16.o3" to "Действовать по правилам реанимации и организовать транспортировку",
    "q.l38#16.e" to "Этот порядок противоположен принципу «сначала откопать, потом спасать», но верен именно он: окно для вентиляции измеряется минутами.",
    "q.l38#17.p" to "Критический уклон канала снежного конвейера — около ______ градусов.",
    "q.l38#17.a0" to "26",
    "q.l38#17.e" to "При меньшем угле снег скатывается обратно к щупу, и эффективность выноса резко падает.",
    "q.l38#18.p" to "Традиционная формула советует начинать копать, отступив от щупа вниз по склону примерно на ______ глубины засыпания.",
    "q.l38#18.a0" to "1,5",
    "q.l38#18.a1" to "1.5",
    "q.l38#18.e" to "1,5 — эмпирическое правило. Когда людей достаточно, стоит предпочесть начало от щупа вдоль линии падения.",
    "q.l38#19.p" to "Целевое время при спасении партнёрами — добраться до человека за ______ минут и откопать за 18 минут.",
    "q.l38#19.a0" to "10",
    "q.l38#19.e" to "10 и 18 — внутренние ориентиры для тренировок и разбора, чтобы понимать, на каком этапе возникло отставание.",
    "q.l38#20.p" to "Соотнесите приём переноса снега с условиями применения.",
    "q.l38#20.l0" to "Сгребание (paddling)",
    "q.l38#20.l1" to "Зачерпывание (scooping)",
    "q.l38#20.l2" to "Нарезание блоков (cutting blocks)",
    "q.l38#20.l3" to "Эстафета (conveyor)",
    "q.l38#20.r0" to "Самый эффективный, подходит для большинства рыхлого снега",
    "q.l38#20.r1" to "Следующий по эффективности, годится для выноса снега из канала",
    "q.l38#20.r2" to "Самый медленный, только для жёсткого снега",
    "q.l38#20.r3" to "Способ организации работы при нескольких людях",
    "q.l38#20.e" to "Порядок эффективности задаёт правило: сначала сгребать, потом зачерпывать, блоки — только на жёстком снегу. Эстафета не приём, а организация.",
    "q.l38#21.p" to "Соотнесите типичную ошибку с её последствием.",
    "q.l38#21.l0" to "Копать с наветренной стороны",
    "q.l38#21.l1" to "Слишком малый уклон канала",
    "q.l38#21.l2" to "Тянуть тело, добравшись до человека",
    "q.l38#21.l3" to "Выдернуть щуп после обнаружения",
    "q.l38#21.r0" to "Снег скатывается на лицо: медленно и опасно",
    "q.l38#21.r1" to "Снег возвращается, приходится выносить его повторно",
    "q.l38#21.r2" to "Возможна травма позвоночника и попадание снега в рот и нос",
    "q.l38#21.r3" to "Теряется ориентир по месту и глубине",
    "q.l38#21.e" to "Все четыре ошибки очень распространены и все предотвращаются заранее отработанной схемой.",
    "q.l38#22.p" to "Снег жёсткий, в группе всего три человека. Где начинать копать?",
    "q.l38#22.o0" to "От щупа вдоль линии падения, на жёстком участке пробивать путь нарезанием блоков",
    "q.l38#22.o1" to "Отступить на 3 глубины",
    "q.l38#22.o2" to "Копать сверху",
    "q.l38#22.o3" to "Ждать оборудование",
    "q.l38#22.e" to "Людей достаточно — значит вдоль линии падения; жёсткий снег меняет только приём, но не принцип.",
    "q.l38#23.p" to "Почему «все вместе навалились и копают» выходит не быстрее?",
    "q.l38#23.o0" to "Люди мешают друг другу, не могут работать долго, и никто не следит за снегом сверху",
    "q.l38#23.o1" to "Потому что от толпы жарко",
    "q.l38#23.o2" to "Потому что не хватает лопат",
    "q.l38#23.o3" to "Потому что нет руководителя",
    "q.l38#23.e" to "Копать — работа очень высокой интенсивности, силы кончаются за минуты. Смена, руководство и эстафета и превращают человеческие силы в скорость.",
    "q.l38#24.p" to "При раскопках рядом с пострадавшим обнаружен большой плотный снежный блок. Как поступить?",
    "q.l38#24.o0" to "Сначала расчистить путь к дыхательным путям, не откладывая вентиляцию ради переноса блока",
    "q.l38#24.o1" to "Сначала убрать блок",
    "q.l38#24.o2" to "Разбить его ледорубом",
    "q.l38#24.o3" to "Обойти его",
    "q.l38#24.e" to "Большим блоком можно заняться позже. Окно для дыхательных путей измеряется минутами, и приоритет у него выше, чем у «расчистки места».",
    "q.l38#25.p" to "На месте всего одна лопата. Что делать?",
    "q.l38#25.o0" to "Копает самый сильный, остальные отгребают руками и лыжами, со сменой",
    "q.l38#25.o1" to "Один копает до конца",
    "q.l38#25.o2" to "Ждать вторую лопату",
    "q.l38#25.o3" to "Заменить лопату рюкзаком",
    "q.l38#25.e" to "Правильный вариант для одного копающего — это и есть конвейер при ограниченных ресурсах: один копает, остальные выносят снег.",
    "q.l38#26.p" to "На разборе выяснилось, что «до контакта прошло 14 минут». Какой этап стоит разбирать в первую очередь?",
    "q.l38#26.o0" to "Поиск и обнаружение: какая из четырёх стадий шла медленно",
    "q.l38#26.o1" to "Раскопки",
    "q.l38#26.o2" to "Вызов помощи",
    "q.l38#26.o3" to "Закупку снаряжения",
    "q.l38#26.e" to "Время до контакта определяется поиском и обнаружением, а раскопки определяют время до извлечения. Эти два показателя нужно смотреть отдельно.",
    "q.m17#16.p" to "Зачем нужна ротация грузов между высотными лагерями?",
    "q.m17#16.o0" to "Чтобы в каждом лагере было ровно столько, сколько нужно, без скопления в одном месте и провала в другом",
    "q.m17#16.o1" to "Чтобы уменьшить вес",
    "q.m17#16.o2" to "Чтобы удобнее считать",
    "q.m17#16.o3" to "Для соблюдения формальностей",
    "q.m17#16.e" to "В экспедиции грузы выдаются порциями по участкам. Без таблицы ротации типичный итог — нехватка газа в верхнем лагере перед выходом на вершину.",
    "q.m17#17.p" to "Как оценивать запас топлива для лагеря?",
    "q.m17#17.o0" to "Число людей × число дней × норма на человека в день (больше всего уходит на таяние снега)",
    "q.m17#17.o1" to "По количеству баллонов",
    "q.m17#17.o2" to "По весу",
    "q.m17#17.o3" to "На глаз",
    "q.m17#17.e" to "Таяние снега — самая большая статья расхода топлива на высоте. Считать нужно по самой холодной погоде, а не по идеальным условиям.",
    "q.m17#18.p" to "На что обращают внимание при усилении палатки под сильным ветром?",
    "q.m17#18.o0" to "На угол оттяжек, точки крепления с наветренной стороны и присыпание юбки снегом",
    "q.m17#18.o1" to "На цвет палатки",
    "q.m17#18.o2" to "На молнию внутренней палатки",
    "q.m17#18.o3" to "На толщину коврика",
    "q.m17#18.e" to "Палатку обычно ломает не разрыв ткани, а отказ одной точки крепления. Ставить двойные оттяжки с наветренной стороны и прижимать юбку снежными блоками — обычная практика.",
    "q.m17#19.p" to "Каковы достоинство и риск снежной пещеры на склоне?",
    "q.m17#19.o0" to "Хорошо держит ветер и тепло; но есть риск обрушения и отравления угарным газом",
    "q.m17#19.o1" to "Экономит палатку; но слишком холодно",
    "q.m17#19.o2" to "Удобно; но незаконно",
    "q.m17#19.o3" to "Риска нет",
    "q.m17#19.e" to "Пещере нужны вентиляционное отверстие и оценка толщины потолка. Горелка в закрытой пещере — типичный сценарий отравления угарным газом.",
    "q.m17#20.p" to "Что опаснее всего при использовании горелки в палатке?",
    "q.m17#20.o0" to "Отравление угарным газом и пожар",
    "q.m17#20.o1" to "Влага",
    "q.m17#20.o2" to "Холод, не связанный с нехваткой кислорода",
    "q.m17#20.o3" to "Деформация палатки",
    "q.m17#20.e" to "Угарный газ не имеет цвета и запаха, а симптомы похожи на высотную болезнь. Вентиляция обязательна, и работать лучше в тамбуре или снаружи.",
    "q.m17#21.p" to "Каково правило обращения с мусором в высотном лагере?",
    "q.m17#21.o0" to "Выносить всё вниз, не закапывать и не сжигать в высотном лагере",
    "q.m17#21.o1" to "Закапывать в снег",
    "q.m17#21.o2" to "Сжигать",
    "q.m17#21.o3" to "Оставлять следующей группе",
    "q.m17#21.e" to "На высоте разложение идёт крайне медленно, и закопанное или сожжённое всё равно выйдет на поверхность при таянии. Вынести вниз — единственный корректный вариант.",
    "q.m17#22.p" to "Как ускорить получение воды из снега?",
    "q.m17#22.o0" to "Сначала налить немного воды, потом добавить снег, и на сильном огне, не давая гореть всухую",
    "q.m17#22.o1" to "Сразу набить полную кастрюлю снега",
    "q.m17#22.o2" to "Топить на слабом огне",
    "q.m17#22.o3" to "Топить холодной водой",
    "q.m17#22.e" to "Сухой нагрев прижигает дно и крайне неэффективен. «Немного воды как затравка плюс сильный огонь» заметно экономит и топливо, и время.",
    "q.m17#23.p" to "Как планировать высоту ночёвок в высотных лагерях?",
    "q.m17#23.o0" to "По возможности чередовать по плану и не ночевать в верхнем лагере много раз подряд",
    "q.m17#23.o1" to "Чем выше, тем лучше",
    "q.m17#23.o2" to "Всегда спать в самом верхнем лагере",
    "q.m17#23.o3" to "Как получится",
    "q.m17#23.e" to "Чередование совмещает акклиматизацию и восстановление. Постоянные ночёвки наверху накапливают усталость и, наоборот, замедляют общий темп.",
    "q.l39#0.p" to "Каково самое точное определение лидерства?",
    "q.l39#0.o0" to "Поведение, которое влияет на других и делает так, чтобы группа хотела вместе достичь цели",
    "q.l39#0.o1" to "Слова человека с должностью",
    "q.l39#0.o2" to "Самый сильный ведёт группу",
    "q.l39#0.o3" to "Решает самый опытный",
    "q.l39#0.e" to "Если считать лидерство поведением, а не должностью, в группе появляется больше людей, готовых предупредить, — а это часть запаса безопасности.",
    "q.l39#1.p" to "Как распределены роли профессиональных и коммуникативных навыков?",
    "q.l39#1.o0" to "Профессиональные определяют, можно ли сделать, коммуникативные — захотят ли люди делать это вместе",
    "q.l39#1.o1" to "Профессиональные важнее",
    "q.l39#1.o2" to "Коммуникативные — только вежливость",
    "q.l39#1.o3" to "Они не связаны",
    "q.l39#1.e" to "Технически уметь, но не получить исполнения — значит не сделать. В горах долю исполнения определяют именно коммуникативные навыки.",
    "q.l39#2.p" to "Что означают три уровня ответственности?",
    "q.l39#2.o0" to "Поведение, мышление, чувства",
    "q.l39#2.o1" to "План, исполнение, разбор",
    "q.l39#2.o2" to "Лидер, помощник, участник",
    "q.l39#2.o3" to "Подъём, вершина, спуск",
    "q.l39#2.e" to "Глядя только на поведение, теряешь способ оценки и эмоциональное состояние. У многих повторяющихся проблем корень на втором и третьем уровнях.",
    "q.l39#3.p" to "Что показывает модель айсберга в конфликте?",
    "q.l39#3.o0" to "На поверхности позиция, под водой потребность",
    "q.l39#3.o1" to "Все конфликты из-за характера",
    "q.l39#3.o2" to "Конфликт неразрешим",
    "q.l39#3.o3" to "Молчание означает отсутствие конфликта",
    "q.l39#3.e" to "«Я обязан взойти» — это позиция, а под ней может быть «не хочу подвести партнёров». Отвечая на потребность, вы даёте позиции пространство для изменения.",
    "q.l39#4.p" to "В чём риск ореола эксперта?",
    "q.l39#4.o0" to "Уверенность и профессиональное снаряжение принимают за компетентность, и никто не решается оспорить явную ошибку",
    "q.l39#4.o1" to "Эксперт слишком дорог",
    "q.l39#4.o2" to "Эксперт не слушается",
    "q.l39#4.o3" to "Эксперт слаб физически",
    "q.l39#4.e" to "Ореол подавляет сомнение. Самое опасное состояние в группе — не когда никто не понимает, а когда никто не решается сказать «стоп, здесь что-то не так».",
    "q.l39#5.p" to "Какова важнейшая обязанность ведомого?",
    "q.l39#5.o0" to "Спрашивать, давать обратную связь и ясно говорить «стоп», когда пора остановиться",
    "q.l39#5.o1" to "Полностью подчиняться",
    "q.l39#5.o2" to "Не создавать хлопот",
    "q.l39#5.o3" to "Молчать",
    "q.l39#5.e" to "Право сказать «стоп» должно быть у каждого, а не только у руководителя. Это право нужно явно выдать до выхода.",
    "q.l39#6.p" to "Когда нужно определять время возврата (turnaround time)?",
    "q.l39#6.o0" to "До выхода, и так, чтобы его знала вся группа",
    "q.l39#6.o1" to "Перед вершиной",
    "q.l39#6.o2" to "По настроению",
    "q.l39#6.o3" to "Пусть решает самый быстрый",
    "q.l39#6.e" to "Срок, назначенный в горах, под усталостью и давлением цели почти наверняка сдвинут. Только заданный до выхода он имеет силу.",
    "q.l39#7.p" to "Как типично проявляется злоупотребление ролью руководителя?",
    "q.l39#7.o0" to "Должностью подавляют оценку, а сомнение считают неподчинением",
    "q.l39#7.o1" to "Слушает мнения",
    "q.l39#7.o2" to "Открыто объясняет основания решений",
    "q.l39#7.o3" to "Признаёт свою неуверенность",
    "q.l39#7.e" to "Прямое следствие подавления — информация перестаёт подниматься наверх. А самый важный вход для руководителя идёт именно от тех, кто решается сказать.",
    "q.l39#8.p" to "Один участник всё время молчит. Какова наиболее вероятная причина?",
    "q.l39#8.o0" to "Считает, что это ничего не изменит, или боится испортить отношения",
    "q.l39#8.o1" to "У него нет мыслей",
    "q.l39#8.o2" to "Не хватает сил",
    "q.l39#8.o3" to "Не понимает языка",
    "q.l39#8.e" to "Молчание обычно означает, что высказываться слишком дорого. Руководителю стоит самому снизить эту цену — например, спросить первым самого младшего.",
    "q.l39#9.p" to "Каков обычно первый шаг в разрешении конфликта?",
    "q.l39#9.o0" to "Установить доверие: сначала дать человеку почувствовать, что его услышали",
    "q.l39#9.o1" to "Объяснять логику",
    "q.l39#9.o2" to "Голосовать",
    "q.l39#9.o3" to "Менять людей",
    "q.l39#9.e" to "Без доверия логика воспринимается как упрёк. Сначала принять эмоцию, потом говорить о фактах и решениях.",
    "q.l39#10.p" to "Что важнее, когда «довести группу до цели» конфликтует с «сохранить всех целыми»?",
    "q.l39#10.o0" to "Безопасность: цель можно достичь в другой раз",
    "q.l39#10.o1" to "Цель",
    "q.l39#10.o2" to "Решает голосование",
    "q.l39#10.o3" to "Решает тот, кто платит",
    "q.l39#10.e" to "Цель можно повторить, человека нельзя. В коммерческих группах это особенно легко искажается давлением прибыли.",
    "q.l39#11.p" to "Что относится к проявлениям коммуникативных навыков?",
    "q.l39#11.o0" to "Ясно объяснять основания решения",
    "q.l39#11.o1" to "Сохранять общение под давлением",
    "q.l39#11.o2" to "Самому спрашивать мнение молчащих",
    "q.l39#11.o3" to "Взойти быстрее всех",
    "q.l39#11.e" to "Первые три пункта — про то, чтобы информация двигалась. Скорость — это способность, а не лидерство.",
    "q.l39#12.p" to "Что снижает риск ореола эксперта?",
    "q.l39#12.o0" to "Поощрять вопросы новичков",
    "q.l39#12.o1" to "Объяснять причины решений",
    "q.l39#12.o2" to "Назначить одного человека «адвокатом дьявола»",
    "q.l39#12.o3" to "Давать слово только самым опытным",
    "q.l39#12.e" to "Первые три создают легитимность сомнения. Последний пункт, наоборот, усиливает ореол.",
    "q.l39#13.p" to "Что относится к правомерным действиям ведомого?",
    "q.l39#13.o0" to "Высказывать иное мнение",
    "q.l39#13.o1" to "Требовать объяснения решения",
    "q.l39#13.o2" to "Отказаться идти дальше, если считаешь это небезопасным",
    "q.l39#13.o3" to "Жаловаться втихую, но не высказываться",
    "q.l39#13.e" to "Жалобы втихую решение не меняют, они лишь накапливают недоверие. Первые три пункта — это конструктивное неподчинение.",
    "q.l39#14.p" to "Расставьте порядок работы с конфликтом.",
    "q.l39#14.o0" to "Дать человеку договорить и подтвердить, что именно вы услышали",
    "q.l39#14.o1" to "Отделить позицию от потребности",
    "q.l39#14.o2" to "Предложить варианты и назвать их цену",
    "q.l39#14.o3" to "Договориться и пересказом подтвердить договорённость",
    "q.l39#14.e" to "Ключевой здесь второй шаг: если потребность не выявлена, решение сведётся к «взаимным уступкам» и скоро вернётся.",
    "q.l39#15.p" to "Расставьте порядок принятия рискованного решения.",
    "q.l39#15.o0" to "Определить цель и то, в чём уступать нельзя",
    "q.l39#15.o1" to "Перечислить варианты и их цену",
    "q.l39#15.o2" to "Оценить произведение вероятности на последствия",
    "q.l39#15.o3" to "Задать срок и его соблюдать",
    "q.l39#15.o4" to "Скорректировать решение по новой информации",
    "q.l39#15.e" to "Это каркас процесса из девяти шагов. Настоящая ценность в четвёртом: превратить «когда надо поворачивать» в число, заданное заранее.",
    "q.l39#16.p" to "Заданное заранее время возврата по-английски обычно называют ______ time.",
    "q.l39#16.a0" to "turnaround",
    "q.l39#16.e" to "Это инструмент, превращающий решимость в правило. Только записанное и озвученное оно имеет силу.",
    "q.l39#17.p" to "Три уровня ответственности — поведение, мышление и ______.",
    "q.l39#17.a0" to "чувства",
    "q.l39#17.a1" to "эмоции",
    "q.l39#17.e" to "Из трёх уровней чаще всего забывают чувства, а именно они первыми подают сигнал о проблеме.",
    "q.l39#18.p" to "Соотнесите роль с её основной задачей.",
    "q.l39#18.l0" to "Руководитель",
    "q.l39#18.l1" to "Помощник и гид",
    "q.l39#18.l2" to "Участник",
    "q.l39#18.l3" to "Наблюдатель за безопасностью",
    "q.l39#18.r0" to "Задаёт цель и границы, делает решения понятными",
    "q.l39#18.r1" to "Выполняет технические действия, передаёт информацию с места",
    "q.l39#18.r2" to "Спрашивает, даёт обратную связь, при необходимости говорит «стоп»",
    "q.l39#18.r3" to "Следит только за опасностями среды, не участвуя в работе",
    "q.l39#18.e" to "Четыре роли вместе дают информацию, исполнение и противовес. Без противовеса решение превращается в единоличное.",
    "q.l39#19.p" to "Соотнесите проявление конфликта с потребностью под водой.",
    "q.l39#19.l0" to "«Я обязательно должен взойти»",
    "q.l39#19.l1" to "«Мне всё равно, решайте вы»",
    "q.l39#19.l2" to "«Со мной всё нормально»",
    "q.l39#19.l3" to "«Он вечно тормозит группу»",
    "q.l39#19.r0" to "Боится, что партнёры его не уважают; нуждается в признании",
    "q.l39#19.r1" to "Не хочет брать на себя ответственность за решение; нуждается в защите",
    "q.l39#19.r2" to "Не хочет быть обузой; нуждается в заботе",
    "q.l39#19.r3" to "Тревожится за темп; нуждается в определённости",
    "q.l39#19.e" to "Четыре проявления соответствуют четырём потребностям. Только отвечая на потребность, можно изменить поведение.",
    "q.l39#20.p" to "Самый опытный в группе говорит: «Я ходил этой дорогой, всё нормально», но по карте впереди ледопад. Что делать?",
    "q.l39#20.o0" to "Предложить вместе сверить карту и рельеф, скорректировав опыт фактами",
    "q.l39#20.o1" to "Просто поверить ему",
    "q.l39#20.o2" to "Опровергнуть его при всех",
    "q.l39#20.o3" to "Разделиться",
    "q.l39#20.e" to "Опыт — ценный вход, а не вывод. Сверка с картой и рельефом и уважает его, и не превращается в слепое подчинение.",
    "q.l39#21.p" to "Участник повторяет «мне всё равно, как хотите». Как поступить разумнее?",
    "q.l39#21.o0" to "Дать конкретные варианты на выбор, а не открытый вопрос",
    "q.l39#21.o1" to "Считать, что ему действительно всё равно",
    "q.l39#21.o2" to "Больше не спрашивать",
    "q.l39#21.o3" to "Решить за него и потом сообщить",
    "q.l39#21.e" to "«Всё равно» обычно означает «не хочу нести последствия выбора». Конкретные варианты снижают цену высказывания, и информация выходит наружу.",
    "q.l39#22.p" to "Приняв решение развернуться, что руководителю важнее всего объяснить?",
    "q.l39#22.o0" to "Основание (что именно увидели), границы (при каких условиях пересмотрим) и дальнейшие шаги",
    "q.l39#22.o1" to "Только то, что разворота не избежать",
    "q.l39#22.o2" to "Только свои эмоции",
    "q.l39#22.o3" to "Ничего не объяснять",
    "q.l39#22.e" to "Объяснение оснований превращает подчинение в понимание. А понимающий человек в следующий раз сам принесёт информацию.",
    "q.l39#23.p" to "Почему «голосование о продолжении подъёма» технически ненадёжно?",
    "q.l39#23.o0" to "У большинства может не быть нужной для оценки информации, а давление искажает высказывания",
    "q.l39#23.o1" to "Голосование слишком медленное",
    "q.l39#23.o2" to "Людей не хватает",
    "q.l39#23.o3" to "Руководитель против",
    "q.l39#23.e" to "Голосование превращает решение в распределение мнений, тогда как в горах оно опирается на информацию и критерии. Мнения собирать можно, но суждение должно иметь основание.",
    "q.l39#24.p" to "В группе возникло молчание «никто не хочет быть плохим». Что прорвёт его эффективнее всего?",
    "q.l39#24.o0" to "Руководителю первому открыто назвать своё сомнение, сделав его предметом обсуждения",
    "q.l39#24.o1" to "Публично отчитать",
    "q.l39#24.o2" to "Продолжать ждать",
    "q.l39#24.o3" to "Развернуться без объяснений",
    "q.l39#24.e" to "Первый, кто назвал сомнение, заметно снижает цену высказывания для остальных. Руководитель подходит на эту роль лучше всех.",
    "q.l39#25.p" to "Если руководитель сам ошибся и это создало опасность, что важнее всего сделать?",
    "q.l39#25.o0" to "Открыто разобрать ошибку и сказать, что изменено, а не смягчать её",
    "q.l39#25.o1" to "Не упоминать",
    "q.l39#25.o2" to "Списать на погоду",
    "q.l39#25.o3" to "Сменить тему",
    "q.l39#25.e" to "Признание ошибки повышает доверие, а не понижает. Смягчение учит группу скрывать — и вот это по-настоящему опасно.",
    "q.l40#0.p" to "Каково первое правило питания на высоте?",
    "q.l40#0.o0" to "Обеспечить углеводы: важнее всего суметь их съесть",
    "q.l40#0.o1" to "Приоритет белкам",
    "q.l40#0.o2" to "Приоритет жирам",
    "q.l40#0.o3" to "Есть меньше, чтобы не тяжело было идти",
    "q.l40#0.e" to "Углеводы дают энергию быстро и требуют меньше кислорода — на высоте это самый выгодный источник. Когда аппетита нет, сначала найдите способ съесть именно углеводы.",
    "q.l40#1.p" to "У какого из трёх источников энергии наибольшая энергетическая плотность?",
    "q.l40#1.o0" to "У жиров",
    "q.l40#1.o1" to "У углеводов",
    "q.l40#1.o2" to "У белков",
    "q.l40#1.o3" to "У всех одинаково",
    "q.l40#1.e" to "У жира около 9 ккал/г, это более чем вдвое больше, чем у углеводов и белков. Именно поэтому на высоте любят орехи и масляные смеси.",
    "q.l40#2.p" to "В чём проблема идеи «переключиться на жировое питание уже в горах»?",
    "q.l40#2.o0" to "Долю жиров поднимают длительной тренировкой, за короткий срок переключиться нельзя",
    "q.l40#2.o1" to "Жир невкусный",
    "q.l40#2.o2" to "Жир слишком тяжёлый",
    "q.l40#2.o3" to "От жира зябнут",
    "q.l40#2.e" to "Метаболическая адаптация измеряется неделями и месяцами. Предпоходная подготовка повышает использование жиров, но ждать этого эффекта на горе нельзя.",
    "q.l40#3.p" to "Что эффективнее всего при падении аппетита на высоте?",
    "q.l40#3.o0" to "Есть дробно и часто, выбирая калорийную и легко идущую еду",
    "q.l40#3.o1" to "Заставлять себя съедать три больших приёма",
    "q.l40#3.o2" to "Пить только спортивные напитки",
    "q.l40#3.o3" to "Ждать, пока проголодаешься",
    "q.l40#3.e" to "Когда аппетита нет, «съесть много за раз» практически невозможно. Разбить общий объём на много небольших порций — единственный устойчивый подход.",
    "q.l40#4.p" to "Какова основная роль питания «на ходу»?",
    "q.l40#4.o0" to "Поддерживать темп: энергию можно получать, не останавливаясь",
    "q.l40#4.o1" to "Давать ощущение сытости",
    "q.l40#4.o2" to "Восполнять белок",
    "q.l40#4.o3" to "Заменять полноценный приём пищи",
    "q.l40#4.e" to "Как только приходится останавливаться, чтобы поесть, ритм рвётся. Ценность гелей, конфет и батончиков именно в том, что они не прерывают движение.",
    "q.l40#5.p" to "Как обезвоживание влияет на приём пищи?",
    "q.l40#5.o0" to "Одновременно снижает аппетит и ясность мышления, из-за чего дефицит энергии труднее закрыть",
    "q.l40#5.o1" to "Никак не влияет",
    "q.l40#5.o2" to "Повышает аппетит",
    "q.l40#5.o3" to "Влияет только на жажду",
    "q.l40#5.e" to "Из-за нехватки воды не хочется есть, и оценка «сколько ещё не хватает» становится неточной. Питьё и энергию планируют вместе.",
    "q.l40#6.p" to "Как правильно относиться к аминокислотам с разветвлённой цепью (BCAA)?",
    "q.l40#6.o0" to "Есть данные о связи с обменом аммиака, но доказательств мало, и это не заменяет общую калорийность",
    "q.l40#6.o1" to "Может полностью заменить еду",
    "q.l40#6.o2" to "Чем больше, тем лучше",
    "q.l40#6.o3" to "Совершенно бесполезны",
    "q.l40#6.e" to "Место добавок — маргинальная оптимизация. Если общих калорий не хватает, никакая добавка этого не восполнит.",
    "q.l40#7.p" to "Почему на высоте суточная потребность в энергии, наоборот, выше?",
    "q.l40#7.o0" to "Холод, груз и гипоксия повышают расход в покое и работу дыхания",
    "q.l40#7.o1" to "Потому что на высоте больше сила тяжести",
    "q.l40#7.o2" to "Потому что плохо спится",
    "q.l40#7.o3" to "Потому что человек нервничает",
    "q.l40#7.e" to "Потребность растёт, а аппетит падает — отсюда и берётся дефицит энергии на высоте. Стратегию строят именно вокруг этого противоречия.",
    "q.l40#8.p" to "Какая схема питания на день выхода на вершину разумна?",
    "q.l40#8.o0" to "Перед выходом съесть горячее с преобладанием углеводов, а в движении есть каждые 45–60 минут",
    "q.l40#8.o1" to "Не есть перед выходом, чтобы было легче",
    "q.l40#8.o2" to "Поесть только после вершины",
    "q.l40#8.o3" to "Держаться на кофеине весь день",
    "q.l40#8.e" to "Выход натощак означает, что гликоген кончится уже через два часа. Малые частые порции — единственный способ продержаться больше десяти часов.",
    "q.l40#9.p" to "В чём значение горячей еды на высоте?",
    "q.l40#9.o0" to "Даёт тепло, воду и психологическую опору, и её легче принять",
    "q.l40#9.o1" to "Это просто ритуал",
    "q.l40#9.o2" to "Восполняет белок",
    "q.l40#9.o3" to "Помогает переваривать клетчатку",
    "q.l40#9.e" to "Горячая еда решает три задачи сразу: энергия, вода, настрой. Именно поэтому лагерную кухню нельзя заменить одними сухими пайками.",
    "q.l40#10.p" to "Если участник не может есть два дня подряд, что должно насторожить в первую очередь?",
    "q.l40#10.o0" to "Истощение энергии ведёт к переохлаждению и снижению оценки, а также может быть признаком усиления высотной болезни",
    "q.l40#10.o1" to "Он похудеет",
    "q.l40#10.o2" to "Будет запор",
    "q.l40#10.o3" to "Будет нехватка витаминов",
    "q.l40#10.e" to "«Не могу есть» на высоте — одновременно причина и симптом. Если это не проходит, нужно оценивать состояние как высотную болезнь, а не просто уговаривать поесть.",
    "q.l40#11.p" to "Каким критериям должны отвечать перекусы на высоте?",
    "q.l40#11.o0" to "Высокая калорийность",
    "q.l40#11.o1" to "Не твердеть на холоде и легко жеваться",
    "q.l40#11.o2" to "Не требовать большого количества воды, чтобы проглотить",
    "q.l40#11.o3" to "Чем больше объём, тем лучше",
    "q.l40#11.e" to "На холоде шоколад и батончики каменеют, а при -20 ℃ твёрдую еду почти невозможно есть. Большой объём — это и место в рюкзаке, и то, что не съедается.",
    "q.l40#12.p" to "Что верно в отношении питья и приёма энергии?",
    "q.l40#12.o0" to "Перед выходом выпить достаточно",
    "q.l40#12.o1" to "В движении пить малыми порциями и часто",
    "q.l40#12.o2" to "Сочетать солевые растворы с приёмом энергии",
    "q.l40#12.o3" to "Догнать всё разом в лагере",
    "q.l40#12.e" to "Одномоментное большое количество воды нагружает желудок и всё равно не закрывает дефицит за день. Работает только распределённый приём.",
    "q.l40#13.p" to "Что реально повышает количество съеденного в горах?",
    "q.l40#13.o0" to "Брать вкусы, которые человек любит и ест дома",
    "q.l40#13.o1" to "Разложить еду на мелкие порции в доступных местах",
    "q.l40#13.o2" to "Иметь несколько разных текстур для чередования",
    "q.l40#13.o3" to "Взять только один самый калорийный продукт",
    "q.l40#13.e" to "Пищевое отвращение на высоте встречается часто: один и тот же вкус через несколько дней просто не идёт. Разнообразие и знакомые вкусы — практичная стратегия.",
    "q.l40#14.p" to "Расставьте разумный порядок питания в течение дня.",
    "q.l40#14.o0" to "После подъёма сначала попить, завтрак с преобладанием углеводов",
    "q.l40#14.o1" to "После выхода есть небольшими порциями каждые 45–60 минут",
    "q.l40#14.o2" to "Перед длительным подъёмом поесть дополнительно",
    "q.l40#14.o3" to "В лагере восполнить горячей едой и водой",
    "q.l40#14.e" to "Главное в этом ритме — не ждать голода. Голод означает, что гликоген уже на нуле, и приём пищи начнёт действовать только через 20–30 минут.",
    "q.l40#15.p" to "Каков правильный порядок действий при «не могу есть»?",
    "q.l40#15.o0" to "Сначала попить и проверить, нет ли обезвоживания",
    "q.l40#15.o1" to "Перейти на легко идущую калорийную еду и есть малыми порциями",
    "q.l40#15.o2" to "Оценить, нет ли признаков высотной болезни",
    "q.l40#15.o3" to "Если улучшения нет, рассматривать спуск",
    "q.l40#15.e" to "Обезвоживание — первый обратимый шаг. Если после его исключения аппетита всё равно нет, оценивают болезнь, а не продолжают уговаривать поесть.",
    "q.l40#16.p" to "Энергетическая плотность жира — около ______ ккал/г.",
    "q.l40#16.a0" to "9",
    "q.l40#16.e" to "У углеводов и белков около 4 ккал/г. Именно эта разница объясняет любовь к орехам, масляным смесям и шоколаду на высоте.",
    "q.l40#17.p" to "В движении рекомендуется принимать пищу каждые ______ минут (впишите число).",
    "q.l40#17.a0" to "45–60",
    "q.l40#17.a1" to "45-60",
    "q.l40#17.a2" to "45",
    "q.l40#17.a3" to "60",
    "q.l40#17.a4" to "50",
    "q.l40#17.e" to "Малые частые порции действуют лучше, чем большие редкие, и реже вызывают проблемы с желудком.",
    "q.l40#18.p" to "Соотнесите источник энергии с его ролью.",
    "q.l40#18.l0" to "Углеводы",
    "q.l40#18.l1" to "Жиры",
    "q.l40#18.l2" to "Белки",
    "q.l40#18.l3" to "Вода и электролиты",
    "q.l40#18.r0" to "Самое быстрое поступление, приоритет на высоте",
    "q.l40#18.r1" to "Наибольшая энергетическая плотность, длительное обеспечение",
    "q.l40#18.r2" to "Восстановление и поддержание, не основной источник энергии",
    "q.l40#18.r3" to "Поддержание кровообращения и терморегуляции",
    "q.l40#18.e" to "Пропорции можно менять, но базовую роль углеводов заменить нечем.",
    "q.l40#19.p" to "Соотнесите ситуацию с подходящим выбором питания.",
    "q.l40#19.l0" to "Длительный подъём",
    "q.l40#19.l1" to "Ожидание на сильном холоде",
    "q.l40#19.l2" to "За 2 часа до выхода на вершину",
    "q.l40#19.l3" to "Возвращение в лагерь",
    "q.l40#19.r0" to "Гели, конфеты и другие углеводы, которые едят на ходу",
    "q.l40#19.r1" to "Жирная и калорийная еда, которая не каменеет на морозе",
    "q.l40#19.r2" to "Горячий приём пищи с преобладанием углеводов",
    "q.l40#19.r3" to "Горячая еда, вода и электролиты",
    "q.l40#19.e" to "Один и тот же набор продуктов работает по-разному в разных ситуациях. Подбирать под сценарий эффективнее, чем «купить побольше батончиков».",
    "q.l40#20.p" to "Участник взял только протеиновый порошок, чтобы сэкономить вес. Как это оценить?",
    "q.l40#20.o0" to "Не годится: белок не основной источник энергии, на высоте нужны достаточные углеводы",
    "q.l40#20.o1" to "Можно, белок чище",
    "q.l40#20.o2" to "Можно, белок легче",
    "q.l40#20.o3" to "Зависит от вкуса",
    "q.l40#20.e" to "Белок как источник энергии — неэффективный путь, к тому же он повышает нагрузку на почки и риск обезвоживания. Основа питания на высоте — углеводы и жиры.",
    "q.l40#21.p" to "Еда замёрзла и затвердела. Что практичнее всего сделать?",
    "q.l40#21.o0" to "Держать ту часть, которую собираетесь есть, у тела и согревать её теплом",
    "q.l40#21.o1" to "Залить горячей водой",
    "q.l40#21.o2" to "Грызть зубами",
    "q.l40#21.o3" to "Бросить и не есть",
    "q.l40#21.e" to "Хранить у тела — самое простое и действенное. Батончик в рюкзаке при -20 ℃ становится твёрдым как камень.",
    "q.l40#22.p" to "Почему «умение есть» само по себе является высотным навыком?",
    "q.l40#22.o0" to "Способность поддерживать приём пищи при гипоксии и упавшем аппетите напрямую определяет силы и ясность мышления",
    "q.l40#22.o1" to "Потому что хороший аппетит — это удача",
    "q.l40#22.o2" to "Потому что еда дорогая",
    "q.l40#22.o3" to "Потому что нужно фотографировать",
    "q.l40#22.e" to "Дефицит энергии проявляется не сразу как голод, а как замедленность, зябкость и ухудшение оценки. Способность стабильно есть — результат тренировки.",
    "q.l40#23.p" to "Что верно про кофеин на высоте?",
    "q.l40#23.o0" to "В умеренных количествах допустим, но не заменяет отдых и питьё",
    "q.l40#23.o1" to "Чем больше, тем лучше",
    "q.l40#23.o2" to "Полностью запрещён",
    "q.l40#23.o3" to "Только чтобы гнать темп",
    "q.l40#23.e" to "Кофеин немного помогает при головной боли, но маскировать им усталость — значит отложить проблему на более опасный момент.",
    "q.l41#0.p" to "В чём суть логистики экспедиции?",
    "q.l41#0.o0" to "Многоступенчатая перевозка, на каждой ступени свои ограничения по весу, срокам и рискам",
    "q.l41#0.o1" to "Одна отправка груза к подножию",
    "q.l41#0.o2" to "Покупка самого дорогого снаряжения",
    "q.l41#0.o3" to "Поиск лучшего гида",
    "q.l41#0.e" to "Только рассматривая логистику как цепь, а не как точку, можно делать верный выбор на каждой ступени. Стоит одному звену порваться — страдает всё дальше.",
    "q.l41#1.p" to "Какова правильная логика упаковки грузов?",
    "q.l41#1.o0" to "Паковать по порядку прибытия: что приходит раньше, то и достаётся первым",
    "q.l41#1.o1" to "Паковать по категориям",
    "q.l41#1.o2" to "Паковать по цене",
    "q.l41#1.o3" to "Смешать всё вместе",
    "q.l41#1.e" to "В высотном лагере мало места и плохая погода, и поиск в ящиках стоит очень дорого. Упаковка по порядку прибытия экономит много времени под открытым небом.",
    "q.l41#2.p" to "К чему обычно привязан пермит на восхождение?",
    "q.l41#2.o0" to "К офицеру связи, маршруту и сроку действия",
    "q.l41#2.o1" to "Только к оплате",
    "q.l41#2.o2" to "Только к числу участников",
    "q.l41#2.o3" to "Только к сезону",
    "q.l41#2.e" to "Все три пункта привязаны к пермиту. Смена маршрута, просрочка или замена людей могут потребовать повторной регистрации и дополнительных расходов.",
    "q.l41#3.p" to "Каково обычное правило залога за мусор?",
    "q.l41#3.o0" to "Залог возвращают только после выноса всего мусора",
    "q.l41#3.o1" to "Вносят и не возвращают",
    "q.l41#3.o2" to "Штраф по весу",
    "q.l41#3.o3" to "Взнос добровольный",
    "q.l41#3.e" to "Цель правила не собрать деньги, а сделать вынос мусора экономическим ограничением. В плане для этого нужно предусмотреть людей.",
    "q.l41#4.p" to "Почему нельзя произвольно увеличивать груз носильщиков и помощников?",
    "q.l41#4.o0" to "Есть законодательный или отраслевой предел: перегруз переносит риск на них и замедляет всю группу",
    "q.l41#4.o1" to "Потому что они будут жаловаться",
    "q.l41#4.o2" to "Потому что снаряжение испортится",
    "q.l41#4.o3" to "Потому что страховка не покрывает",
    "q.l41#4.e" to "Перегруз — это когда свою эффективность строят на чужом вреде, и он же замедляет всю транспортную цепь. Это вопрос и этики, и управления.",
    "q.l41#5.p" to "Что означает темп расхода в плане снабжения?",
    "q.l41#5.o0" to "Люди × дни × норма на день, по этому считают общий объём и точки пополнения",
    "q.l41#5.o1" to "Сколько километров в день",
    "q.l41#5.o2" to "Сколько метров набора в день",
    "q.l41#5.o3" to "Сколько несёт каждый",
    "q.l41#5.e" to "Топливо, газ и продукты считают по темпу расхода. При оценке на глаз обычно выясняется, что газа не хватает именно в самые холодные дни.",
    "q.l41#6.p" to "Срок пермита заканчивается, а погодное окно ещё не наступило. Что разумнее?",
    "q.l41#6.o0" to "Заранее оценить стоимость продления и требования соответствия и при необходимости продлить или перенести сроки",
    "q.l41#6.o1" to "Продолжать восхождение с просроченным пермитом",
    "q.l41#6.o2" to "Сменить маршрут без регистрации",
    "q.l41#6.o3" to "Попросить офицера связи закрыть глаза",
    "q.l41#6.e" to "Восхождение с просроченным пермитом обнуляет и разрешение, и страховку, и возможность спасения. Продление дорого, но дешевле, чем «после аварии спасать нечем».",
    "q.l41#7.p" to "Зачем в снабжении нужен резерв?",
    "q.l41#7.o0" to "Задержки погоды, износ снаряжения и состояние группы увеличивают расход",
    "q.l41#7.o1" to "Чтобы продать излишки",
    "q.l41#7.o2" to "Чтобы уменьшить вес",
    "q.l41#7.o3" to "Для соответствия требованиям",
    "q.l41#7.e" to "Расход в экспедиции никогда не бывает линейным. Резерв — это запас на «незапланированно задержались на несколько дней».",
    "q.l41#8.p" to "В чём суть управления грузами в высотных лагерях?",
    "q.l41#8.o0" to "Понятная таблица выдачи и ротация, чтобы не было «в одном лагере склад, в другом пусто»",
    "q.l41#8.o1" to "Чем больше, тем лучше",
    "q.l41#8.o2" to "Кто пришёл первым, тот и берёт",
    "q.l41#8.o3" to "Делить всё поровну",
    "q.l41#8.e" to "Таблица выдачи даёт каждому лагерю понимание, что у него есть и когда будет пополнение. Без таблицы грузы скапливаются не там, где нужно.",
    "q.l41#9.p" to "Что обычно требуется для подтверждения восхождения?",
    "q.l41#9.o0" to "Фото или видео с вершины, декларация, пермит и документ, удостоверяющий личность",
    "q.l41#9.o1" to "Только фотография",
    "q.l41#9.o2" to "Только подтверждение партнёров",
    "q.l41#9.o3" to "Ничего не требуется",
    "q.l41#9.e" to "Требования на разных вершинах разные, но «фото плюс декларация плюс пермит» работает почти везде. Оформлять это после возвращения всегда труднее, чем подготовить заранее.",
    "q.l41#10.p" to "Если багаж не прилетел тем же рейсом, что спасать в первую очередь?",
    "q.l41#10.o0" to "Ботинки и личное техническое снаряжение: их почти невозможно заменить на месте",
    "q.l41#10.o1" to "Сменную одежду",
    "q.l41#10.o2" to "Снеки",
    "q.l41#10.o3" to "Сувениры",
    "q.l41#10.e" to "В неподходящих ботинках идти невозможно, а техническое снаряжение связано с безопасностью. Большинство групп требует брать эти две категории в ручную кладь.",
    "q.l41#11.p" to "Что нужно подтверждать по каждой ступени плана логистики?",
    "q.l41#11.o0" to "Способ перевозки и запасной вариант",
    "q.l41#11.o1" to "Вес и стоимость вьючного транспорта или носильщиков",
    "q.l41#11.o2" to "Время и контрольные точки каждой ступени",
    "q.l41#11.o3" to "Аккаунты участников в соцсетях",
    "q.l41#11.e" to "Первые три пункта определяют, можно ли двигаться по плану. Четвёртый к логистике отношения не имеет.",
    "q.l41#12.p" to "Что обычно входит в затраты на пермит и соответствие требованиям?",
    "q.l41#12.o0" to "Стоимость пермита и оплата офицера связи",
    "q.l41#12.o1" to "Залог за мусор",
    "q.l41#12.o2" to "Плата за продление",
    "q.l41#12.o3" to "Амортизация снаряжения",
    "q.l41#12.e" to "Первые три — это затраты на соответствие, их нужно выделять в бюджете отдельной строкой. Амортизация снаряжения — личная статья.",
    "q.l41#13.p" to "Каких ситуаций в управлении лагерными грузами нужно избегать?",
    "q.l41#13.o0" to "В одном лагере избыток, в другом закончилась еда",
    "q.l41#13.o1" to "Совместное хранение топлива и продуктов, ведущее к загрязнению",
    "q.l41#13.o2" to "Отсутствие таблицы выдачи и опора на память",
    "q.l41#13.o3" to "Ротация по плану",
    "q.l41#13.e" to "Первые три — признаки отсутствия управления. Последний пункт как раз правильное действие.",
    "q.l41#14.p" to "Расставьте порядок планирования логистики экспедиции.",
    "q.l41#14.o0" to "Подтвердить маршрут, пермит и сроки",
    "q.l41#14.o1" to "Определить способ перевозки и сроки на каждой ступени",
    "q.l41#14.o2" to "Разложить грузы по порядку прибытия и составить таблицу выдачи",
    "q.l41#14.o3" to "Заложить резерв и бюджет на продление",
    "q.l41#14.e" to "Порядок отражает принцип: сначала соответствие требованиям, затем логистика, потом детали. Если заказывать перевозку до оформления пермита, стоимость переноса удваивается.",
    "q.l41#15.p" to "Расставьте порядок поступления грузов в высотный лагерь.",
    "q.l41#15.o0" to "Перевозка автотранспортом до базового лагеря",
    "q.l41#15.o1" to "Вьючный транспорт или переноска людьми до промежуточного лагеря",
    "q.l41#15.o2" to "Распределение по таблице выдачи в высотные лагеря",
    "q.l41#15.o3" to "Пересчёт ключевых грузов перед выходом на вершину: газ, продукты, батареи",
    "q.l41#15.e" to "Последний шаг пропускают чаще всего. Без пересчёта перед выходом типичный итог — «пришли в верхний лагерь, а газа не хватает».",
    "q.l41#16.p" to "Общий объём снабжения обычно считают как люди × дни × ______.",
    "q.l41#16.a0" to "норма на день",
    "q.l41#16.a1" to "дневная норма",
    "q.l41#16.a2" to "норма",
    "q.l41#16.e" to "Только записав темп расхода в план, можно посчитать точки пополнения и объём резерва.",
    "q.l41#17.p" to "Многие вершины требуют вынести весь мусор, иначе не возвращают ______.",
    "q.l41#17.a0" to "залог",
    "q.l41#17.a1" to "залог за мусор",
    "q.l41#17.e" to "Если считать залог статьёй расходов, не окажется в последний день, что некому нести мусор.",
    "q.l41#18.p" to "Соотнесите этап логистики с его главным риском.",
    "q.l41#18.l0" to "Перевозка автотранспортом",
    "q.l41#18.l1" to "Вьючный транспорт и носильщики",
    "q.l41#18.l2" to "Выдача в высотных лагерях",
    "q.l41#18.l3" to "Срок пермита",
    "q.l41#18.r0" to "Обрыв дороги, оползень, задержка машины",
    "q.l41#18.r1" to "Превышение веса, состояние людей, погода",
    "q.l41#18.r2" to "Пересортица грузов, нехватка еды и газа",
    "q.l41#18.r3" to "Просрочка обнуляет разрешение и возможность спасения",
    "q.l41#18.e" to "Типы риска на четырёх этапах совершенно разные, поэтому и планы на случай сбоя пишут отдельно.",
    "q.l41#19.p" to "Соотнесите документ с его назначением.",
    "q.l41#19.l0" to "Пермит и документы офицера связи",
    "q.l41#19.l1" to "Квитанция о залоге за мусор",
    "q.l41#19.l2" to "Фото с вершины и декларация",
    "q.l41#19.l3" to "Страховка и телефон спасения",
    "q.l41#19.r0" to "Допуск и проверка соответствия",
    "q.l41#19.r1" to "Основание для возврата залога при уходе с горы",
    "q.l41#19.r2" to "Заявка на подтверждение восхождения",
    "q.l41#19.r3" to "Связь и урегулирование при страховом случае",
    "q.l41#19.e" to "Четыре документа служат четырём моментам: вход на маршрут, уход, подтверждение, авария. Не хватит одного — застрянешь именно в этот момент.",
    "q.l41#20.p" to "Группа хочет провесить дополнительный участок перил вне разрешённой зоны. Что сделать в первую очередь?",
    "q.l41#20.o0" to "Проверить, не нарушает ли это пермит и правила охраняемой территории, и при необходимости зарегистрировать изменение",
    "q.l41#20.o1" to "Сначала провесить, потом разбираться",
    "q.l41#20.o2" to "Провесить ночью, чтобы никто не видел",
    "q.l41#20.o3" to "Поручить это кому-то другому",
    "q.l41#20.e" to "На охраняемых территориях перила часто считаются постоянным сооружением, и без разрешения это нарушение. Сначала выясняют, потом делают.",
    "q.l41#21.p" to "Команда помощников заявляет, что объём работы превышает договор. Как поступить разумнее?",
    "q.l41#21.o0" to "Пересмотреть условия по договору и фактическому объёму, зафиксировав изменения",
    "q.l41#21.o1" to "Отказаться от общения",
    "q.l41#21.o2" to "Потребовать выполнить любым способом",
    "q.l41#21.o3" to "Тихо доплатить и не записывать",
    "q.l41#21.e" to "В экспедиции изменения по людям обычны. Пересмотр с фиксацией защищает и их, и вас.",
    "q.l41#22.p" to "Почему в экспедиции нужен отдельный бюджет на продление?",
    "q.l41#22.o0" to "Погодные окна и задержки логистики обычны, а продление означает дополнительные расходы на жильё, людей и пермит",
    "q.l41#22.o1" to "Чтобы было на покупки",
    "q.l41#22.o2" to "На чаевые",
    "q.l41#22.o3" to "Из-за курса валют",
    "q.l41#22.e" to "Бюджет на продление — не расточительство, а способ не принимать опасных решений из-за нехватки денег.",
    "q.l41#23.p" to "Как правильно обращаться с мусором при уходе с горы?",
    "q.l41#23.o0" to "Вынести всё, рассортировав по требованиям пермита, и сохранить квитанции",
    "q.l41#23.o1" to "Закопать в снег",
    "q.l41#23.o2" to "Сжечь",
    "q.l41#23.o3" to "Передать следующей группе",
    "q.l41#23.e" to "Закапывание и сжигание нарушают правила и загрязняют воду. Вынести и сохранить квитанцию — единственный способ вернуть залог.",
    "q.l41#24.p" to "Что в первую очередь должна покрывать страховка грузов экспедиции?",
    "q.l41#24.o0" to "Расходы от срыва программы из-за утраты или задержки снаряжения",
    "q.l41#24.o1" to "Только стоимость перевозки",
    "q.l41#24.o2" to "Только жизнь и здоровье",
    "q.l41#24.o3" to "Ничего не нужно",
    "q.l41#24.e" to "Задержка снаряжения может сразу закончить всю программу. Страховка должна покрывать задержку и срыв, а не только утрату.",
    "q.l41#25.p" to "Как эффективнее всего оговаривать объём работы с командой помощников?",
    "q.l41#25.o0" to "До выхода письменно подтвердить вес, число ходок и оплату, а изменения фиксировать по ходу",
    "q.l41#25.o1" to "Договориться на словах",
    "q.l41#25.o2" to "Решить уже на месте",
    "q.l41#25.o3" to "Пусть решают они сами",
    "q.l41#25.e" to "Изменения в экспедиции — норма. Письменное подтверждение и фиксация изменений избавляют от спора о деньгах в последний день.",
    "q.l41#26.p" to "Что должна содержать ведомость запасов базового лагеря?",
    "q.l41#26.o0" to "Наименование, количество, лагерь, дата вскрытия и ответственный",
    "q.l41#26.o1" to "Только общее количество",
    "q.l41#26.o2" to "Только категории",
    "q.l41#26.o3" to "Ничего",
    "q.l41#26.e" to "«Где, сколько осталось, кто использует» — три обязательных элемента ведомости. Без неё грузы обязательно скапливаются не там.",
    "q.l41#27.p" to "Если пермит требует вынести весь мусор, что нужно дополнительно предусмотреть в плане?",
    "q.l41#27.o0" to "Людей и транспортные возможности на обратный путь, а также взвешивание и квитанции",
    "q.l41#27.o1" to "Только мешки для мусора",
    "q.l41#27.o2" to "Только бюджет на штраф",
    "q.l41#27.o3" to "Ничего дополнительно",
    "q.l41#27.e" to "На обратном пути группа слабее всего и время самое сжатое, а мусор самый тяжёлый. Если вписать это в транспортный план, последний день не выйдет из-под контроля.",
    "q.m18#16.p" to "Каковы высота и положение Музтаг-Ата?",
    "q.m18#16.o0" to "7 509 м, уезд Акто в Синьцзяне, восточная окраина Памира",
    "q.m18#16.o1" to "6 812 м, Непал",
    "q.m18#16.o2" to "7 134 м, Киргизия",
    "q.m18#16.o3" to "8 163 м, Непал",
    "q.m18#16.e" to "«Отец ледников» — один из первых вариантов для 7000-метрового уровня в Китае: снежные склоны длинные, требования к акклиматизации и выносливости высокие.",
    "q.m18#17.p" to "В чём основная сложность Музтаг-Ата?",
    "q.m18#17.o0" to "Акклиматизация на высоте и выносливость на длинных снежных склонах, а не техническая сложность",
    "q.m18#17.o1" to "Вертикальные скальные стены",
    "q.m18#17.o2" to "Частые трещины",
    "q.m18#17.o3" to "Техническое ледолазание",
    "q.m18#17.e" to "Технически гора относительно мягкая, но «долго, высоко, холодно» многократно усиливает недостаток формы и акклиматизации.",
    "q.m18#18.p" to "В какой стране или регионе находится пик Ленина?",
    "q.m18#18.o0" to "На границе Киргизии и Таджикистана",
    "q.m18#18.o1" to "Непал",
    "q.m18#18.o2" to "Синьцзян, Китай",
    "q.m18#18.o3" to "Пакистан",
    "q.m18#18.e" to "Пик Ленина на Памире часто выбирают как первую 7000-метровую вершину, но высота и ледниковый рельеф всё равно остаются.",
    "q.m18#19.p" to "Какова высота Ама-Даблам?",
    "q.m18#19.o0" to "6 812 м",
    "q.m18#19.o1" to "7 509 м",
    "q.m18#19.o2" to "7 126 м",
    "q.m18#19.o3" to "6 189 м",
    "q.m18#19.e" to "Высота меньше 7000, но крутой смешанный скально-снежный рельеф и сильное чувство открытости ставят её техническую сложность на уровень выше 7000.",
    "q.m18#20.p" to "Чем Ама-Даблам часто служит «пробным камнем»?",
    "q.m18#20.o0" to "Технической и психологической подготовки к 8000-метровому уровню",
    "q.m18#20.o1" to "Первой снежной вершиной",
    "q.m18#20.o2" to "Лыжным маршрутом",
    "q.m18#20.o3" to "Треккинговым маршрутом",
    "q.m18#20.e" to "Сочетание открытости и техники проверяет главное: способность выполнять правильные действия под давлением.",
    "q.m18#21.p" to "Каково обычно сезонное окно на 7000-метровом уровне?",
    "q.m18#21.o0" to "Уже, чем на 5000–6000 м: окно определяют ветер в верхних слоях и снегопады",
    "q.m18#21.o1" to "Круглый год",
    "q.m18#21.o2" to "Только зимой",
    "q.m18#21.o3" to "Такое же, как на меньших высотах",
    "q.m18#21.e" to "Чем выше, тем сильнее окно зависит от ветра и муссона. Узкое окно означает, что и «ждать», и «разворачиваться» нужно решительнее.",
    "q.m18#22.p" to "Что важнее всего подтвердить перед выбором 7000-метровой цели?",
    "q.m18#22.o0" to "Что на 6000-метровом уровне уже неоднократно и уверенно пройдены длинные снежные склоны и налажено самообслуживание",
    "q.m18#22.o1" to "Сложность по скалолазанию",
    "q.m18#22.o2" to "Результат в беге",
    "q.m18#22.o3" to "Количество снаряжения",
    "q.m18#22.e" to "Порог 7000 м — это выносливость и самостоятельность, а не отдельный технический приём. Сначала посмотрите на свою историю на 6000.",
    "q.m18#23.p" to "Что обычно требуется для пермита и логистики на этих вершинах?",
    "q.m18#23.o0" to "Оформить пермит за несколько недель и организовать гида, вьючный транспорт и лагерное снабжение",
    "q.m18#23.o1" to "Оформить на месте",
    "q.m18#23.o2" to "Пермит не нужен",
    "q.m18#23.o3" to "Достаточно купить билет",
    "q.m18#23.e" to "Чем глуше маршрут, тем длиннее цепь снабжения. Считать пермит и логистику частью технической подготовки гораздо дешевле, чем исправлять потом.",
    "q.m19#19.p" to "Что обычно называют зоной смерти по высоте?",
    "q.m19#19.o0" to "От 8 000 м",
    "q.m19#19.o1" to "От 6 000 м",
    "q.m19#19.o2" to "От 7 000 м",
    "q.m19#19.o3" to "От 5 000 м",
    "q.m19#19.e" to "Выше 8 000 м давление примерно треть от уровня моря, и организм не может долго удерживать равновесие — он только расходует ресурс.",
    "q.m19#20.p" to "Почему на 8 000 м отдых уже не даёт настоящего восстановления?",
    "q.m19#20.o0" to "Поступление кислорода не покрывает восстановление, организм в чистом расходе",
    "q.m19#20.o1" to "Потому что слишком холодно",
    "q.m19#20.o2" to "Потому что плохо спится",
    "q.m19#20.o3" to "Из-за обезвоживания",
    "q.m19#20.e" to "Это физиологическая основа правила «чем короче пребывание, тем лучше». Вся тактика строится вокруг сокращения времени под воздействием.",
    "q.m19#21.p" to "Какое проявление снижения когнитивных способностей на высоте опаснее всего?",
    "q.m19#21.o0" to "Человек сам не замечает, что оценка ухудшилась",
    "q.m19#21.o1" to "Плохая память",
    "q.m19#21.o2" to "Медленная реакция",
    "q.m19#21.o3" to "Трудности с концентрацией",
    "q.m19#21.e" to "Гипоксия первым делом ослабляет способность оценивать себя. Именно поэтому решения выносят наружу: пишут чек-листы и просят партнёров перепроверить.",
    "q.m20#20.p" to "Почему доступная ёмкость кислородного баллона отличается от номинальной?",
    "q.m20#20.o0" to "Остаточное давление не даёт использовать последнюю часть, а на холоде давление падает",
    "q.m20#20.o1" to "Из-за утечки",
    "q.m20#20.o2" to "Из-за ошибки в маркировке",
    "q.m20#20.o3" to "Из-за износа маски",
    "q.m20#20.e" to "Считать нужно по доступному объёму. Если принять номинал за доступный, в день выхода на вершину кислород типично заканчивается раньше срока.",
    "q.m20#21.p" to "Какую цену приходится платить за повышение потока кислорода?",
    "q.m20#21.o0" to "Время работы сокращается пропорционально, нужно больше запасных баллонов",
    "q.m20#21.o1" to "Цены нет",
    "q.m20#21.o2" to "Испортится маска",
    "q.m20#21.o3" to "Баллон замёрзнет",
    "q.m20#21.e" to "Поток и автономность связаны обратной зависимостью. Поднимая поток, обязательно пересчитывают общую потребность и запас.",
    "q.m21#18.p" to "Какова последняя официальная высота Эвереста?",
    "q.m21#18.o0" to "8 848,86 м по совместному измерению Китая и Непала 2020 года",
    "q.m21#18.o1" to "8 848 м",
    "q.m21#18.o2" to "8 850 м",
    "q.m21#18.o3" to "8 846 м",
    "q.m21#18.e" to "8 848,86 м — совместно опубликованное значение 2020 года. Классическое 8 848 м из старых учебников тоже встречается часто.",
    "q.m21#19.p" to "Как Лходзе расположен относительно Эвереста?",
    "q.m21#19.o0" to "Вплотную к Эвересту с юга, часто восходят по одной линии с ним",
    "q.m21#19.o1" to "К северу от Эвереста",
    "q.m21#19.o2" to "На западе Непала",
    "q.m21#19.o3" to "В Каракоруме",
    "q.m21#19.e" to "Обе вершины делят часть маршрута через Южное седло, поэтому «Эверест плюс Лходзе» часто планируют одной экспедицией.",
    "q.m21#20.p" to "Где находится Канченджанга?",
    "q.m21#20.o0" to "На границе Непала и Индии",
    "q.m21#20.o1" to "На границе Китая и Непала",
    "q.m21#20.o2" to "В Пакистане",
    "q.m21#20.o3" to "В Бутане",
    "q.m21#20.e" to "Третья вершина мира стоит на границе Непала и Индии (Сикким), и пермит с логистикой там относительно сложны.",
    "q.m21#21.p" to "Какова особенность Аннапурны I?",
    "q.m21#21.o0" to "Относительно высокая смертность, крутой маршрут и выраженный риск лавин и камнепадов",
    "q.m21#21.o1" to "Самая простая",
    "q.m21#21.o2" to "Самая высокая",
    "q.m21#21.o3" to "Доступна круглый год",
    "q.m21#21.e" to "Это одна из самых опасных вершин 8000-метрового уровня. Цифры напоминают: порядок по высоте не равен порядку по сложности.",
    "q.m22#17.p" to "Какова официальная высота K2 и его прозвище?",
    "q.m22#17.o0" to "8 611 м, «Дикая гора»",
    "q.m22#17.o1" to "8 586 м, «Снежный барс»",
    "q.m22#17.o2" to "8 126 м, «Голая гора»",
    "q.m22#17.o3" to "8 080 м, «Скрытая вершина»",
    "q.m22#17.e" to "K2 — вторая по высоте вершина мира, и по технической сложности и смертности она давно держится в числе первых на 8000-метровом уровне.",
    "q.m22#18.p" to "Каково прозвище Нангапарбата и его главный риск?",
    "q.m22#18.o0" to "«Голая гора»: огромный перепад высот даёт риск лавин и камнепадов",
    "q.m22#18.o1" to "«Отец ледников»",
    "q.m22#18.o2" to "«Скрытая вершина»",
    "q.m22#18.o3" to "«Гора-людоед»",
    "q.m22#18.e" to "Её южная стена — один из крупнейших скальных перепадов в мире. Маршруты открыты, погода переменчива, отход сложен.",
    "q.m22#19.p" to "Каковы высоты Гашербрума I и II?",
    "q.m22#19.o0" to "8 080 м и 8 035 м",
    "q.m22#19.o1" to "8 051 м и 8 080 м",
    "q.m22#19.o2" to "8 611 м и 8 586 м",
    "q.m22#19.o3" to "8 188 м и 8 167 м",
    "q.m22#19.e" to "GI 8 080, GII 8 035. Эти две вершины часто сравнивают, но маршруты и сложность у них сильно различаются.",
    "q.m22#20.p" to "Какова высота Броуд-Пика?",
    "q.m22#20.o0" to "8 051 м",
    "q.m22#20.o1" to "8 035 м",
    "q.m22#20.o2" to "8 080 м",
    "q.m22#20.o3" to "8 126 м",
    "q.m22#20.e" to "Броуд-Пик 8 051 м часто считают технически более простым вариантом на 8000-метровом уровне, но длинные снежные склоны и высота никуда не исчезают.",
    "q.m22#21.p" to "Сколько восьмитысячников находится в Пакистане?",
    "q.m22#21.o0" to "Пять",
    "q.m22#21.o1" to "Три",
    "q.m22#21.o2" to "Четыре",
    "q.m22#21.o3" to "Две",
    "q.m22#21.e" to "K2, Нангапарбат, Гашербрум I и II, Броуд-Пик — всего пять.",
    "q.m23#18.p" to "Ситуация: у партнёра на 7 500 м атаксия, кислорода осталось на 2 часа. Что делать в первую очередь?",
    "q.m23#18.o0" to "Немедленно начать спуск и дать кислород, одновременно сообщить в базовый лагерь о готовности принять",
    "q.m23#18.o1" to "Сначала отдохнуть и понаблюдать",
    "q.m23#18.o2" to "Сначала дать лекарство",
    "q.m23#18.o3" to "Дойти до лагеря и там разбираться",
    "q.m23#18.e" to "Атаксия указывает на HACE. Спуск — единственная надёжно действующая мера, кислород нужен, чтобы выиграть время.",
    "q.m23#19.p" to "Ситуация: в день выхода на вершину обнаружено, что перила затёрты предыдущей группой до ворса. Как поступить?",
    "q.m23#19.o0" to "Не использовать этот участок: сменить линию или развернуться",
    "q.m23#19.o1" to "Продолжать, но осторожно",
    "q.m23#19.o2" to "Просто предупредить идущих сзади",
    "q.m23#19.o3" to "Записать и продолжить",
    "q.m23#19.e" to "Прочность затёртой верёвки оценить невозможно. Перила — это линия жизни для всех, и «осторожностью» это не компенсируется.",
    "q.m23#20.p" to "Ситуация: группа на 6 500 м попала в буран, видимость 5 метров. Какое решение разумнее?",
    "q.m23#20.o0" to "Организовать укрытие рядом или отходить по GPS вдоль заранее записанного трека",
    "q.m23#20.o1" to "Продолжать искать путь",
    "q.m23#20.o2" to "Разойтись и искать по одному",
    "q.m23#20.o3" to "Сесть на месте и ждать погоды",
    "q.m23#20.e" to "В белой мгле «поиск пути» почти гарантированно уводит в сторону. Остановиться и укрыться или вернуться по записанному треку — единственные рабочие варианты.",
    "q.m23#21.p" to "Ситуация: вся группа за продолжение, только вам кажется, что это неправильно, но объяснить вы не можете. Что делать?",
    "q.m23#21.o0" to "Явно сказать «у меня плохое предчувствие» и предложить группе вместе сверить ключевую информацию",
    "q.m23#21.o1" to "Подчиниться большинству",
    "q.m23#21.o2" to "Молча идти следом",
    "q.m23#21.o3" to "Одному повернуть назад",
    "q.m23#21.e" to "Интуиция часто означает «заметил, но ещё не оформил в слова». Скажите об этом вслух и сверьте факты вместе с группой.",
    "q.m24#18.p" to "Ситуация: в день выхода на вершину отставание 4 часа, ветер усилился, один участник двигается медленнее. Какое решение разумнее?",
    "q.m24#18.o0" to "Развернуться по заранее заданным условиям и записать, что именно их вызвало",
    "q.m24#18.o1" to "Дойти до вершины и там решить",
    "q.m24#18.o2" to "Отпустить медленного назад одного",
    "q.m24#18.o3" to "Ускориться, чтобы догнать график",
    "q.m24#18.e" to "Когда три сигнала совпали, аргументы «продолжаем» обычно идут от давления цели, а не от фактов. Условия разворота задают именно для такого момента.",
    "q.m24#19.p" to "Ситуация: у партнёра одышка в покое, но сатурация ещё 80 %. Что делать?",
    "q.m24#19.o0" to "Действовать как при HAPE: покой, кислород, готовить спуск",
    "q.m24#19.o1" to "Продолжать наблюдение",
    "q.m24#19.o2" to "Дать больше воды",
    "q.m24#19.o3" to "Дать обезболивающее",
    "q.m24#19.e" to "Симптом важнее цифры. Одышка в покое — ключевой признак HAPE, а спуск — самое надёжное действие.",
    "q.m24#20.p" to "Ситуация: на участке перил обнаружена сомнительная точка, а группа уже прошла больше половины. Что делать?",
    "q.m24#20.o0" to "Прекратить использование участка, поставить дубль или сменить линию, людей сначала вывести в безопасное место",
    "q.m24#20.o1" to "Быстро проскочить",
    "q.m24#20.o2" to "Только предупредить идущих сзади",
    "q.m24#20.o3" to "Продолжать пользоваться",
    "q.m24#20.e" to "«Уже больше половины» не является аргументом продолжать. Отказ точки даёт системные последствия, а не индивидуальные.",
    "q.m24#21.p" to "Ситуация: программа закончена. Что ценнее всего сохранить?",
    "q.m24#21.o0" to "Разбор, где выписаны хронология, основания решений и точки ошибок",
    "q.m24#21.o1" to "Фотографии",
    "q.m24#21.o2" to "Список снаряжения",
    "q.m24#21.o3" to "Счета",
    "q.m24#21.e" to "Разбор превращает пережитое в опыт. Записав, на каком узле можно было решить раньше, вы повышаете шанс решить раньше в следующий раз.",
    "q.t01#0.p" to "Какая информация лучше всего позволяет оценить сложность пешего маршрута?",
    "q.t01#0.o0" to "Километраж",
    "q.t01#0.o1" to "Расстояние, суммарный набор высоты, состояние поверхности, снабжение и точки выхода",
    "q.t01#0.o2" to "Максимальная высота",
    "q.t01#0.o3" to "Сколько шли другие",
    "q.t01#0.e" to "Километраж — лишь один из пунктов. На одних и тех же 10 км набор 80 м и 800 м дают разницу во времени в два-три раза, а грунт, щебень или мокрые скалы определяют риск подвернуть ногу.",
    "q.t01#1.p" to "Два маршрута по 10 км: у A набор 80 м, у B набор 800 м. В чём главное различие?",
    "q.t01#1.o0" to "В красоте видов",
    "q.t01#1.o1" to "Во времени и затрате сил: у B примерно в два-три раза больше",
    "q.t01#1.o2" to "В высоте над уровнем моря",
    "q.t01#1.o3" to "Различий почти нет",
    "q.t01#1.e" to "Набор высоты — самая недооценённая переменная. По опыту каждые 100 м подъёма примерно равны лишним 500 м по ровному, то есть 800 м набора — это как 4 км сверху.",
    "q.t01#2.p" to "Каким условиям должен отвечать маршрут для первого похода?",
    "q.t01#2.o0" to "Проходится за 3 часа",
    "q.t01#2.o1" to "Набор высоты в пределах 300 м",
    "q.t01#2.o2" to "По пути есть дорога или деревня, откуда можно сойти",
    "q.t01#2.o3" to "Мобильная связь есть на всём протяжении",
    "q.t01#2.e" to "Первые три пункта — управляемые границы риска. Связь относится к везению и не может быть частью плана: во многих долинах её просто нет.",
    "q.t01#3.p" to "Почему точку выхода нужно выяснять раньше, чем виды?",
    "q.t01#3.o0" to "Там обычно есть туалет",
    "q.t01#3.o1" to "При плохой погоде или нехватке сил можно сойти рядом, а не тащиться до конца",
    "q.t01#3.o2" to "Удобно фотографировать",
    "q.t01#3.o3" to "Этого требует страховка",
    "q.t01#3.e" to "Точка выхода превращает «обязан дойти» в «могу остановиться». В плане для каждого участка должно быть известно, где ближайший выход и сколько до него идти.",
    "q.t01#4.p" to "После дождя тот же маршрут заметно сложнее. Основная причина?",
    "q.t01#4.o0" to "Стало холоднее",
    "q.t01#4.o1" to "Поверхность мокрая и грязная, возможны броды: растёт и время, и риск подвернуть ногу",
    "q.t01#4.o2" to "Виды стали хуже",
    "q.t01#4.o3" to "Людей стало меньше",
    "q.t01#4.e" to "Скользкая поверхность одновременно удлиняет время и повышает вероятность падений и растяжений. Маршрут на 4 часа после дождя считают на 5–6 и заново оценивают, проходимы ли крутые спуски.",
    "q.t01#5.p" to "Партнёр говорит: «Я прошёл этот маршрут за 4 часа». Как это понимать?",
    "q.t01#5.o0" to "Я тоже пройду за 4 часа",
    "q.t01#5.o1" to "Это скорость опытного человека; группе нужно закладывать 1,3–1,5 от времени самого медленного",
    "q.t01#5.o2" to "Значит, маршрут простой",
    "q.t01#5.o3" to "Ориентироваться на это нельзя совсем",
    "q.t01#5.e" to "Чужое время опирается на форму, груз и знание маршрута. Группа считает по самому медленному, а потом добавляет отдых, фото и поиск пути — только тогда цифра близка к реальности.",
    "q.t01#6.p" to "Каков обычный грубый способ оценить время пешего маршрута?",
    "q.t01#6.o0" to "Взять время по расстоянию и добавлять по 30 минут на каждые 300–500 м набора",
    "q.t01#6.o1" to "Только по расстоянию",
    "q.t01#6.o2" to "Только по набору",
    "q.t01#6.o3" to "По весу тела",
    "q.t01#6.e" to "Чистое расстояние недооценивает затраты на подъём. Считая «время по расстоянию + время по набору» раздельно, а затем умножая на коэффициент группы, получаешь гораздо меньшую ошибку.",
    "q.t01#7.p" to "Зачем выяснять точки выхода до старта?",
    "q.t01#7.o0" to "Без возможности сойти посередине не может быть и речи о безопасности и корректировке плана",
    "q.t01#7.o1" to "Чтобы фотографировать",
    "q.t01#7.o2" to "Чтобы сэкономить на билетах",
    "q.t01#7.o3" to "Чтобы идти налегке",
    "q.t01#7.e" to "Точка выхода — предохранительный клапан маршрута. Без неё остаётся один путь: идти до конца чего бы это ни стоило.",
    "q.t02#0.p" to "Каков главный критерий правильной посадки треккинговой обуви?",
    "q.t02#0.o0" to "Чем теснее, тем устойчивее",
    "q.t02#0.o1" to "Пятка не скользит, а на спуске пальцы не упираются в носок",
    "q.t02#0.o2" to "Чем больше, тем удобнее",
    "q.t02#0.o3" to "Смотреть на бренд и цену",
    "q.t02#0.e" to "Примерять нужно после обеда, в треккинговых носках и пройтись по спуску. Если нога ездит внутри, на подъёме натирается ахилл, на спуске упираются пальцы, и мозоли появляются в обоих случаях.",
    "q.t02#1.p" to "Какова самая непосредственная причина появления мозолей?",
    "q.t02#1.o0" to "Обувь слишком новая",
    "q.t02#1.o1" to "Сложение влаги, трения и локального давления",
    "q.t02#1.o2" to "Слишком долгая ходьба",
    "q.t02#1.o3" to "Цвет носков",
    "q.t02#1.e" to "Один фактор редко действует сам по себе. Песок в обуви даёт локальное давление, пот размягчает кожу, и через полчаса ходьбы появляется мозоль.",
    "q.t02#2.p" to "Какое сочетание действий лучше всего предотвращает мозоли?",
    "q.t02#2.o0" to "Заранее заклеить уязвимые места пластырем, держать носки сухими и менять их в пути",
    "q.t02#2.o1" to "Надеть два хлопковых носка",
    "q.t02#2.o2" to "Распарить ноги перед выходом",
    "q.t02#2.o3" to "Идти без остановок, чтобы меньше снимать обувь",
    "q.t02#2.e" to "Пластырь переносит трение с кожи на наклейку, а смена носков решает вопрос влаги. Вместе эти две вещи закрывают большинство мозолей.",
    "q.t02#3.p" to "Что делать со шнуровкой на длинном спуске?",
    "q.t02#3.o0" to "Затянуть сильнее, чтобы нога меньше съезжала вперёд",
    "q.t02#3.o1" to "Полностью ослабить",
    "q.t02#3.o2" to "Оставить как на подъёме",
    "q.t02#3.o3" to "Затянуть только у щиколотки",
    "q.t02#3.e" to "На спуске нога уходит к носку. Подтянув среднюю часть и зону щиколотки и слегка ослабив подъём стопы, вы фиксируете пятку и не давите на верх стопы.",
    "q.t02#4.p" to "На ноге появилась «горячая точка»: локальное покраснение, жар и лёгкая боль при нажатии. Что делать?",
    "q.t02#4.o0" to "Сразу остановиться и обработать",
    "q.t02#4.o1" to "Заклеить пластырем или лентой",
    "q.t02#4.o2" to "Проверить, нет ли складок и песчинок в обуви и носке",
    "q.t02#4.o3" to "Идти дальше, разбираться после того, как натрёт",
    "q.t02#4.e" to "Горячая точка — обратимая стадия, на обработку нужно две минуты. После того как кожа повреждена, каждый шаг расширяет повреждение и возможна инфекция.",
    "q.t02#5.p" to "Почему на длинных маршрутах не рекомендуют хлопковые носки?",
    "q.t02#5.o0" to "Хлопок впитывает пот и не отводит его: мокрый носок и натирает, и перестаёт греть",
    "q.t02#5.o1" to "Хлопковые носки слишком дороги",
    "q.t02#5.o2" to "Они не дышат и пахнут",
    "q.t02#5.o3" to "Они быстро линяют",
    "q.t02#5.e" to "Хлопковое волокно, набрав воду, прилипает к коже и повышает трение; при похолодании мокрый носок быстро уносит тепло. Шерсть и синтетика отводят влагу и частично греют даже мокрыми.",
    "q.t02#6.p" to "Зачем нужна шнуровка с фиксацией пятки?",
    "q.t02#6.o0" to "Она прижимает пятку к заднику и уменьшает удар пальцев на спуске",
    "q.t02#6.o1" to "Чтобы обувь сидела плотнее",
    "q.t02#6.o2" to "Чтобы быстрее обуваться",
    "q.t02#6.o3" to "Чтобы меньше изнашивалась подошва",
    "q.t02#6.e" to "На спуске нога уходит вперёд, и повторяющиеся удары пальцев о носок — главная причина чёрных ногтей и мозолей. Фиксация пятки решает это напрямую.",
    "q.t02#7.p" to "Какой запас обычно советуют оставлять при покупке треккинговой обуви?",
    "q.t02#7.o0" to "Примерно палец перед пальцами ноги: на длинном маршруте стопа отекает",
    "q.t02#7.o1" to "Сидеть впритык",
    "q.t02#7.o2" to "На размер больше",
    "q.t02#7.o3" to "На два размера больше",
    "q.t02#7.e" to "После долгой ходьбы стопа слегка отекает. Запас в палец не даёт пальцам упираться на спуске и не приводит к натиранию из-за слишком свободной обуви.",
    "q.t03#0.p" to "Каков обычный предел веса рюкзака в походе?",
    "q.t03#0.o0" to "10–20 % массы тела, новичкам ближе к нижней границе",
    "q.t03#0.o1" to "Чем тяжелее, тем безопаснее",
    "q.t03#0.o2" to "30 % массы тела",
    "q.t03#0.o3" to "Предела нет",
    "q.t03#0.e" to "Вес напрямую превращается в нагрузку на суставы и расход кислорода. На первом многодневном походе держите рюкзак в пределах 12–15 % массы тела: если после перехода остались силы, вес выбран верно.",
    "q.t03#1.p" to "Куда класть тяжёлые вещи при укладке рюкзака?",
    "q.t03#1.o0" to "Ближе к спине, между лопатками и поясницей",
    "q.t03#1.o1" to "На самое дно",
    "q.t03#1.o2" to "В наружный карман",
    "q.t03#1.o3" to "В верхний клапан",
    "q.t03#1.e" to "Тяжёлое у спины и на уровне центра тяжести тела даёт минимальное раскачивание. На дне оно тянет вниз и давит на поясницу, снаружи отводит центр тяжести и заставляет компенсировать шеей.",
    "q.t03#2.p" to "Как правильно распределены роли лямок и поясного ремня?",
    "q.t03#2.o0" to "Вес несут лямки",
    "q.t03#2.o1" to "Основной вес берёт поясной ремень, лямки отвечают за прилегание и устойчивость",
    "q.t03#2.o2" to "Поясной ремень — только украшение",
    "q.t03#2.o3" to "Как получится",
    "q.t03#2.e" to "Поясной ремень передаёт вес на таз — самую способную к нагрузке часть тела. Слишком затянутые лямки пережимают сосуды плеча, и через время руки немеют.",
    "q.t03#3.p" to "Что уместно держать в верхнем клапане или снаружи?",
    "q.t03#3.o0" to "Дождевик, карту, налобный фонарь",
    "q.t03#3.o1" to "Воду и перекусы на день",
    "q.t03#3.o2" to "Дуги палатки, пристёгнутые снаружи",
    "q.t03#3.o3" to "Самую тяжёлую флягу",
    "q.t03#3.e" to "В клапан и наружу кладут только то, что нужно в любой момент, или то, что имеет неудобную форму. Тяжёлое снаружи ломает центр тяжести и цепляется за ветки и камни на узкой тропе.",
    "q.t03#4.p" to "К чему приводит рюкзак, который не прилегает к спине?",
    "q.t03#4.o0" to "Центр тяжести уходит назад, шея и плечи компенсируют, на спуске становится неустойчиво",
    "q.t03#4.o1" to "Просто некрасиво",
    "q.t03#4.o2" to "Уменьшается объём",
    "q.t03#4.o3" to "Ни к чему",
    "q.t03#4.e" to "Когда между спинкой и спиной есть зазор, рюкзак раскачивается в такт шагам. Чтобы его удержать, человек невольно наклоняется и поднимает плечи, и через несколько часов первой устаёт спина.",
    "q.t03#5.p" to "Зачем взвешивать рюкзак перед выходом?",
    "q.t03#5.o0" to "Зная базовый вес, можно понять, что именно лишнее",
    "q.t03#5.o1" to "В аэропорту проверяют",
    "q.t03#5.o2" to "Чтобы выложить в соцсети",
    "q.t03#5.o3" to "Практического смысла нет",
    "q.t03#5.e" to "Взвешивание превращает «кажется, тяжеловато» в цифру. Из одного и того же рюкзака за счёт дублирующей посуды, лишней одежды и полной фляги обычно уходит два-три килограмма.",
    "q.t03#6.p" to "Каково распространённое мнение о верхнем пределе веса рюкзака в процентах от массы тела?",
    "q.t03#6.o0" to "20–25 %",
    "q.t03#6.o1" to "10 %",
    "q.t03#6.o2" to "40 %",
    "q.t03#6.o3" to "Предела нет",
    "q.t03#6.e" to "Выше этой доли заметно растут и затраты на подъём, и риск травм. Облегчение начинают с «того, что можно не брать».",
    "q.t03#7.p" to "Какова главная роль треккинговых палок на спуске?",
    "q.t03#7.o0" to "Распределить нагрузку с коленей и добавить точку опоры",
    "q.t03#7.o1" to "Ускорить движение",
    "q.t03#7.o2" to "Уменьшить вес рюкзака",
    "q.t03#7.o3" to "Для самообороны",
    "q.t03#7.e" to "На спуске колени получают ударную нагрузку в несколько раз больше, чем на подъёме. Палки переносят часть нагрузки на руки и дают третью точку опоры.",
    "q.t04#0.p" to "Как выдерживать устойчивый темп на подъёме?",
    "q.t04#0.o0" to "Держать интенсивность, при которой можете говорить целыми фразами, и отдыхать до наступления усталости",
    "q.t04#0.o1" to "Рвануть до вершины, а потом отдыхать",
    "q.t04#0.o2" to "Идти за самым быстрым",
    "q.t04#0.o3" to "Всё время идти очень медленно",
    "q.t04#0.e" to "«Разговорный тест» — самый простой измеритель интенсивности. Если фраза не складывается, надо сбавить темп; когда человек останавливается уже на грани, восстановление занимает дольше.",
    "q.t04#1.p" to "Каков правильный ритм питья?",
    "q.t04#1.o0" to "Пить, когда захотелось",
    "q.t04#1.o1" to "Малыми глотками каждые 20–30 минут, в жару с электролитами",
    "q.t04#1.o2" to "Выпить литр за раз",
    "q.t04#1.o3" to "Пить как можно меньше, чтобы реже отходить",
    "q.t04#1.e" to "К моменту появления жажды уже потеряно около 1–2 % массы тела, и оценка с выносливостью начинают падать. Питьё малыми порциями по часам усваивается легче, чем литр залпом.",
    "q.t04#2.p" to "Как эффективнее восполнять энергию в движении?",
    "q.t04#2.o0" to "30–60 г углеводов в час, дробно",
    "q.t04#2.o1" to "Один большой приём, когда проголодался",
    "q.t04#2.o2" to "Только спортивные напитки",
    "q.t04#2.o3" to "Терпеть на силе воли до лагеря",
    "q.t04#2.e" to "Организм способен усвоить за час ограниченное количество углеводов, и слишком большой объём за раз даёт лишь тяжесть в животе. Есть на ходу (орехи, батончики, хлеб) надёжнее, чем останавливаться на плотную еду.",
    "q.t04#3.p" to "Какие ранние признаки гипогликемии нужно знать?",
    "q.t04#3.o0" to "Дрожь в руках и холодный пот",
    "q.t04#3.o1" to "Внезапная раздражительность или замедленная реакция",
    "q.t04#3.o2" to "Побеление и «плывущая» картинка в глазах",
    "q.t04#3.o3" to "Внезапный прилив сил",
    "q.t04#3.e" to "При таких признаках нужно остановиться и съесть 15–20 г быстрых углеводов (сахар, сок): заметное облегчение приходит в течение десяти минут. Если терпеть, можно просто потерять сознание.",
    "q.t04#4.p" to "Почему не стоит отдыхать дольше 10 минут?",
    "q.t04#4.o0" to "Тело остывает, мышцы деревенеют, и снова разогнаться дороже по силам",
    "q.t04#4.o1" to "Партнёры будут жаловаться",
    "q.t04#4.o2" to "Это потеря времени",
    "q.t04#4.o3" to "Оснований нет",
    "q.t04#4.e" to "После долгого покоя пульс падает, температура мышц снижается, и первый километр после отдыха идёт особенно тяжело. Несколько коротких пауз суммарно экономят больше времени, чем одна длинная.",
    "q.t04#5.p" to "При каких условиях в походе обычно «ловят стену»?",
    "q.t04#5.o0" to "Через 2–3 часа после выхода гликоген кончается, а пополнения почти не было",
    "q.t04#5.o1" to "Перед выходом в первый день",
    "q.t04#5.o2" to "На спуске",
    "q.t04#5.o3" to "При нехватке сна",
    "q.t04#5.e" to "Запаса гликогена хватает примерно на 90–120 минут работы средней интенсивности. Если после этого углеводы не поступали, появляются внезапная слабость, головокружение и нежелание разговаривать.",
    "q.t04#6.p" to "Какой самый практичный субъективный показатель правильного темпа?",
    "q.t04#6.o0" to "«Разговорный тест»: вы ещё можете говорить целыми фразами",
    "q.t04#6.o1" to "Цифры пульса",
    "q.t04#6.o2" to "Количество пота",
    "q.t04#6.o3" to "Частота шагов",
    "q.t04#6.e" to "Способность говорить целыми фразами означает, что вы ещё в аэробной зоне. Если фраза не складывается, интенсивность слишком высока и на длинном маршруте силы кончатся раньше.",
    "q.t04#7.p" to "Какой момент для приёма электролитов в жару забывают чаще всего?",
    "q.t04#7.o0" to "Перед выходом и в первой половине маршрута, а не тогда, когда уже свело мышцу",
