    "q.t04#7.o3" to "Во время еды",
    "q.t04#7.e" to "Судорога означает, что дефицит уже есть. Малыми порциями, заранее и на протяжении всего маршрута — эффективнее, чем залпом после случившегося.",
    "q.t15#0.p" to "Что важнее всего сделать с картой в телефоне перед выходом в горы?",
