    "q.t15#0.o3" to "Включить энергосбережение",
    "q.t15#0.e" to "Офлайн-подложка плюс офлайн-трек — единственное, что работает при «заряд есть, связи нет».",
    "q.t15#1.p" to "На карте 1:50 000 два сантиметра соответствуют скольким метрам на местности?",
