    "q.t15#1.e" to "1 см = 500 м, значит 2 см = 1 000 м. Ошибка в масштабе тянет за собой все остальные.",
    "q.t15#2.p" to "Что означает более плотное расположение горизонталей?",
    "q.t15#2.o0" to "Склон круче",
    "q.t15#2.o1" to "Склон положе",
    "q.t15#2.o2" to "Высота больше",
    "q.t15#2.o3" to "Тропа шире",
    "q.t15#2.e" to "Плотность показывает больший перепад высот на том же горизонтальном расстоянии. Именно по ней оценивают, будет ли участок тяжёлым.",
    "q.t15#3.p" to "Какой способ ориентации в поле самый надёжный и не зависит от электроники?",
    "q.t15#3.o0" to "Компас и карта",
    "q.t15#3.o1" to "По форме деревьев",
    "q.t15#3.o2" to "По движению облаков",
    "q.t15#3.o3" to "По ощущениям",
    "q.t15#3.e" to "Растительность и облака дают лишь вспомогательные признаки с большой погрешностью. Компас вместе с картой — единственное устойчивое сочетание.",
    "q.t15#4.p" to "Вы заподозрили, что сбились с пути. Что делать в первую очередь?",
    "q.t15#4.o0" to "Остановиться и, оглянувшись, найти три заметных ориентира для проверки своего положения",
