    "q.t15#4.o2" to "Ускориться",
    "q.t15#4.o3" to "Позвонить знакомым",
    "q.t15#4.e" to "Остановка и взгляд назад — единственный способ превратить «кажется, сбился» в «точно сбился». Движение дальше только увеличивает ошибку.",
    "q.t15#5.p" to "Что нужно заранее подготовить в офлайн-навигационном наборе?",
    "q.t15#5.o0" to "Офлайн-карту",
    "q.t15#5.o1" to "Трек маршрута в формате GPX",
    "q.t15#5.o2" to "Запасной источник питания",
    "q.t15#5.o3" to "Приложения соцсетей",
    "q.t15#5.e" to "Первые три пункта обеспечивают работу без связи. Соцсети в горах без сети бесполезны.",
    "q.t15#6.p" to "Расставьте порядок проверки своего положения.",
    "q.t15#6.o0" to "Открыть офлайн-карту и определить текущее положение",
    "q.t15#6.o1" to "Соотнести местность со склоном и рисунком горизонталей",
    "q.t15#6.o2" to "Найти следующий заметный ориентир",
    "q.t15#6.o3" to "Подтвердить направление движения и оставшееся расстояние",
    "q.t15#6.e" to "Определение положения — это не «посмотреть на синюю точку», а «сверить точку с рельефом». Ключевой здесь второй шаг.",
    "q.t15#7.p" to "Партнёр говорит: «Пойдём за людьми, точно не ошибёмся». Что ответить разумнее?",
    "q.t15#7.o0" to "Люди могут идти к другой цели: сначала сверим маршрут, потом пойдём",
    "q.t15#7.o1" to "За ними проще всего",
    "q.t15#7.o2" to "Где много людей, там точно безопасно",
    "q.t15#7.o3" to "Достаточно спросить",
    "q.t15#7.e" to "На развилке «поток людей» часто уходит на другую линию. Одна сверка с картой стоит десять секунд.",
    "q.t05#0.p" to "Что нужно определить первым при планировании многодневного маршрута?",
    "q.t05#0.o0" to "Пределы дневного километража и набора высоты, а также точки пополнения и отхода",
    "q.t05#0.o1" to "Какие достопримечательности по пути",
    "q.t05#0.o2" to "В какой гостинице жить",
    "q.t05#0.o3" to "Что фотографировать",
    "q.t05#0.e" to "Сначала проводят черту «сколько максимум в день», а потом вписывают в неё маршрут. При обратном порядке получается график, который невозможно пройти, и люди идут ночью.",
    "q.t05#1.p" to "Зачем нужен резервный день?",
    "q.t05#1.o0" to "Чтобы задержка из-за погоды или травмы не превратилась в ночной марш-бросок",
    "q.t05#1.o1" to "Чтобы подольше поспать",
    "q.t05#1.o2" to "Чтобы оставить время на фото",
    "q.t05#1.o3" to "Практического смысла нет",
    "q.t05#1.e" to "На многодневном маршруте задержки почти неизбежны. С резервным днём это просто минус один переход; без него — ночная ходьба или проход опасного участка силой.",
    "q.t05#2.p" to "Какие затраты времени недооценивают чаще всего?",
    "q.t05#2.o0" to "Поиск пути и исправление ошибок",
    "q.t05#2.o1" to "Забор и фильтрация воды",
