    "q.t05#2.o3" to "Ходьба по ровному",
    "q.t05#2.e" to "Расстояние на карте соответствует только самой ходьбе. В реальном дне есть ещё поиск пути, вода, палатка, еда и сборы, и вместе это обычно 1,5–2 часа.",
    "q.t05#3.p" to "Какова рекомендуемая плотность точек отхода?",
    "q.t05#3.o0" to "Минимум одна возможность сойти — перекрёсток или деревня — на каждый день",
    "q.t05#3.o1" to "Достаточно одной на весь маршрут",
    "q.t05#3.o2" to "Не нужны",
    "q.t05#3.o3" to "Одна на пять дней",
    "q.t05#3.e" to "Слишком редкие точки отхода означают, что «обязан дойти» вписано в сам план. Только зная ближайший выход на каждом участке, вы действительно имеете выбор.",
    "q.t05#4.p" to "Почему самый длинный день не стоит ставить первым?",
    "q.t05#4.o0" to "В первый день хуже всего состояние и оценка: нет привычки ни к грузу, ни к высоте",
    "q.t05#4.o1" to "В первый день плохие виды",
    "q.t05#4.o2" to "В первый день обычно дождь",
    "q.t05#4.o3" to "Разницы нет",
    "q.t05#4.e" to "Организму нужен день-два на адаптацию: спина привыкает к грузу, ноги к обуви, человек к темпу. Самый тяжёлый день в середине даёт больше шансов дойти и меньше травм.",
    "q.t05#5.p" to "В плане написано «расчётное прибытие через 6 часов». Что нужно добавить?",
    "q.t05#5.o0" to "Предельное время прибытия, после которого включается запасной вариант",
    "q.t05#5.o1" to "Ожидаемую температуру",
    "q.t05#5.o2" to "Телефоны попутчиков",
    "q.t05#5.o3" to "Ничего добавлять не нужно",
    "q.t05#5.e" to "Расчётное время — это ожидание, предельное — линия решения. Если предельное время прошло, а вы не на месте, включают запасной лагерь или возвращаются, а не продолжают испытывать удачу.",
    "q.t05#6.p" to "Зачем в многодневный маршрут закладывают резервные дни?",
    "q.t05#6.o0" to "Погода, травмы и транспортные задержки съедают время; без резерва срезается запас безопасности",
    "q.t05#6.o1" to "Чтобы отдохнуть",
    "q.t05#6.o2" to "Чтобы фотографировать",
    "q.t05#6.o3" to "Чтобы сэкономить",
    "q.t05#6.e" to "Резервный день — часть плана. Если считать его потерей, в итоге срежут именно отдых и безопасность.",
    "q.t05#7.p" to "Каково рекомендованное время прихода в лагерь на многодневном маршруте?",
    "q.t05#7.o0" to "Оставлять 1–2 часа светлого времени на установку лагеря и готовку",
    "q.t05#7.o1" to "В последний момент перед темнотой",
    "q.t05#7.o2" to "Чем позже, тем прохладнее",
    "q.t05#7.o3" to "Не имеет значения",
    "q.t05#7.e" to "В темноте лагерь ставится крайне неэффективно, и легко пропустить опасность на месте. Вписать время прихода в план — это дисциплина.",
    "q.t06#0.p" to "Какое расстояние от лагеря до воды обычно считается минимальным?",
    "q.t06#0.o0" to "5 м",
    "q.t06#0.o1" to "60 м",
    "q.t06#0.o2" to "200 м",
    "q.t06#0.o3" to "Чем ближе, тем лучше",
    "q.t06#0.e" to "60 м — минимальное требование большинства охраняемых территорий. Слишком близко — и вы загрязняете источник, и рискуете встретить животных, приходящих на водопой. Умывание и мытьё посуды тоже не ближе 60 м.",
    "q.t06#1.p" to "Каких мест нужно избегать при выборе лагеря?",
    "q.t06#1.o0" to "Камнепадного участка прямо под крутым склоном",
    "q.t06#1.o1" to "Пересохшего русла",
    "q.t06#1.o2" to "Места под одиноким большим деревом",
    "q.t06#1.o3" to "Места, где проходит звериная тропа",
    "q.t06#1.e" to "Все четыре — из категории «обычно тихо, но если случится, то тяжело»: камни, паводок, молния, звери. Лагерь стоит на месте всю ночь, и запаса на такой риск у него нет.",
    "q.t06#2.p" to "Почему в лагере рекомендуют небольшой уклон?",
    "q.t06#2.o0" to "Чтобы был сток и в дождь не стояла вода",
    "q.t06#2.o1" to "Чтобы крепче спалось",
    "q.t06#2.o2" to "Чтобы выглядело аккуратно",
    "q.t06#2.o3" to "Чтобы палатка не деформировалась",
    "q.t06#2.e" to "На идеально ровном месте в ливень собирается вода. Уклон 2–3° отводит её, а положение «голова выше ног» не даёт сползать во сне.",
    "q.t06#3.p" to "Как поставить палатку устойчивее?",
    "q.t06#3.o0" to "Вход с подветренной стороны, длинная сторона на ветер",
    "q.t06#3.o1" to "Вход на ветер",
    "q.t06#3.o2" to "Как получится",
    "q.t06#3.o3" to "По направлению к солнцу",
    "q.t06#3.e" to "При входе с подветренной стороны вас не задувает при выходе, и меньше заносит дождём. Когда длинная сторона обращена к ветру, площадь сопротивления минимальна, и дуги нагружены ровнее.",
    "q.t06#4.p" to "Почему не ставят лагерь на гребне?",
    "q.t06#4.o0" to "Там сильный ветер и высокий риск удара молнии",
    "q.t06#4.o1" to "Слишком открытые виды",
    "q.t06#4.o2" to "Слишком твёрдая земля",
    "q.t06#4.o3" to "Слишком близко к воде",
    "q.t06#4.e" to "Гребень — высшая точка рельефа, ветер почти без преград, а в грозу это самое вероятное место удара. Лагерь смещают на подветренную сторону гребня и чуть ниже.",
    "q.t06#5.p" to "Что делать после снятия лагеря?",
    "q.t06#5.o0" to "Восстановить поверхность, забрать весь мусор, проверить, не осталось ли чего-то",
    "q.t06#5.o1" to "Просто уйти",
    "q.t06#5.o2" to "Закопать мусор в землю",
    "q.t06#5.o3" to "Оставить дрова следующему",
    "q.t06#5.e" to "На этом месте будут стоять и другие. Пройтись и проверить колышки, обёртки и крошки, по возможности распрямить примятую траву — это минимум вежливости.",
    "q.t07#0.p" to "Как грубо оценить расход топлива?",
    "q.t07#0.o0" to "30–50 г газа на человека в день",
    "q.t07#0.o1" to "200 г на человека в день",
    "q.t07#0.o2" to "50 г на группу в день",
    "q.t07#0.o3" to "Оценивать не нужно",
    "q.t07#0.e" to "Для обычного маршрута с готовкой на воде 30–50 г на человека в день — устойчивая оценка. На холоде, при таянии снега и варке еды норму поднимают, а лучше взять ещё один баллон в запас.",
    "q.t07#1.p" to "Каким свойствам продуктов отдают приоритет при планировании?",
    "q.t07#1.o0" to "Высокая калорийность",
    "q.t07#1.o1" to "Хорошая сохранность",
    "q.t07#1.o2" to "Минимум мытья и чистки котла",
    "q.t07#1.o3" to "Необходимость долгой варки",
    "q.t07#1.e" to "Каждый грамм в рюкзаке оплачивается силами, каждая минута на горелке — топливом. Сублиматы, орехи, хлопья и хлеб из серии «залил водой и готово» — самое выгодное.",
    "q.t07#2.p" to "Почему на высоте предпочитают углеводы?",
    "q.t07#2.o0" to "Они требуют меньше кислорода на переработку и быстро становятся доступной энергией",
    "q.t07#2.o1" to "Углеводы дешевле",
    "q.t07#2.o2" to "Углеводы легче",
    "q.t07#2.o3" to "Разницы нет",
    "q.t07#2.e" to "У жира калорий на грамм больше, но на его обмен нужно больше кислорода. В условиях гипоксии углеводы — более «экономный по кислороду» источник.",
    "q.t07#3.p" to "Что важнее всего помнить при использовании горелки в палатке?",
    "q.t07#3.o0" to "Держать вентиляцию, чтобы не получить отравление угарным газом",
    "q.t07#3.o1" to "Сделать огонь поменьше",
    "q.t07#3.o2" to "Не разговаривать",
    "q.t07#3.o3" to "Сначала зажечь свечу для прогрева",
    "q.t07#3.e" to "Ранние признаки отравления угарным газом (головная боль, сонливость) почти не отличить от высотной болезни и усталости, и беда обычно приходит во сне. В палатке обязателен вентиляционный выход.",
    "q.t07#4.p" to "Каков самый надёжный способ обработки воды в поле?",
    "q.t07#4.o0" to "Кипячение в течение 1 минуты",
    "q.t07#4.o1" to "Фильтрация через ткань",
    "q.t07#4.o2" to "Отстаивание",
    "q.t07#4.o3" to "Добавить сахар",
    "q.t07#4.e" to "Кипячение убивает бактерии, вирусы и паразитов. Фильтр против вирусов работает ограниченно, а химическим таблеткам нужно время выдержки. На высоте вода кипит при меньшей температуре, поэтому кипячение удлиняют.",
    "q.t07#5.p" to "Как лучше всего фасовать продукты?",
    "q.t07#5.o0" to "По дням, с подписанной датой, чтобы не перерывать весь мешок",
    "q.t07#5.o1" to "Высыпать всё в один большой мешок",
    "q.t07#5.o2" to "Запихнуть в рюкзак в заводской упаковке",
    "q.t07#5.o3" to "Фасовать по вкусам",
    "q.t07#5.e" to "Фасовка по дням задаёт темп расхода и не даёт «сначала поесть хорошо, а потом не хватить». Дата на пакете решает ещё одну задачу: понятно, что открывать первым.",
    "q.t08#0.p" to "Какие три сведения о погоде важнее всего перед выходом?",
    "q.t08#0.o0" to "Тренд на 24–48 часов, вероятность осадков, ветер и ощущаемая температура",
    "q.t08#0.o1" to "Максимальная температура дня",
    "q.t08#0.o2" to "Вчерашняя погода",
    "q.t08#0.o3" to "Влажность воздуха",
    "q.t08#0.e" to "Одна фраза «сколько сегодня градусов» несёт мало информации. Тренд определяет, менять ли план, вероятность осадков — что брать, ветер — как будет ощущаться и устоите ли вы на открытом месте.",
    "q.t08#1.p" to "О чём говорит растёкшаяся в наковальню вершина кучево-дождевого облака?",
    "q.t08#1.o0" to "Гроза уже созрела: возможны сильные осадки, град и молнии",
    "q.t08#1.o1" to "Погода скоро наладится",
    "q.t08#1.o2" to "Это просто высокое облако, влияния нет",
    "q.t08#1.o3" to "Скоро пойдёт снег",
    "q.t08#1.e" to "Наковальня означает, что восходящий поток дошёл до тропопаузы и облако достигло максимальной стадии. В этот момент нужно как можно быстрее уйти с гребня, открытого места и от одиночных деревьев.",
    "q.t08#2.p" to "Какие признаки могут появиться перед грозой?",
    "q.t08#2.o0" to "Далёкий гром",
    "q.t08#2.o1" to "Потемневшее и опускающееся основание облаков",
    "q.t08#2.o2" to "Резкая смена ветра и падение температуры",
    "q.t08#2.o3" to "Волосы встают дыбом, кожа покалывает",
    "q.t08#2.e" to "Последний пункт означает, что заряд уже силён и удар может быть рядом: немедленно снижайте высоту и приседайте, поставив ступни вместе, но не ложитесь.",
    "q.t08#3.p" to "Какое действие при грозе верное?",
    "q.t08#3.o0" to "Уйти с гребня и от одиночных деревьев, снизить высоту, разойтись примерно на 50 м",
    "q.t08#3.o1" to "Спрятаться под самым высоким деревом",
    "q.t08#3.o2" to "Быстро идти дальше по гребню",
    "q.t08#3.o3" to "Сбиться в кучу и греться",
    "q.t08#3.e" to "Молния предпочитает высшую точку. Расходятся для того, чтобы при ударе в одного остальные могли помочь; сбившись в кучу, вы превращаете один удар в несколько пострадавших.",
    "q.t08#4.p" to "Каково самое раннее и самое надёжное проявление переохлаждения?",
    "q.t08#4.o0" to "Постоянная дрожь, неуклюжие движения, невнятная речь",
    "q.t08#4.o1" to "Покраснение кожи",
    "q.t08#4.o2" to "Сильное потоотделение",
    "q.t08#4.o3" to "Замедление пульса",
    "q.t08#4.e" to "Дрожь — способ организма согреваться. Прекращение дрожи не означает улучшения, а может быть признаком более тяжёлого состояния. Порядок действий: укрытие от ветра, сухая одежда, изоляция, горячее питьё.",
    "q.t08#5.p" to "Почему при той же температуре воздуха с ветром кажется холоднее?",
    "q.t08#5.o0" to "Ветер ускоряет потерю тепла с поверхности кожи, и ощущаемая температура заметно ниже",
    "q.t08#5.o1" to "Ветер задувает холодный воздух под одежду",
    "q.t08#5.o2" to "Это психологический эффект",
    "q.t08#5.o3" to "Из-за изменения влажности",
    "q.t08#5.e" to "Это эффект ветрового охлаждения. При 0 °C и ветре 40 км/ч ощущается примерно как −10 °C. Сколько надеть, решают по ощущаемой температуре, а не по цифре на термометре.",
    "q.t16#0.p" to "Каково базовое разделение лагеря на зоны?",
    "q.t16#0.o0" to "Сон, готовка и туалет раздельно",
    "q.t16#0.o1" to "Мужчины, женщины, общая",
    "q.t16#0.o2" to "Палатка, машина, костёр",
    "q.t16#0.o3" to "Зонировать не нужно",
    "q.t16#0.e" to "Зонирование решает три задачи: риск открытого огня, привлечение животных запахом и перекрёстное загрязнение в вопросах гигиены.",
    "q.t16#1.p" to "Каковы разумные глубина кошачьей ямки и расстояние до воды?",
    "q.t16#1.o0" to "Глубина 15–20 см, не ближе 60 м от воды",
    "q.t16#1.o1" to "Глубина 5 см, 5 м от воды",
    "q.t16#1.o2" to "Чем глубже и дальше, тем лучше",
    "q.t16#1.o3" to "Копать не нужно",
    "q.t16#1.e" to "Слишком мелко — не разложится, слишком близко — загрязнит источник. 60 м — общепринятое расстояние.",
    "q.t16#2.p" to "Как правильно поступить с туалетной бумагой?",
    "q.t16#2.o0" to "Сложить в пакет и унести",
    "q.t16#2.o1" to "Сжечь",
    "q.t16#2.o2" to "Закопать в ямку",
    "q.t16#2.o3" to "Бросить в траву",
    "q.t16#2.e" to "Сжигание бумаги в сухой сезон грозит пожаром, а закопанная бумага выходит на поверхность после таяния снега или раскопок животными. Унести — самое чистое решение.",
    "q.t16#3.p" to "Как правильно поступать с водой после мытья посуды?",
    "q.t16#3.o0" to "Процедить остатки, воду разбрызгать, остатки унести",
    "q.t16#3.o1" to "Вылить прямо в ручей",
    "q.t16#3.o2" to "Вылить у палатки",
    "q.t16#3.o3" to "Вылить в кошачью ямку",
    "q.t16#3.e" to "Остатки — источник загрязнения и приманка для животных: их процеживают и уносят, а воду разбрызгивают, чтобы она не собиралась в одной точке.",
    "q.t16#4.p" to "Какие три вещи важнее всего для ухода за ногами в походе?",
    "q.t16#4.o0" to "Каждый день мыть ноги, менять носки на сухие, сушить обувь",
    "q.t16#4.o1" to "Больше ходить",
    "q.t16#4.o2" to "Надевать толстые носки",
    "q.t16#4.o3" to "Мазать мазью",
    "q.t16#4.e" to "И мозоли, и размягчение кожи возникают из «влаги плюс трения». Поддержание сухости действует лучше любой мази.",
    "q.t16#5.p" to "Каких действий в лагере нужно избегать?",
    "q.t16#5.o0" to "Есть в палатке",
    "q.t16#5.o1" to "Оставлять пищевые остатки в лагере",
    "q.t16#5.o2" to "Мыть посуду у воды",
    "q.t16#5.o3" to "Ставить обувь в тамбур перед сном",
    "q.t16#5.e" to "Первые три пункта тянут животных и загрязнение в спальную зону. Обувь в тамбуре — обычная практика, но её нужно сначала вытрясти.",
    "q.t16#6.p" to "Расставьте порядок утреннего сворачивания лагеря.",
    "q.t16#6.o0" to "Сначала убрать спальник в гермомешок",
    "q.t16#6.o1" to "Собрать мелочи и мусор внутри палатки",
    "q.t16#6.o2" to "Разобрать палатку, стряхнуть росу и иней",
    "q.t16#6.o3" to "Обойти лагерь и убедиться, что ничего не осталось",
    "q.t16#6.e" to "Последний шаг пропускают чаще всего: забытые в лагере вещи — самый частый минус в «не оставлять следов».",
    "q.t16#7.p" to "Рядом с лагерем есть следы животных (помет, раскопы). Что делать?",
    "q.t16#7.o0" to "Подвесить или герметично упаковать еду подальше от спальной зоны",
    "q.t16#7.o1" to "Продолжать готовить на том же месте",
    "q.t16#7.o2" to "Покормить животное",
    "q.t16#7.o3" to "Положить еду в палатку",
    "q.t16#7.e" to "Животных привлекает запах. Еда в палатке — самое опасное решение: она ведёт зверя прямо туда, где вы спите.",
    "q.t09#0.p" to "Какую скорость подъёма высоты ночёвки рекомендуют выше 3 000 м?",
    "q.t09#0.o0" to "Не более 500 м в день",
    "q.t09#0.o1" to "1 000 м в день",
    "q.t09#0.o2" to "1 500 м в день",
    "q.t09#0.o3" to "Ограничений нет",
    "q.t09#0.e" to "Обычная стратегия — «идти высоко, спать низко»: днём можно подняться выше, но высота сна не должна расти больше чем на 500 м в сутки. Слишком быстрый подъём — главный провокатор AMS.",
    "q.t09#1.p" to "Какая группа признаков наиболее типична для острой горной болезни (AMS)?",
    "q.t09#1.o0" to "Головная боль с тошнотой или потерей аппетита, плюс головокружение и слабость",
    "q.t09#1.o1" to "Боли в суставах и сыпь",
    "q.t09#1.o2" to "Постоянный кашель с кровью",
    "q.t09#1.o3" to "Температура до 39 °C",
    "q.t09#1.e" to "Смысл имеют именно три пункта вместе: одна головная боль может быть от обезвоживания или усталости, а в сочетании с плохим аппетитом и слабостью это уже больше похоже на AMS.",
    "q.t09#2.p" to "Что правильно делать при появлении симптомов AMS?",
    "q.t09#2.o0" to "Прекратить подъём, акклиматизироваться на месте или спуститься",
    "q.t09#2.o1" to "Принять таблетку и продолжить подъём по плану",
    "q.t09#2.o2" to "Пить больше воды и идти дальше, перетерпеть",
    "q.t09#2.o3" to "Ускориться, чтобы дойти до лагеря и там отдохнуть",
    "q.t09#2.e" to "Главный принцип — не подниматься с симптомами. Если они легкие и условия позволяют, можно остаться на месте на лишний день; при усилении нужно спускаться.",
    "q.t09#3.p" to "Какие сигналы требуют немедленного спуска?",
    "q.t09#3.o0" to "Одышка даже в покое",
    "q.t09#3.o1" to "Шаткая походка, как у пьяного",
    "q.t09#3.o2" to "Спутанность сознания или странное поведение",
    "q.t09#3.o3" to "Слабая головная боль",
    "q.t09#3.e" to "Эти три пункта означают, что процесс мог уже перейти в HAPE или HACE. Направление действий одно: вниз, одновременно кислород и медицинская помощь.",
    "q.t09#4.p" to "Почему советуют «спать пониже»?",
    "q.t09#4.o0" to "Ночью дыхание становится поверхностнее, гипоксия сильнее, и сон ниже её уменьшает",
    "q.t09#4.o1" to "Внизу тише",
    "q.t09#4.o2" to "Внизу теплее",
    "q.t09#4.o3" to "Внизу лучше виды",
    "q.t09#4.e" to "Во сне вентиляция падает, и сатурация оказывается ниже, чем при бодрствовании. Поставить лагерь на несколько сотен метров ниже высшей точки дня — значит оставить запас для себя ночного.",
    "q.t09#5.p" to "Значит ли хорошая физическая форма, что горная болезнь менее вероятна?",
    "q.t09#5.o0" to "Не обязательно: всё решают скорость подъёма и индивидуальные особенности",
    "q.t09#5.o1" to "Да, чем лучше форма, тем безопаснее",
    "q.t09#5.o2" to "Нет, чем лучше форма, тем вероятнее",
    "q.t09#5.o3" to "Зависит только от возраста",
    "q.t09#5.e" to "Люди в хорошей форме часто идут быстрее и поднимаются выше, поэтому и попадают в группу риска чаще. Разделять форму и способность к акклиматизации на высоте очень важно.",
    "q.t10#0.p" to "На сколько слоёв обычно делят систему одежды в высокогорном походе?",
    "q.t10#0.o0" to "Отводящий влагу, утепляющий, ветрозащитный",
    "q.t10#0.o1" to "Нижнее бельё и куртка",
    "q.t10#0.o2" to "Хлопковая куртка, свитер, дождевик",
    "q.t10#0.o3" to "Чем больше, тем лучше",
    "q.t10#0.e" to "Слои нужны не для того, чтобы одеться теплее, а чтобы регулировать температуру. Разогрелись — снять внешний слой, остановились — сразу надеть: переохлаждение часто случается именно в те десять минут отдыха.",
    "q.t10#1.p" to "На сколько примерно растёт интенсивность ультрафиолета на каждые 1 000 м высоты?",
    "q.t10#1.o0" to "10–12 %",
    "q.t10#1.o1" to "2 %",
    "q.t10#1.o2" to "50 %",
    "q.t10#1.o3" to "Не меняется",
    "q.t10#1.e" to "Воздух становится тоньше и хуже фильтрует ультрафиолет. Вместе с отражением от снега около 80 % реальная доза на лице и носу почти удваивается.",
    "q.t10#2.p" to "Что должно входить в защиту от солнца на высоте?",
    "q.t10#2.o0" to "Очки UV400",
    "q.t10#2.o1" to "Крем SPF50+ с обновлением каждые 2–3 часа",
    "q.t10#2.o2" to "Гигиеническая помада с защитой от солнца",
    "q.t10#2.o3" to "Головной убор или бафф",
    "q.t10#2.e" to "Каждый пункт закрывает своё: глаза, кожу, губы, лицо. В губах нет меланина, они трескаются первыми и чаще всего остаются без внимания.",
    "q.t10#3.p" to "Почему руки и ноги мёрзнут первыми?",
    "q.t10#3.o0" to "Организм бережёт температуру ядра и сужает сосуды на конечностях",
    "q.t10#3.o1" to "На руках и ногах мало жира",
    "q.t10#3.o2" to "Они мало двигаются",
    "q.t10#3.o3" to "Это психологический эффект",
    "q.t10#3.e" to "Это нормальный механизм выживания. Поэтому тепло сосредотачивают на корпусе: согреется ядро — пойдёт кровь в конечности. Одни только перчатки без утепления корпуса дают мало.",
    "q.t10#4.p" to "Что делать, если перчатки и носки намокли?",
    "q.t10#4.o0" to "Сразу заменить: мокрый слой постоянно уносит тепло",
    "q.t10#4.o1" to "Продолжать носить, на ходу высохнет",
    "q.t10#4.o2" to "Просто отжать",
    "q.t10#4.o3" to "Сменить на следующий день",
    "q.t10#4.e" to "Мокрая ткань проводит тепло в несколько раз быстрее сухой. Как только руки и ноги застыли, движения замедляются, и ошибки при работе со снаряжением и при ходьбе становятся вероятнее.",
    "q.t10#5.p" to "Что такое снежная слепота?",
    "q.t10#5.o0" to "Ультрафиолетовый ожог роговицы: через 6–12 часов сильная боль, светобоязнь, слёзы",
    "q.t10#5.o1" to "Усталость глаз от отражённого снегом света",
    "q.t10#5.o2" to "Обморожение глазного яблока",
    "q.t10#5.o3" to "Нехватка витамина A",
    "q.t10#5.e" to "Снежная слепота проявляется с задержкой: днём ничего не чувствуешь, боль приходит вечером. Профилактика почти целиком в очках, причём носить их нужно и в пасмурную погоду, и в снежной дымке.",
    "q.t11#0.p" to "Что делать, если на высоте не хочется есть?",
    "q.t11#0.o0" to "Есть активно, малыми порциями и часто, с приоритетом углеводов",
    "q.t11#0.o1" to "Не есть, дождаться аппетита",
    "q.t11#0.o2" to "Пить только горячую воду",
    "q.t11#0.o3" to "Держаться на кофеине",
    "q.t11#0.e" to "На высоте дефицит энергии напрямую замедляет акклиматизацию. Разбить один большой приём на несколько небольших гораздо реальнее, чем заставлять себя съесть целую порцию.",
    "q.t11#1.p" to "Какой самый простой показатель достаточного питья?",
    "q.t11#1.o0" to "Моча остаётся светло-жёлтой",
    "q.t11#1.o1" to "Выпивать ровно 3 литра в день",
    "q.t11#1.o2" to "Отсутствие жажды",
    "q.t11#1.o3" to "Неизменный вес",
    "q.t11#1.e" to "Цвет мочи — самый прямой показатель гидратации. Тёмно-жёлтый говорит о нехватке; полностью прозрачный может означать переизбыток, и тогда стоит добавить электролиты.",
    "q.t11#2.p" to "Какова самая частая причина плохого сна на высоте?",
    "q.t11#2.o0" to "Периодическое дыхание из-за гипоксии, которое раз за разом выбивает из поверхностного сна",
    "q.t11#2.o1" to "Неудобная палатка",
    "q.t11#2.o2" to "Слишком тихо",
    "q.t11#2.o3" to "Мало ходили днём",
    "q.t11#2.e" to "Это физиологично, и тревожиться из-за «недоспал восемь часов» не нужно. Настораживать должна бессонница вместе с головной болью и тошнотой — это может быть AMS.",
    "q.t11#3.p" to "Что помогает спать на высоте лучше?",
    "q.t11#3.o0" to "Не наедаться на ночь",
    "q.t11#3.o1" to "Не пить алкоголь",
    "q.t11#3.o2" to "Умеренно попить перед сном",
    "q.t11#3.o3" to "Принимать ацетазоламид по назначению врача",
    "q.t11#3.e" to "Первые три пункта человек может сделать сам, последний требует оценки врача. Приём лекарств — медицинское решение, его не должны советовать друг другу участники группы.",
    "q.t11#4.p" to "Почему алкоголь на высоте опаснее, чем на равнине?",
    "q.t11#4.o0" to "Он подавляет дыхание, усиливает гипоксию и маскирует симптомы AMS",
    "q.t11#4.o1" to "Он обезвоживает",
    "q.t11#4.o2" to "Он мешает уснуть",
    "q.t11#4.o3" to "Он калорийный",
    "q.t11#4.e" to "На высоте дыхательный драйв и без того ослаблен, и алкоголь подавляет его ещё сильнее. Хуже того, картина опьянения похожа на раннюю стадию HACE, и её легко оценить неверно.",
    "q.t11#5.p" to "Можно ли употреблять кофеин на высоте?",
    "q.t11#5.o0" to "В умеренных количествах можно, но он не заменяет отдых и питьё",
    "q.t11#5.o1" to "Полностью нельзя",
    "q.t11#5.o2" to "Чем больше, тем лучше",
    "q.t11#5.o3" to "Только утром",
    "q.t11#5.e" to "Одна чашка кофе не вызовет горной болезни и не вылечит усталость. При головной боли он немного помогает, но если держаться на нём, проблема просто откладывается.",
    "q.t12#0.p" to "Какая психологическая подготовка важнее всего перед выходом?",
    "q.t12#0.o0" to "Принять, что дойти может не получиться, и включить спуск в план",
    "q.t12#0.o1" to "Решить, что не сдашься ни за что",
    "q.t12#0.o2" to "Написать цель на руке",
    "q.t12#0.o3" to "Не рассказывать близким о маршруте",
    "q.t12#0.e" to "Когда спуск вписан в план, человек останавливается там, где нужно. Если же целью становится «обязан закончить», ради этого часто игнорируют тревожные сигналы.",
    "q.t12#1.p" to "Вы поняли, что не успеваете за темпом группы. Как поступить лучше всего?",
    "q.t12#1.o0" to "Честно сказать и попросить группу идти по скорости самого медленного",
    "q.t12#1.o1" to "Стиснуть зубы и не отставать",
    "q.t12#1.o2" to "Молча отставать",
    "q.t12#1.o3" to "Одному повернуть назад, никому не сказав",
    "q.t12#1.e" to "Если тянуться из последних сил, за несколько часов человек выгорает, и дальше он ошибается и получает травмы чаще. Идти по самому медленному — это и эффективность, и безопасность.",
    "q.t12#2.p" to "Что реально помогает при чувстве открытости и страхе высоты?",
    "q.t12#2.o0" to "Смотреть под ноги по участкам, не вглядываться вдаль",
    "q.t12#2.o1" to "Замедлить дыхание и перенести внимание на движение",
    "q.t12#2.o2" to "Держать три точки опоры и делать движения мельче",
    "q.t12#2.o3" to "Закрыть глаза и быстро проскочить",
    "q.t12#2.e" to "Страх делает дыхание поверхностным, а движения зажатыми, и именно зажатость ведёт к ошибке. Вернуть внимание к «следующей точке постановки ноги» — самый действенный приём.",
    "q.t12#3.p" to "В чём проблема мысли «мы уже столько прошли, нельзя зря»?",
    "q.t12#3.o0" to "Она превращает уже потраченное время в основание рисковать дальше",
    "q.t12#3.o1" to "Она недостаточно позитивна",
    "q.t12#3.o2" to "Из-за неё идут слишком медленно",
    "q.t12#3.o3" to "Проблемы нет",
    "q.t12#3.e" to "Потраченное время не вернётся от продолжения, зато продолжение может принести новую, необратимую цену. Смотреть нужно вперёд, а не назад.",
    "q.t12#4.p" to "О чём группа должна договориться до выхода?",
    "q.t12#4.o0" to "Кто имеет право сказать «стоп», где точка сбора при разделении и через сколько времени запускается план на случай потери связи",
    "q.t12#4.o1" to "Кто фотографирует",
    "q.t12#4.o2" to "Кто идёт быстрее всех",
    "q.t12#4.o3" to "Кто несёт больше всех",
    "q.t12#4.e" to "Когда право сказать «стоп» выдано заранее, а не зависит от личной смелости, человек решается заговорить в нужный момент. То же касается точки сбора и плана на случай потери связи.",
    "q.t12#5.p" to "Настроение внезапно упало, человек не хочет говорить и двигается медленнее. О чём думать в первую очередь?",
    "q.t12#5.o0" to "Возможно, не хватает энергии или воды, а может быть, это раннее проявление горной болезни или переохлаждения",
    "q.t12#5.o1" to "Просто плохое настроение",
    "q.t12#5.o2" to "Особенности характера",
    "q.t12#5.o3" to "Ему нужно побыть одному",
    "q.t12#5.e" to "В поле изменение настроения часто оказывается первым лицом физиологической проблемы. Сначала дать еду, воду, тёплое и оценить состояние, а о настроении говорить потом.",
    "q.t13#0.p" to "Какова рекомендуемая частота точек пополнения на длинном маршруте?",
    "q.t13#0.o0" to "Одна на каждые 3–5 дней",
    "q.t13#0.o1" to "Одна на весь маршрут",
    "q.t13#0.o2" to "Каждый день",
    "q.t13#0.o3" to "Пополнение не нужно",
    "q.t13#0.e" to "Точки пополнения дробят длинный маршрут на отрезки, каждый из которых можно отдельно оценить и с которого можно сойти. При слишком редких точках одна погодная задержка тянет за собой весь маршрут.",
    "q.t13#1.p" to "Каков примерно суточный вес сублимированных продуктов?",
    "q.t13#1.o0" to "600–800 г",
    "q.t13#1.o1" to "200 г",
    "q.t13#1.o2" to "1,5 кг",
    "q.t13#1.o3" to "3 кг",
    "q.t13#1.e" to "600–800 г сублиматов в день дают около 2 500–3 000 ккал. С орехами и масляными смесями общий вес будет чуть выше.",
    "q.t13#2.p" to "Какие правила обязательно уточнить до выхода на длинный маршрут?",
    "q.t13#2.o0" to "Пермит на вход или разрешение охраняемой территории",
    "q.t13#2.o1" to "Разрешён ли открытый огонь",
    "q.t13#2.o2" to "Обязательно ли выносить весь мусор",
    "q.t13#2.o3" to "Можно ли летать на дроне",
    "q.t13#2.e" to "Ни один из пунктов не мелочь: без пермита могут развернуть, костёр в сухой сезон легко даёт пожар, а дроны во многих охраняемых зонах запрещены полностью.",
    "q.t13#3.p" to "Зачем брать с собой наличные?",
    "q.t13#3.o0" to "В горных деревнях, точках пополнения и транспорте часто принимают только наличные, а связи для оплаты может не быть",
    "q.t13#3.o1" to "Чтобы выглядеть профессионально",
    "q.t13#3.o2" to "Чтобы подкладывать под ножку стола",
    "q.t13#3.o3" to "Чтобы удобнее взвешивать",
    "q.t13#3.e" to "Чем глуше место, тем сильнее всё зависит от наличных. Практичнее всего мелкие купюры, а отдельный резерв на случай аварии стоит держать отдельно, не смешивая с текущими расходами.",
    "q.t13#4.p" to "Как подготовить аварийную связь на длинном маршруте?",
    "q.t13#4.o0" to "Спутниковое устройство или аварийный маяк, плюс бумажная карта и план, оставленные контактному лицу",
    "q.t13#4.o1" to "Только телефон",
    "q.t13#4.o2" to "Только свисток",
    "q.t13#4.o3" to "Ничего не нужно",
    "q.t13#4.e" to "На многих длинных маршрутах связи нет вообще. Устройство позволяет отправить сообщение, а карта с планом дают тому, кто остался дома, понимание, куда вы пошли и когда пора звонить в спасательную службу.",
    "q.t13#5.p" to "Что конкретно означает запас 20 % в плане?",
    "q.t13#5.o0" to "Еды, топлива, времени и наличных берут на 20 % больше расчётного",
    "q.t13#5.o1" to "Взять больше только воды",
    "q.t13#5.o2" to "Оставить только время",
    "q.t13#5.o3" to "Запас не нужен",
    "q.t13#5.e" to "Запас — это место для неожиданностей. Задержка на день из-за погоды, лишние две готовки на горелке, дополнительная плата за транспорт не должны сразу ставить поход в тяжёлое положение.",
    "q.t14#0.p" to "Каков основной принцип первой помощи при растяжении связок голеностопа?",
    "q.t14#0.o0" to "Покой, холод, давящая повязка, приподнятое положение (RICE)",
    "q.t14#0.o1" to "Сразу горячее и массаж",
    "q.t14#0.o2" to "Продолжать идти, расходится",
    "q.t14#0.o3" to "Сильно разминать гематому",
    "q.t14#0.e" to "В острой фазе горячее и массаж усиливают кровотечение и отёк. В первые 48 часов применяют холод, давление и приподнятое положение, а нагрузку вводят позже и постепенно.",
    "q.t14#1.p" to "Каков правильный порядок действий при переохлаждении?",
    "q.t14#1.o0" to "Укрыть от ветра, снять мокрое, изолировать от земли, дать горячее питьё в сознании, согревать постепенно",
    "q.t14#1.o1" to "Сначала горячее питьё, потом переодеть",
    "q.t14#1.o2" to "Растирать руки и ноги для кровообращения",
    "q.t14#1.o3" to "Заставить пострадавшего быстро идти, чтобы согрелся",
    "q.t14#1.e" to "Сначала прекращают дальнейшую потерю тепла, потом думают о согревании. Растирание конечностей и принудительная ходьба могут вернуть холодную кровь к ядру и усилить опасность.",
    "q.t14#2.p" to "Что делать в первую очередь при подозрении на тепловой удар?",
    "q.t14#2.o0" to "Быстро перенести в тень и на ветер, расстегнуть одежду и начать физическое охлаждение",
    "q.t14#2.o1" to "Дать много простой воды",
    "q.t14#2.o2" to "Пусть идёт дальше, пропотеет и станет легче",
    "q.t14#2.o3" to "Укрыть одеждой, чтобы не простудился",
    "q.t14#2.e" to "Суть теплового удара — отказ теплоотдачи, поэтому сначала охлаждают, потом восполняют жидкость. При нарушенном сознании поить через силу нельзя: есть риск аспирации.",
    "q.t14#3.p" to "Что обязательно должно быть в сообщении о помощи?",
    "q.t14#3.o0" to "Точное место или координаты",
    "q.t14#3.o1" to "Число людей и характер травм",
    "q.t14#3.o2" to "Имеющееся снаряжение и запасы",
    "q.t14#3.o3" to "Контакты и остаток заряда батареи",
    "q.t14#3.e" to "Спасателям прежде всего нужно знать: где, сколько человек, насколько тяжело и сколько ещё продержитесь. При неполной информации почти всегда уходят часы на уточнения.",
    "q.t14#4.p" to "Как должен быть устроен план на случай потери связи?",
    "q.t14#4.o0" to "Задать контрольное время: через сколько опоздания кто кому звонит и когда обращаются в службу спасения",
    "q.t14#4.o1" to "Разобраться по обстановке",
    "q.t14#4.o2" to "Просто сказать близким примерный район",
    "q.t14#4.o3" to "План не нужен",
    "q.t14#4.e" to "План должен быть привязан ко времени и действию: в такой-то час нет вестей — звоним; ещё через несколько часов — связываемся с местными спасателями. Расплывчатое «если что, звоните» планом не является.",
    "q.t14#5.p" to "В каком случае нужно вызывать помощь, а не справляться своими силами?",
    "q.t14#5.o0" to "Человек не может двигаться сам, сознание изменено или состояние продолжает ухудшаться",
    "q.t14#5.o1" to "Просто немного устал",
    "q.t14#5.o2" to "Обувь натирает",
    "q.t14#5.o3" to "Отставание от плана на два часа",
    "q.t14#5.e" to "Порог для вызова помощи нужно продумать заранее: идёт, в сознании, становится лучше — можно выходить своими силами; не идёт, без сознания, становится хуже — звать помощь как можно раньше.",
    "q.t17#0.p" to "Какой показатель гидратации в походе самый практичный?",
    "q.t17#0.o0" to "Моча остаётся светло-жёлтой",
    "q.t17#0.o1" to "Чувство жажды",
    "q.t17#0.o2" to "Количество пота",
    "q.t17#0.o3" to "Вес тела",
    "q.t17#0.e" to "К моменту появления жажды дефицит уже есть. Цвет мочи — самый дешёвый способ ежедневной самопроверки.",
    "q.t17#1.p" to "Что является ядром диагностики теплового удара?",
    "q.t17#1.o0" to "Температура ядра выше 40 ℃ вместе с изменением сознания",
    "q.t17#1.o1" to "Сильное потоотделение",
    "q.t17#1.o2" to "Покраснение кожи",
    "q.t17#1.o3" to "Учащённый пульс",
    "q.t17#1.e" to "Изменение сознания — ключевой сигнал. Если термометра нет, оценивают по состоянию сознания и сразу начинают охлаждение.",
    "q.t17#2.p" to "Каков правильный порядок действий при перегреве?",
    "q.t17#2.o0" to "В тень, расстегнуть одежду, охлаждать, восполнить электролиты",
    "q.t17#2.o1" to "Сначала жидкость, потом охлаждение",
    "q.t17#2.o2" to "Сначала массаж конечностей",
    "q.t17#2.o3" to "Сначала дать воды",
    "q.t17#2.e" to "Охлаждение в приоритете: жидкости нужно время, чтобы подействовать, а повреждение органов от высокой температуры происходит немедленно.",
    "q.t17#3.p" to "Что делать в первые 48 часов после растяжения голеностопа?",
    "q.t17#3.o0" to "Холод, давящая повязка, приподнятое положение; без горячего и без сильного растирания",
    "q.t17#3.o1" to "Горячее и массаж",
    "q.t17#3.o2" to "Продолжать ходьбу",
    "q.t17#3.o3" to "Энергично разминать гематому",
    "q.t17#3.e" to "В острой фазе горячее и растирание усиливают кровотечение и отёк. Все четыре шага RICE нужны вместе.",
    "q.t17#4.p" to "Что правильно делать, если человек с перегревом без сознания?",
    "q.t17#4.o0" to "Не поить через силу, а охлаждать влажными обёртываниями и как можно быстрее звать помощь",
    "q.t17#4.o1" to "Вливать воду",
    "q.t17#4.o2" to "Давать солевые таблетки",
    "q.t17#4.o3" to "Пусть пьёт сам",
    "q.t17#4.e" to "При ненадёжном глотательном рефлексе питьё попадёт в дыхательные пути. В этой ситуации работают только охлаждение и профессиональная помощь.",
    "q.t17#5.p" to "Как правильно обработать мозоль, если она мешает идти?",
    "q.t17#5.o0" to "Обработать антисептиком, вскрыть с края, оставить покрышку и наложить повязку",
    "q.t17#5.o1" to "Сорвать целиком",
    "q.t17#5.o2" to "Проколоть в центре",
    "q.t17#5.o3" to "Не трогать",
    "q.t17#5.e" to "Оставленная покрышка — лучшая повязка. Прокол в центре легко приводит к разрыву.",
    "q.t17#6.p" to "Что повышает риск перегрева в походе?",
    "q.t17#6.o0" to "Высокая влажность и отсутствие ветра",
    "q.t17#6.o1" to "Непрерывный подъём в полдень",
    "q.t17#6.o2" to "Восполнение только простой воды без электролитов",
    "q.t17#6.o3" to "Светлая дышащая одежда",
    "q.t17#6.e" to "Первые три пункта ослабляют теплоотдачу или нарушают баланс электролитов. Светлая дышащая одежда как раз помогает охлаждаться.",
    "q.t17#7.p" to "Что обязательно должно быть в походной аптечке?",
    "q.t17#7.o0" to "Пластыри и повязки для мозолей",
    "q.t17#7.o1" to "Обезболивающее и жаропонижающее",
    "q.t17#7.o2" to "Эластичный бинт",
    "q.t17#7.o3" to "Антибиотики",
    "q.t17#7.e" to "Первые три закрывают самые частые проблемы похода: ноги, боль, растяжение. Антибиотики требуют решения врача.",
    "q.t17#8.p" to "Расставьте порядок действий при тепловом истощении.",
    "q.t17#8.o0" to "Прекратить движение, перейти в тень",
    "q.t17#8.o1" to "Расстегнуть одежду, начать физическое охлаждение",
    "q.t17#8.o2" to "Дать жидкость с электролитами",
    "q.t17#8.o3" to "Наблюдать за сознанием и состоянием, при необходимости звать помощь",
    "q.t17#8.e" to "Смысл порядка — сначала прекратить тепловое воздействие. Если продолжать идти, тепловое истощение перейдёт в тепловой удар.",
    "q.t17#9.p" to "У партнёра в полдень на подъёме внезапно заболела голова, появились тошнота и влажная холодная кожа. Что делать в первую очередь?",
    "q.t17#9.o0" to "Немедленно остановиться, охлаждать, дать электролиты и наблюдать",
    "q.t17#9.o1" to "Дойти до лагеря",
    "q.t17#9.o2" to "Дать обезболивающее и идти дальше",
    "q.t17#9.o3" to "Велеть одеться теплее",
    "q.t17#9.e" to "Это типичная картина теплового истощения. Продолжение движения быстро ухудшает состояние, а тепловой удар может убить за десятки минут.",
    "q.t18#0.p" to "Какая пара величин важнее всего при оценке возможности брода?",
    "q.t18#0.o0" to "Глубина × скорость течения",
    "q.t18#0.o1" to "Глубина",
    "q.t18#0.o2" to "Ширина реки",
    "q.t18#0.o3" to "Температура воды",
    "q.t18#0.e" to "При той же глубине удвоение скорости удваивает усилие потока. Измерять только глубину — самая частая ошибка в походах.",
    "q.t18#1.p" to "Каков инженерный предел безопасности при переходе вброд?",
    "q.t18#1.o0" to "Глубина × скорость > 1,0 м²/с считается непригодной для брода",
    "q.t18#1.o1" to "Глубина > 0,5 м",
    "q.t18#1.o2" to "Скорость > 3 м/с",
    "q.t18#1.o3" to "Ширина > 20 м",
    "q.t18#1.e" to "1,0 рассчитано на здорового взрослого, короткий переход и лёгкую выкладку. Группа может держать внутренний порог 0,8, но это консервативная практика, а не норматив.",
    "q.t18#2.p" to "Как оценить скорость течения броском ветки?",
    "q.t18#2.o0" to "Если приходится переходить на бег, чтобы не отстать, скорость уже выше пешей",
    "q.t18#2.o1" to "Утонула ли ветка",
    "q.t18#2.o2" to "Вращается ли ветка",
    "q.t18#2.o3" to "Есть ли на воде пена",
    "q.t18#2.e" to "Идти вдоль берега — самый наглядный способ. Если для этого нужно бежать, скорость уже слишком велика.",
    "q.t18#3.p" to "При какой глубине нужно искать другое место?",
    "q.t18#3.o0" to "Выше бедра самого низкого в группе",
    "q.t18#3.o1" to "Выше пояса у руководителя",
    "q.t18#3.o2" to "Выше колена",
    "q.t18#3.o3" to "Выше груди",
    "q.t18#3.e" to "Считают по самому низкому, а не по самому сильному. Группа ограничена самым слабым — это железное правило брода.",
    "q.t18#4.p" to "Что такое зона выноса (run-out)?",
    "q.t18#4.o0" to "Участок ниже по течению, куда поток унесёт человека при срыве",
    "q.t18#4.o1" to "Крутой берег",
    "q.t18#4.o2" to "Уклон дна",
    "q.t18#4.o3" to "Водосбор выше по течению",
    "q.t18#4.e" to "Если в зоне выноса есть водопад, завал или обрыв, это место не годится, даже когда вода на вид мелкая.",
    "q.t18#5.p" to "Какое место для брода искать в первую очередь?",
    "q.t18#5.o0" to "Широкий и мелкий участок",
    "q.t18#5.o1" to "Узкий и глубокий участок",
    "q.t18#5.o2" to "Внешнюю сторону излучины",
    "q.t18#5.o3" to "Рядом с завалом",
    "q.t18#5.e" to "Чем шире русло, тем обычно мельче и спокойнее; на внешней стороне излучины глубоко и быстро, а завал — смертельная ловушка для стопы.",
    "q.t18#6.p" to "Насколько должен подняться уровень воды, чтобы прежде безопасное место стало опасным?",
    "q.t18#6.o0" to "На 15 см",
    "q.t18#6.o1" to "На 1 м",
    "q.t18#6.o2" to "На 50 см",
    "q.t18#6.o3" to "От такого изменения ничего не меняется",
    "q.t18#6.e" to "15 см уже заметно меняют скорость и глубину, особенно на реках ледникового питания.",
    "q.t18#7.p" to "В каких случаях от точки брода нужно сразу отказаться?",
    "q.t18#7.o0" to "Дно не видно, вода мутная",
    "q.t18#7.o1" to "Ниже по течению завал или обрыв",
    "q.t18#7.o2" to "Выше по течению только что прошёл ливень",
    "q.t18#7.o3" to "Дно — пологий галечный пляж",
    "q.t18#7.e" to "Первые три означают «оценить невозможно или ошибку не выдержать». Галечное дно как раз хороший вариант.",
    "q.t18#8.p" to "Что обязательно сделать со снаряжением перед бродом?",
    "q.t18#8.o0" to "Расстегнуть грудную стяжку",
    "q.t18#8.o1" to "Ослабить плечевые лямки",
    "q.t18#8.o2" to "Утянуть наружные крепления, чтобы меньше зачерпывало воду",
    "q.t18#8.o3" to "Убрать телефон и лекарства в гермомешок",
    "q.t18#8.e" to "Первые два пункта нужны, чтобы сбросить рюкзак, последние два — чтобы не потерять важное. Все четыре делают до входа в воду.",
    "q.t18#9.p" to "Расставьте порядок принятия решения о броде.",
    "q.t18#9.o0" to "Сначала спросить: обязательно ли переходить (обход, мост, подождать спад)",
    "q.t18#9.o1" to "Выбрать место и измерить глубину и скорость",
    "q.t18#9.o2" to "Договориться, как вся группа обращается с рюкзаками и одеждой",
    "q.t18#9.o3" to "Перейти в составе группы или по одиночной схеме",
    "q.t18#9.e" to "Первый вопрос снимает большую часть риска. Многие его пропускают и сразу начинают обсуждать, как переходить.",
    "q.t18#10.p" to "Почему днём вода заметно больше, чем утром?",
    "q.t18#10.o0" to "Суточный ход ледникового таяния: максимум приходится на послеполуденные часы",
    "q.t18#10.o1" to "Днём чаще идут дожди",
    "q.t18#10.o2" to "Сброс воды из водохранилища",
    "q.t18#10.o3" to "Испарение",
    "q.t18#10.e" to "У рек ледникового питания суточный ход очень правильный: минимум утром, максимум после полудня. Переправу планируют на первую половину дня.",
    "q.t19#0.p" to "Как правильно строится треугольник при броде?",
    "q.t19#0.o0" to "Трое лицом внутрь, держатся за плечи или рюкзак, движется один человек и одна нога",
    "q.t19#0.o1" to "Трое в ряд, взявшись за руки, идут одновременно",
    "q.t19#0.o2" to "Трое друг за другом в колонну",
    "q.t19#0.o3" to "Двое несут одного",
    "q.t19#0.e" to "Одновременный шаг лишает всю группу опоры сразу. Держаться за руки устаёшь и легко разжать — берут за плечо или рюкзак.",
    "q.t19#1.p" to "Где должен стоять самый сильный в шеренге?",
    "q.t19#1.o0" to "По краям, в первую очередь со стороны течения",
    "q.t19#1.o1" to "В середине",
    "q.t19#1.o2" to "Последним",
    "q.t19#1.o3" to "Где угодно",
    "q.t19#1.e" to "Верхний по течению принимает основной удар потока, нижний подстраховывает. Новичков ставят в середину, по краям — по сильному.",
    "q.t19#2.p" to "Каков ритм команд при движении в группе?",
    "q.t19#2.o0" to "«Шаг, стоп, шаг»",
    "q.t19#2.o1" to "«Раз-два» без остановок",
    "q.t19#2.o2" to "Без разговоров",
    "q.t19#2.o3" to "Каждый идёт сам",
    "q.t19#2.e" to "Единый ритм нужен, чтобы в каждый момент двигался только один человек. Одновременный шаг — самая частая ошибка группы.",
    "q.t19#3.p" to "Каково первое правило после падения в воду?",
    "q.t19#3.o0" to "Не вставать",
    "q.t19#3.o1" to "Немедленно встать",
    "q.t19#3.o2" to "Схватиться за верёвку",
    "q.t19#3.o3" to "Схватиться за бревно",
    "q.t19#3.e" to "Стопа может застрять в камнях или завале, и поток прижмёт человека под воду — это и есть заклинивание стопы, самая типичная причина гибели на броде.",
    "q.t19#4.p" to "Каково правильное положение после падения?",
    "q.t19#4.o0" to "На спине, ногами вниз по течению и ближе к поверхности, голова поднята",
    "q.t19#4.o1" to "Плыть лицом вниз",
    "q.t19#4.o2" to "Держаться вертикально, работая ногами",
    "q.t19#4.o3" to "Подтянуть колени к груди",
    "q.t19#4.e" to "На спине и ногами вперёд можно отталкиваться от препятствий, а не упираться в дно, и при этом защищена голова.",
    "q.t19#5.p" to "Что верно про поясной ремень рюкзака при броде?",
    "q.t19#5.o0" to "Американская школа советует расстёгивать, чтобы сбросить рюкзак, новозеландская MSC — застёгивать для плавучести; главное — единообразие в группе",
    "q.t19#5.o1" to "Обязательно расстегнуть",
    "q.t19#5.o2" to "Обязательно застегнуть",
