    "q.t19#7.e" to "Плавучесть рюкзака помогает, но при неверном порядке теряется опора. Сначала пояс, затем лямка со стороны течения — стандартный порядок.",
    "q.t19#8.p" to "Что входит в подготовку к переходу в группе?",
